import{_ as r,O as i,o,c as d,a as s,i as a,f as l}from"./chunks/framework.fmIt2z2h.js";const b=JSON.parse('{"title":"第八部分　人类状态原型","description":"","frontmatter":{"title":"第八部分　人类状态原型","xkChars":8722,"xkLessons":{"intro-08-part":{"title":"第八部分　人类状态原型","lead":"这一部分提供一组描述集体状态的候选原型。读它时，先问对象与证据，再问哪张卡适合；不要把编号读成成长分数。","explanation":["原文定位：第1627—1628行；原文锚点 part_8；短引文：‘人类状态原型’。本题源切片逐字附后，讲解与原文分开。","本独立导语在原文只有分部标题，没有另附论证。这里的阅读路线依据紧随其后的§8.1—8.8展开，不把后文内容伪装成标题自身已经证明的事实。第七部分提供人类变量接口，本部分进一步讨论这些变量在某个集体、子系统与窗口中形成什么候选构型。","§8.1先划适用域和非授权边界；§8.2冻结对象、K、九轴和窗口，登记可复核分类；§8.3逐张展开S0—S6；§8.4保留混合、并行、回退、跳跃等非线性路径；§8.5单列X0退场转换；§8.6处理调节、预警与承接；§8.7—8.8说明原型的有限性及它与个人状态、多圈层推演的边界。目录顺序是阅读安排，不是任何集体必经的历史过程。","原型卡解决“在给定条件下如何描述”而非自动解决“为什么造成”“是否正当”或“应如何干预”。要升级到机制说明，需相应通道和G实例；要进入现实采用，需另有规范前提、C12、J及O程序。原型字段完整也不证明此分类可靠、优于专业描述或产生预测收益，这些要实际比较。","本部分不是穷尽一切人类集体的字典。资料不足可以unknown，局部已成立事实仍保留；对象持续不合原型应保留残差，不硬塞编号。如果直接记录成员、通道、负荷已能完成任务，可以跳过原型，避免为形式完整增加无用标签。"],"distinctions":[{"leftTitle":"阅读顺序","leftText":"便于理解本部分怎样组织问题。","rightTitle":"历史必经顺序","rightText":"关于真实集体必须依次经历什么，需要另外证据，原文不主张。"},{"leftTitle":"原型可复核","leftText":"条件和反证可追查。","rightTitle":"分类已可靠有效","rightText":"还需观察者一致性、稳定性与实际使用比较。"},{"leftTitle":"未知","leftText":"现有材料不足以分型。","rightTitle":"没有任何事实","rightText":"局部直接材料仍可有用，不应删除。"}],"boundaries":["导语只有标题，不能单据标题推导经验规律。","七种原型不等于穷尽状态，也不按编号给人或制度排序。","清楚的图卡不等于实际教学效果、分类准确率或使用收益已经验证。"],"questions":["任务只问一个接口何时中断，是否必须先判整体S原型？","为何S5编号比S1大不能推出更正当？","原型不匹配的案例应怎么办？"],"diagramPath":"/reading-assets/S-8-1/figures/intro-08-part.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"intro-08-part","start_line":1627,"end_line":1628,"startLine":1627,"endLine":1628}],"outputId":"intro-08-part","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先承认导语本身是标题，路线解释准确回指后续各节。","按适用域、最小合同、原型、路径、退出与边界顺序阅读，不当时间阶梯。","每次分清描述、机制、规范和行动四种任务。","未知保留材料，不能用标签填补缺口；原型无增益时允许直接变量描述。"],"teachingExamples":[{"title":"形式构造：改名不改变事实，编号不是天然数值","text":"设两张原型卡标签为S1和S5，卡中条件及对象材料都保持不变。若仅把它们的检索码改为甲卡与乙卡，材料支持关系不变。原来“5比1大”这一算术事实不能因此成为“乙更正当”的证据，因为检索码并未定义价值函数。","assumptions":"只是名称置换的形式构造；实际交付仍使用原书编号，不改原文标签。","boundary":"说明名义标识不自带度量，不证明任意两真实制度具有相同价值。"},{"title":"教学构造：不分类也可以回答局部问题","text":"虚构任务只问本周哪个服务接口中断，已有可核输入输出与中断时点，但缺完整原型入口和反证材料。可直接说明该接口在该窗口的事实，整体原型保持unknown；不必先给组织分S级才允许报告。","assumptions":"假设局部记录质量足以支持这一有限问题；其他范围未知。","boundary":"不把未分类等同于失败，也不绕过实际处置所需权限。"}],"counterexamples":[{"identity":"constructed_boundary","text":"章节先讲S0后讲S6，所以所有组织必从0走到6。","effect":"把文档顺序误读成历史必经规律。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"卡片写得清楚，所以读者使用它一定更准确更快。","effect":"形式可读性不替代真实比较或教学测试。","sourceIds":["theory"]}],"questionAnswers":[{"question":"任务只问一个接口何时中断，是否必须先判整体S原型？","answer":"不必；可以直接用变量回答，整体原型缺证保持未知。","basis":"本节原文及上述公开推导"},{"question":"为何S5编号比S1大不能推出更正当？","answer":"编号没有定义价值量，正当性需规范与具体证据。","basis":"本节原文及上述公开推导"},{"question":"原型不匹配的案例应怎么办？","answer":"保留材料和未解释残差，按独立研究考虑修订原型，而不是硬塞或删除案例。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-1/figures/intro-08-part.png","alt":"8.1 适用与上限，人类意向性集体，描述不自动授权；8.2 最小合同，对象／K／尺度／窗口，证据与缺失；8.3 七种原型，逐卡条件与反证，编号只是检索；8.4 非线性路径，混合／并行／回退等，不强制单一路径；8.5—8.6，X0独立转换，调节／预警／承接；8.7—8.8 边界，不穷尽，不套人格，无增益可跳过原型。六卡按主题组织阅读，没有把它们画成真实集体必须经历的六个阶段。","caption":"六卡按主题组织阅读，没有把它们画成真实集体必须经历的六个阶段。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。导航卡说明各节职责；原文导语只有标题，具体解释回指本部分后续节。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"分部标题是导航与适用边界，名称置换和局部问题构造足以解释；不把真实组织强贴原型当作目录的证据。"},"openQuestions":[],"taskId":"S-8-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1627—1636行；每节精确范围见sourceRefs","claim_support":["intro-08-part：术语、合同、论证责任和原文边界；不据此认证经验事实","8.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"roadmap","title":"现行原文第八部分全部节的职责","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.1—8.8，第1629—1868行","claim_support":["分部导语：本部分阅读路线与各节职责；原导语本身仅标题"],"limits":["目录组织不是现实集体的时间规律，不作为经验支持。"],"access_status":"read"},{"id":"HV10","title":"现行原文HV10适用与接口记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§7.3.10第1586—1589行；附录A10第4162—4227行","claim_support":["8.1：形成期不要求四组件先成熟；接口评估可含缺失；原型与相位机制区分"],"limits":["条件检查不为真实对象赋原型。"],"access_status":"read"},{"id":"modes","title":"现行原文分类模式及非线性路径","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2第1639—1652行；§8.4第1787—1810行，mixed与parallel两行","claim_support":["8.1：parallel对应可稳定映射的不同子系统；mixed同对象尺度窗口中多种必要特征共同出现；unknown不冒充混合"],"limits":["教学构造假定条件给定，现实仍须逐项证据。"],"access_status":"read"},{"id":"limits","title":"现行原文原型的有限用途","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.7—8.8，第1849—1868行","claim_support":["分部导语及8.1：不穷尽、不直接套人格；分类可靠性与使用增益需实际比较；允许跳过原型"],"limits":["未报告任何未经实施的准确率、预测或读者测试。"],"access_status":"read"},{"id":"C12J","title":"现行原文规范桥接与J原子授权","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.14.1第908—924行；§5.2第1055行","claim_support":["8.1：描述分类不自动产生干预权限，显式规范、方案比较、J和O程序另核"],"limits":["框架程序不替代现实授权，也不构成法律意见。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-1/lecture.md","sourcesPath":"/reading-assets/S-8-1/sources.json","sourceSlicePath":"/reading-assets/S-8-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-1/diagrams.md"},"8.1":{"title":"8.1　本部分解释什么","lead":"同一个集体的中心、边缘和不同功能单元，可以同时呈现不同构型。8.1允许把差异留下来，不用一个总阶段把人和位置都压平。","explanation":["原文定位：第1629—1636行；原文锚点 section-8-1；短引文：‘不是成熟度阶梯’。本题源切片逐字附后，讲解与原文分开。","S0—S6适用于人类有意图集体：人们围绕可表达的共同问题、承诺、目标或意义安排形成，并通过角色、资源、规则、关系及反馈运作。可涉及团队、组织、机构、运动、共同体和治理安排。正在形成时组件尚未成熟可以登记缺口，不因需要检查这些面向就要求先全部成熟；具体原型入口仍须自身材料。","这些原型不能直接套个人人格、纯物理系统、物种演化或宇宙整体。某装置有稳定反馈，不因此是S6集体；某个人反应迅速，也不因此处于更高阶段。大型集体中的“技术单元”若要使用本组原型，所指应是有意向与组织安排的人类工作单元，而非仅凭机器性能把纯技术系统拟人化。","编号只区分原型，所问是特定对象、子系统与时间窗的结构构型。编号更大不能推出人更好、制度更正当或文明更先进；规模更大、维持更久，也不是自动支持某个较大编号的依据。原型是描述性的、可撤回的分类，不是价值排名或历史必经序列。","原文举出一个大型集体中中心S5、边缘S3、技术单元S6、代际承接S1可以并存的可能情形。此处是条件化结构示例，不是已经调查过的真实组织。若不同地域、层级或功能的差异能稳定映射到独立子系统，登记parallel并各保留K与证据；若同一对象、尺度和窗口内多种原型的必要特征共同出现而不能这样分开，登记mixed。两种状态均需正面材料，不把无知改名为复杂性。","状态标签不授予干预权限。现实行动应明确规范前提，通过C12，比较包含不行动的方案，取得覆盖来源、主体、单一对象、单一动作、地域、期限、撤回与有效性的J原子授权，再按O程序接受监测、停止、申诉及回滚。原型支持不能替这些门作证；即使分类后来撤回，也应保留证据与版本。","这里的边界并不禁止任何价值讨论，也不否定对危害的直接观察。它只要求价值与行动各有明确根据。某子系统已观察到过载或排除，应按自己的证据报告；不能因为整体原型未知而隐去这些事实，也不能仅凭S名称对成员作处置。"],"distinctions":[{"leftTitle":"人类技术工作单元","leftText":"有成员、意向、角色与资源安排的集体。","rightTitle":"纯技术装置","rightText":"仅有反馈或稳定功能不能取得人类原型资格。"},{"leftTitle":"parallel","leftText":"差异对应不同子系统、地域、层级或功能。","rightTitle":"mixed","rightText":"同一对象、尺度和窗口内多种必要特征共同出现。"},{"leftTitle":"编号","leftText":"用于识别和检索原型。","rightTitle":"成熟度或正当性数值","rightText":"本部分没有把编号定义为这类度量。"},{"leftTitle":"可撤回分类","leftText":"证据支持的限定描述。","rightTitle":"行动授权","rightText":"具体N、C12、J和O程序另核。"}],"boundaries":["同一功能可呈多种原型，但须实际支持；资料少不等于mixed。","子系统差异不能被一个加权“总阶段”抹掉。","人类集体的描述不直接作用于每个成员人格，也不把纯物理对象拟人化。","分类错误的纠正要保留原证据、异议和版本链，不靠抹掉旧记录实现。"],"questions":["四子系统代码平均3.75有何问题？","何时应记parallel而不是mixed？","一个恒温器有稳态反馈，是否可直接判S6？","缺原型材料时还能报告已观察到的局部危害吗？"],"diagramPath":"/reading-assets/S-8-1/figures/section-8-1.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"8.1","start_line":1629,"end_line":1636,"startLine":1629,"endLine":1636}],"outputId":"section-8-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["确认对象是人类意向性集体，记录形成与运作证据和组件缺口。","固定子系统与窗口，逐原型核条件，不从编号或规模判高低。","有多个正面支持时，判断可否稳定分解到独立子系统：能则parallel，否则按同域特征检查mixed。","若缺关键材料，只保留unknown与已支持局部事实。","现实采用另核规范、方案、J原子授权和O程序，不以状态标签代证。"],"teachingExamples":[{"title":"数学构造：原型代码不能求有意义的平均阶段","text":"沿原文可能情形，虚构四个已分别按完整合同得到有限支持的子系统标签为S5、S3、S6、S1。直接平均代码得(5+3+6+1)/4=3.75，但书中没有S3.75，也没有把代码间距定义为等距量。若仅重命名检索码，平均数还会变，而各子系统材料不变。因此应保留对应位置及标签，不把3.75当整体成熟度。","assumptions":"这是以“各子系统条件均已独立满足”为前提的演示；本讲没有完成任何真实对象的原型分类。","boundary":"不禁止对有明确单位的其他指标求均值；仅否定把名义原型代码当等距成熟度。"},{"title":"分类边界构造：并行、混合与未知三种不同理由","text":"虚构对象甲的两个独立功能单元分别有充分S2与S4材料，可讨论parallel；对象乙在同一功能、尺度和窗口中有两原型必要特征共同出现，且不能稳定拆成独立子系统，可讨论mixed；对象丙只有口号和一张名单，关键入口与反证缺失，应保持unknown。","assumptions":"原型支持作为条件给定，用于解释分类模式，不替代§8.2—8.3的实际逐项核验。","boundary":"不能把复杂叙事或缺证都贴成mixed，也不能把一个人的两种行为当集体并行相位。"}],"counterexamples":[{"identity":"constructed_boundary","text":"中心表现稳定，所以边缘成员也都应被赋同一原型或人格等级。","effect":"中心材料不覆盖边缘，集体标签也不覆盖个人人格。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"不知哪种原型更合适，就填mixed。","effect":"mixed需要多个原型的正向材料；关键缺失应记unknown。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"某集体被判S1，所以可以直接要求其升级。","effect":"描述不提供正向目标、方案比较或具体行动授权。","sourceIds":["theory"]}],"questionAnswers":[{"question":"四子系统代码平均3.75有何问题？","answer":"代码是名义标识，未定义等距度量；平均不能表示原型或成熟度，且会随纯重命名改变。","basis":"本节原文及上述公开推导"},{"question":"何时应记parallel而不是mixed？","answer":"差异能够稳定映射到独立子系统或不同地域、层级、功能时，保留各自对象与证据。","basis":"本节原文及上述公开推导"},{"question":"一个恒温器有稳态反馈，是否可直接判S6？","answer":"不能，纯技术装置不因稳定反馈获得人类意向性集体原型资格。","basis":"本节原文及上述公开推导"},{"question":"缺原型材料时还能报告已观察到的局部危害吗？","answer":"能，局部事实按独立证据范围保留，不能因总体unknown而删除。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-1/figures/section-8-1.png","alt":"虚构中心，有限支持S5，保留其窗口与证据；虚构边缘，有限支持S3，不被中心材料替代；人类技术单元，有限支持S6，不是纯装置评级；代际承接面向，有限支持S1，仍有自己的条件；可分独立子系统，登记parallel，不算整体3.75阶段；描述性／可撤回，不作价值和人格排序，行动授权始终另核。标签沿原文可能情形构造，未对任何真实组织认证；每个支持前提均须另有完整材料。","caption":"标签沿原文可能情形构造，未对任何真实组织认证；每个支持前提均须另有完整材料。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。四个位置卡与两张解释卡保留并行差异；没有上升阶梯或平均阶段。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节主要限定形式分类的适用对象、模式与非授权边界；没有可满足全部原型合同的现实案例材料，因此使用明确条件构造，不将历史组织事后授予S级。"},"openQuestions":[],"taskId":"S-8-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1627—1636行；每节精确范围见sourceRefs","claim_support":["intro-08-part：术语、合同、论证责任和原文边界；不据此认证经验事实","8.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"roadmap","title":"现行原文第八部分全部节的职责","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.1—8.8，第1629—1868行","claim_support":["分部导语：本部分阅读路线与各节职责；原导语本身仅标题"],"limits":["目录组织不是现实集体的时间规律，不作为经验支持。"],"access_status":"read"},{"id":"HV10","title":"现行原文HV10适用与接口记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§7.3.10第1586—1589行；附录A10第4162—4227行","claim_support":["8.1：形成期不要求四组件先成熟；接口评估可含缺失；原型与相位机制区分"],"limits":["条件检查不为真实对象赋原型。"],"access_status":"read"},{"id":"modes","title":"现行原文分类模式及非线性路径","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2第1639—1652行；§8.4第1787—1810行，mixed与parallel两行","claim_support":["8.1：parallel对应可稳定映射的不同子系统；mixed同对象尺度窗口中多种必要特征共同出现；unknown不冒充混合"],"limits":["教学构造假定条件给定，现实仍须逐项证据。"],"access_status":"read"},{"id":"limits","title":"现行原文原型的有限用途","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.7—8.8，第1849—1868行","claim_support":["分部导语及8.1：不穷尽、不直接套人格；分类可靠性与使用增益需实际比较；允许跳过原型"],"limits":["未报告任何未经实施的准确率、预测或读者测试。"],"access_status":"read"},{"id":"C12J","title":"现行原文规范桥接与J原子授权","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.14.1第908—924行；§5.2第1055行","claim_support":["8.1：描述分类不自动产生干预权限，显式规范、方案比较、J和O程序另核"],"limits":["框架程序不替代现实授权，也不构成法律意见。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-1/lecture.md","sourcesPath":"/reading-assets/S-8-1/sources.json","sourceSlicePath":"/reading-assets/S-8-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-1/diagrams.md"},"8.2":{"title":"8.2　状态判断的最小合同","lead":"给集体贴一个状态标签之前，先说清在追踪谁、用什么身份判据、观察哪里和多久。合同固定的是分析尺子，不是要求真实世界停止变化。","explanation":["原文定位：第1637—1653行；原文锚点 section-8-2；短引文：‘不要求被观察的成员构成、实际边界、角色、承诺或自我认同已经稳定’。本题源切片逐字附后，讲解与原文分开。","每次判断先冻结object_id、同一性判据K、九轴SP、时间窗与子系统范围。K是用来追踪是否同一对象的判据，不是整个对象合同。冻结给比较提供固定依据，仍须检查实际观察是否照此执行，以及变化后判据是否继续适用。名称相同不自动证明同一对象，成员变化也不自动证明对象已换。","原文专门允许形成中的成员、实际边界、角色、承诺及自我认同变化。若对象继续满足原K、判据本身亦适用，且交接和身份可追踪，这些可成为同一对象的状态变化；若确须改K定义，应新建版本，保留旧判据、旧材料与旧判断，重新核对同一性。未核清前，不将不同K下的两份记录拼成同一对象的跨窗路径。","最小合同的八个检查面分别有停止点：对象与K不清先停原型分配；尺度时间不足不能越覆盖；入口退出不明不把“像”当成立；可观察量不能只靠口号、总量或自述；反例证伪必须主动检查；外部证据须能解析并覆盖当前对象；缺失要分类保留；规范行动一律只到描述且无授权。八项不是可互相抵消的评分。","分类模式只有single_dominant、mixed、parallel、unknown。一个主导原型须对应其证据；mixed与parallel均需要多个原型正向支持，且分别说明同域共同特征或不同子系统位置。关键入口、反证或尺度缺失只支持unknown或暂停相关分类，不能为了显得全面把缺证改叫“混合”。已成立局部事实仍在其原范围保留。","五种缺失须分开：not_collected是可取得但未收集；not_observable是在当前权限、安全或测量条件下不可观察，不强迫当事人暴露；not_applicable须经过适用性判断；conflicted是合格来源互相冲突；unknown是已经尝试仍不能区分。未收集不是零，受保护不可得不是“不存在”，冲突也不适合用一个无依据平均数掩盖。","所有状态的normative_status恒为descriptive_only，action_authorization恒为none。更大观察范围不增加J权限，分类成立也不支持价值、义务或处置权。后面的运行时记录把这些要求变成逐项可追查结构；结构有效仍不认证原型事实真实性。"],"distinctions":[{"leftTitle":"冻结K","leftText":"固定本次怎样判断同一对象。","rightTitle":"冻结实际成员","rightText":"要求所有人员和边界不变，原文没有这个要求。"},{"leftTitle":"状态变化","leftText":"同一判据下对象的某些状态不同。","rightTitle":"对象身份转换","rightText":"须另核对象是否继续满足原K、判据本身是否适用，不能仅看名称或人数。"},{"leftTitle":"not_collected","leftText":"材料可取得但尚未收集。","rightTitle":"not_observable","rightText":"当前权限、安全或测量条件不允许观察，不能强制填补。"},{"leftTitle":"mixed或parallel","leftText":"有多个原型及位置的正面材料。","rightTitle":"unknown","rightText":"材料不足以区分，不能通过改名升级支持。"}],"boundaries":["分析冻结不是执行保证，应检查偏离及真实适用性。","没有同一性判断就不能把不同K记录拼成轨迹。","受保护不可观察不成为要求弱势者公开敏感信息的理由。","相互冲突的来源应保留版本与差异，不凭平均制造一致。","描述分类无论多确定，都不会自行改变action_authorization=none。"],"questions":["固定K以后，是否禁止集体成员退出和加入？","新K更合理，能直接覆盖旧K并连接两窗吗？","因安全无法询问当事人，应记未收集还是不可观察？","总体unknown是否需要删除已核的任务日志？"],"diagramPath":"/reading-assets/S-8-2/figures/section-8-2.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"8.2","start_line":1637,"end_line":1653,"startLine":1637,"endLine":1653}],"outputId":"section-8-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["冻结对象、K、九轴、窗口和子系统，并记录所据材料与版本。","核对象是否可在固定K下追踪；必要改变K时另建版本并重核身份。","逐项核入口、退出、可观察量、反例、证伪及外部证据，不用总评代替。","明确五类缺失与它影响的判断，禁止填为零或把无知称混合。","选择由正面材料支持的模式，保留局部事实和不确定性。","把描述性与无行动授权写明，任何实际行动另过其规范和授权条件。"],"teachingExamples":[{"title":"集合与身份构造：成员改变并不自动改变K","text":"虚构项目在本模型的K规定为“同一项目标识及连续可核的任务交接链”。t0成员M0={甲,乙}，t1成员M1={乙,丙}，若标识与交接链确实连续，成员变化可在同一K下记录。若分析者后来改用K2=成员名单完全相同，则M0与M1不满足K2；不能把K1下t0和K2下t1不经核对拼成同一身份轨迹。","assumptions":"这是明确约定K的形式模型，不声称真实集体只需标识即可证明同一；其余合同与材料在实际应用须完整。","boundary":"判据可被合理修订，但修订不允许抹掉旧版本或自动跨接。"},{"title":"教学构造：五个空格有五种不同原因","text":"虚构记录中，已存在却尚未读取的日志标not_collected；因安全与权限不能访问的私人陈述标not_observable；经检查该功能从未涉及的问题标not_applicable；两份合格记录对同一时点给出不相容结果标conflicted；已经核了可用材料仍无法区分两种机制标unknown。不能把五者全部填“0”。","assumptions":"例子只解释缺失语义，不涉及真实私人资料获取，也不让“不涉及”由分析者随意声称。","boundary":"缺失类型正确仍不保证关键条件已经满足。"}],"counterexamples":[{"identity":"constructed_boundary","text":"成员从甲乙变成乙丙，所以无论K怎么定都必须是新对象。","effect":"把状态变化与同一性判据混为一谈；需要实际核验对象是否继续满足原K及该判据是否仍适用。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"缺少反证材料，填mixed比较稳妥。","effect":"mixed需要正面支持多个原型，缺证应unknown或暂停。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"两个来源冲突，取平均就能当作精确状态。","effect":"平均需要本来就有合理测量模型，不能自动消除来源冲突。","sourceIds":["theory"]}],"questionAnswers":[{"question":"固定K以后，是否禁止集体成员退出和加入？","answer":"不禁止；固定的是分析判据，成员与实际边界可以在可追踪对象中变化。","basis":"本节原文及上述公开推导"},{"question":"新K更合理，能直接覆盖旧K并连接两窗吗？","answer":"不能；另建版本、保留旧材料并重核同一性，未核完不拼跨窗路径。","basis":"本节原文及上述公开推导"},{"question":"因安全无法询问当事人，应记未收集还是不可观察？","answer":"按本例当前安全与权限限制，应记not_observable及理由，不以填表为由迫使暴露。","basis":"本节原文及上述公开推导"},{"question":"总体unknown是否需要删除已核的任务日志？","answer":"不需要，局部事实按原范围保留，只是不由它们伪造完整原型。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-2/figures/section-8-2.png","alt":"先冻结，object_id／K／SP，窗口／子系统；实际状态可变，成员／边界／角色，仍须按K追踪；若要改K，新版本＋旧材料保留，重核前不拼轨迹；逐项材料，入口／退出／观察，反例／证伪／覆盖；五种缺失，未收／不可观／不适用，冲突／已查仍未知；分类与上限，缺证不冒充混合，描述性且不授权。冻结不保证执行；成员变化不自动等于K改变，未知也不等于零或混合。","caption":"冻结不保证执行；成员变化不自动等于K改变，未知也不等于零或混合。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上排解释判据与对象变化的区别，下排说明分类材料和缺失边界；没有对真实集体赋值。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"最小合同与缺失语义属于形式分类规范，使用身份与记录构造直接解释；没有对现实集体作缺证分级。"},"openQuestions":[],"taskId":"S-8-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1637—1665行；每节精确范围见sourceRefs","claim_support":["8.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.2.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"D0","title":"现行原文对象合同与同一性","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.1第425—448行","claim_support":["8.2：K只是同一性判据，与完整合同及实际状态变化区分"],"limits":["教学K约定不是现实集体身份的充分测量方案。"],"access_status":"read"},{"id":"SP","title":"现行原文九轴状态","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§5.2第1039—1059行","claim_support":["8.2：逐轴适用性、未知与不可相互替代，观察扩大不扩大J"],"limits":["不把字段填写当事实认证。"],"access_status":"read"},{"id":"S2","title":"现行原文S2原型卡","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.3.3，第1702—1718行，S2-O1及证伪行","claim_support":["8.2.1教学片段：S2-O1进入/退出和接口变化；中心单方标签分化的证伪阻断"],"limits":["demo_log为教学占位，不是真实证据，也不是完整运行记录。"],"access_status":"read"},{"id":"modes","title":"现行原文混合与并行路径","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行，mixed、parallel行","claim_support":["8.2：多原型正面支持和对应位置，而非缺失即混合"],"limits":["案例不满足材料时保持未知。"],"access_status":"read"},{"id":"phase","title":"现行原文原型与相位机制界线","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§7.3.10第1586—1589行；§8.2.1第1662—1664行","claim_support":["8.2.1：U/H/G/C只是合同链接；单窗原型描述不统一硬需CM-PHASE，机制另加相应条件"],"limits":["不省略各具体原型本身的时间要求。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-2/lecture.md","sourcesPath":"/reading-assets/S-8-2/sources.json","sourceSlicePath":"/reading-assets/S-8-2/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-2/diagrams.md"},"8.2.1":{"title":"8.2.1　运行时分类记录","lead":"可复核分类要让别人顺着每一个判断找到真正材料，而不是只看到“已检查”三个字。运行时记录把原型、条件、证据和复核关系连接起来，也把失效点暴露出来。","explanation":["原文定位：第1654—1665行；原文锚点 section-8-2-1；短引文：‘内部编号、定义和自报判断不能替代对象证据’。本题源切片逐字附后，讲解与原文分开。","“封闭的运行时记录”指本次判断的对象、版本、候选、引用和程序关系明确可核，不是禁止申诉或冻结以后永不改判。它同时固定record_id、对象与K、九轴、时间窗、子系统、分类模式、候选状态、路径候选、五类条件结果、缺失、对象证据、不确定性、独立复核、申诉、回滚及非授权边界。","入口、退出、观察、反例和证伪每一项都使用item_id + state_id + status + evidence_refs + reason。item_id定位具体检查项，state_id指向所评原型，status报告该项实际结果，evidence_refs指向材料，reason解释材料为何支持这个结果。一个原型的入口与观察至少须有对象证据；逐项覆盖候选，不能用“整体看起来合适”替代。","single_dominant恰有一个候选；mixed和parallel至少两个且显式登记相应路径。unknown不指定已获支持的原型，要说明关键材料不足。如果记录格式不容许unknown候选条件栏存支持项，把已成立局部材料保留在对象证据及理由中；不能为了存一个局部事实就伪造整张原型已支持。","反例检查提供竞争表象，证伪项则规定何种结果阻断候选。任一证伪项为supported，该候选即被阻断，不能把名字改成“弱S2”“可能S2”绕过同一失败条件。可以保留已观察事实、改查其他适合候选或总体unknown，但不把反证软化成自动通过。","每次验证另提供外部evidence_ids注册表。记录中每一层evidence_refs都须解析到本记录的对象证据，并递归解析到该外部表；嵌套入口、反例或复核位置不能只查顶层。编号能找到只是引用一致性，仍须核来源内容、对象、窗口、测量口径和支持上限；往注册表添加一个空名字不能使幽灵证据变真。外部表也不意味着各条来源统计独立，同源关系须保留。","复核者记录须含reviewer_id、independent、reviewed_at、material_version和outcome，申诉与回滚各绑定结构化程序ID及状态。reviewer_id经NFKC、首尾空白与大小写规范化后不能等于对象ID，也不能用对象ID派生别名冒充他者；字符串不同是必要防错，不是实际独立的充分证明，还要核人员、职责与原决策链关系。","复核无论支持还是反对，normative_status始终descriptive_only，action_authorization始终none。撤回或改写标签须保留原材料、异议和版本链，不为显示“已纠正”删除证据史。申诉可达与回滚执行也需实际状态，而非“可申诉”“已复核”的自报字符串。","U、H、G、C在这里分别提供对象状态接口、人类意义承接等适配、何时升级到经验机制的实例责任、推论停止边界。它们是合同链接，不是眼前对象证据。原型描述不统一以CM-PHASE多区间为前提：单一观察窗若符合该原型自身必要条件，可得有限分类，但不证明已发生相位转移；相反，两区间形式模式也不直接证明符合某个人类原型。"],"distinctions":[{"leftTitle":"引用解析成功","leftText":"ID能到达登记材料。","rightTitle":"证据实际支持","rightText":"还需内容、对象、窗口与主张相符，不能以ID代真值。"},{"leftTitle":"不同reviewer_id","leftText":"通过部分形式身份检查。","rightTitle":"独立复核","rightText":"真实人员和决策依赖需核，换名不足。"},{"leftTitle":"反例待检查","leftText":"某种不同机制可能造成表象。","rightTitle":"证伪项已支持","rightText":"该候选被阻断，不能靠弱化措辞继续。"},{"leftTitle":"原型配置描述","leftText":"按具体卡条件作有限分类。","rightTitle":"CM-PHASE模式或机制","rightText":"另需多区间、阈值与相应实例，双方不自动互证。"}],"boundaries":["内部理论编号不是对象证据，框架自报不能补缺。","注册表齐全不保证每条来源独立，也不保证内容真实。","unknown可以保留局部支持材料，不能为填结构强造候选。","证伪已支持就阻断该候选，不把它降格包装后继续同一分类。","复核通过不改变action_authorization=none。"],"questions":["E含e2但外部R不含e2，引用能通过吗？","为何一个S2-O1观察supported不能让整张S2成立？","复核ID不同就独立吗？","只有一个观察窗口是否必不能作原型描述？","某候选证伪项supported，应该如何处理？"],"diagramPath":"/reading-assets/S-8-2/figures/section-8-2-1.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"8.2.1","start_line":1654,"end_line":1665,"startLine":1654,"endLine":1665}],"outputId":"section-8-2-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["冻结完整记录范围，并为每个候选逐项登记五类条件的五字段结果。","检查模式与候选数量、路径及unknown保留事实方式一致。","检查任何已支持证伪项并阻断对应候选，不靠改弱措辞保留。","递归收集所有引用，核对象证据与外部注册表两层解析，再核源内容的实际支持。","核独立复核者实质身份、规范化标识、材料版本和结果，申诉回滚有结构化程序状态。","保留描述性与无授权边界，区分原型配置、机制升级和实际处置。"],"teachingExamples":[{"title":"集合构造：本地引用可查仍可能缺外部依据","text":"虚构记录对象证据ID集合E={e1,e2}，外部注册表R={e1,e3}，所有层引用集合F={e1,e2}。虽然F是E的子集，但F不是R的子集，e2无法解析到外部依据，因此记录未满足要求。正确补法是取得并登记相应真实可核材料，或按实际缺口改写受影响判断；只在R添字符串e2不能证明事实。","assumptions":"e1—e3只是教学符号，没有对应真实对象来源；模型不声称这是一份完整可验证的运行记录。","boundary":"说明两层覆盖条件，不以形式集合包含认证内容真实性。"},{"title":"教学片段：一项观察不能替整张卡结案","text":"虚构S2观察片段可写item_id=S2-O1、state_id=S2、status=supported、evidence_refs=[demo_log]、reason=“指定窗口内，成员甲退出、成员乙进入，服务接口由单入口改为两个入口；变化前后构成与时间记录均可核”。这五格只定位一项观察。即便demo_log确实存在，还要查S2两入口、其他观察、反例与证伪；若“分化只来自中心单方标签”的证伪项被支持，S2候选必须阻断。","assumptions":"明确假定demo_log完整记载并支持所述进入、退出与接口构成变化，含前后状态和时间；它仍是纯教学占位，不冒充实际注册来源，本段不是可提交的完整运行记录。","boundary":"观察支持不等于原型整体支持，更不是现实人员分级。"},{"title":"身份构造：全角和空白不创造独立复核者","text":"虚构对象ID为team-a，复核ID写成带首尾空格的ＴＥＡＭ－Ａ。经过NFKC、去首尾空白和小写转换，两者都为team-a，因此不能把它当独立复核者。即使改成完全不同的review-b，若仍是原对象自行确认，实质独立仍未满足。","assumptions":"仅检验字符串规范化及逻辑边界，不处理任何真实人员身份。","boundary":"形式不同并非独立充分条件；程序记录也不能保证实际执行。"}],"counterexamples":[{"identity":"constructed_boundary","text":"顶层e1可查，嵌套证伪项引用的e2就无需再查。","effect":"原文要求每一层递归解析，未覆盖嵌套引用仍存在幽灵依据。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"证伪成立后改称“弱S2”，就可继续保留同一S2候选。","effect":"违反证伪阻断规则；应保留事实并重新考虑候选或未知。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"已有U/H/G/C链接，因此现场材料可以省略。","effect":"合同职责与眼前对象证据不是同一事。","sourceIds":["theory"]}],"questionAnswers":[{"question":"E含e2但外部R不含e2，引用能通过吗？","answer":"不能，需要两层解析；还不能靠只补一个字符串宣告内容有效。","basis":"本节原文及上述公开推导"},{"question":"为何一个S2-O1观察supported不能让整张S2成立？","answer":"它只覆盖一项；入口、其他观察、反例证伪及尺度等仍需逐项材料。","basis":"本节原文及上述公开推导"},{"question":"复核ID不同就独立吗？","answer":"不充分；还要核实质身份与决策链关系，派生别名或换字符串不能替代。","basis":"本节原文及上述公开推导"},{"question":"只有一个观察窗口是否必不能作原型描述？","answer":"不必，按该原型本身条件判断；不能统一硬加CM-PHASE多区间，也不能省该原型明确的跨窗条件。","basis":"本节原文及上述公开推导"},{"question":"某候选证伪项supported，应该如何处理？","answer":"阻断该候选，保留原材料及理由，改查其他合格候选或保持unknown，不能靠弱化命名绕过。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-2/figures/section-8-2-1.png","alt":"逐项五字段，item／state／status，refs／reason；本记录对象证据E，例：e1、e2，需匹配对象与窗口；外部注册表R，例：e1、e3，e2缺外部解析；递归收集F，例：e1、e2，不能只核顶层；证伪项supported，阻断对应候选，不能改弱名字绕过；复核与边界，实际独立＋版本记录，描述性／行动授权none。教学集合F⊆E但F不包含于R；ID解析不等于事实真实，所有运行记录仍不授权行动。","caption":"教学集合F⊆E但F不包含于R；ID解析不等于事实真实，所有运行记录仍不授权行动。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上排展示两层来源链，下排保留递归范围、证伪阻断与独立复核；例中e编号全部为教学符号。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"运行时记录是形式证据和程序规范，采用标明身份的片段与集合构造；不制造现实分类实例或虚构独立审阅证书。"},"openQuestions":[],"taskId":"S-8-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1637—1665行；每节精确范围见sourceRefs","claim_support":["8.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.2.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"D0","title":"现行原文对象合同与同一性","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.1第425—448行","claim_support":["8.2：K只是同一性判据，与完整合同及实际状态变化区分"],"limits":["教学K约定不是现实集体身份的充分测量方案。"],"access_status":"read"},{"id":"SP","title":"现行原文九轴状态","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§5.2第1039—1059行","claim_support":["8.2：逐轴适用性、未知与不可相互替代，观察扩大不扩大J"],"limits":["不把字段填写当事实认证。"],"access_status":"read"},{"id":"S2","title":"现行原文S2原型卡","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.3.3，第1702—1718行，S2-O1及证伪行","claim_support":["8.2.1教学片段：S2-O1进入/退出和接口变化；中心单方标签分化的证伪阻断"],"limits":["demo_log为教学占位，不是真实证据，也不是完整运行记录。"],"access_status":"read"},{"id":"modes","title":"现行原文混合与并行路径","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行，mixed、parallel行","claim_support":["8.2：多原型正面支持和对应位置，而非缺失即混合"],"limits":["案例不满足材料时保持未知。"],"access_status":"read"},{"id":"phase","title":"现行原文原型与相位机制界线","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§7.3.10第1586—1589行；§8.2.1第1662—1664行","claim_support":["8.2.1：U/H/G/C只是合同链接；单窗原型描述不统一硬需CM-PHASE，机制另加相应条件"],"limits":["不省略各具体原型本身的时间要求。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-2/lecture.md","sourcesPath":"/reading-assets/S-8-2/sources.json","sourceSlicePath":"/reading-assets/S-8-2/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-2/diagrams.md"},"8.3":{"title":"8.3　S0—S6 状态原型","lead":"七张卡的用途，是把“看起来像”拆成可以核查、可以反驳的判断。先固定同一对象与窗口，再看入口和反证，不靠编号挑一个听起来好听的名字。","explanation":["原文定位：第1666—1667行；原文锚点 section-8-3；短引文：‘S0—S6 状态原型’。本题源切片逐字附后，讲解与原文分开。","本父节原文只有标题，具体内容在下七个独立单元。本讲父节解释共同读法，分别回指§8.2和七卡，不把目录本身当作经验规律。S0聚焦形成中的局部凝聚，S1聚焦对生成核心的持续依赖，S2聚焦持续扩展及承接分化，S3聚焦相互强化的连通约束，S4聚焦实际重构与转换成本，S5聚焦跨窗协调和真实成本，S6聚焦分布式恢复、更新与继任。","每卡同时读入口、退出、可观察、反例、证伪、尺度、证据升级、合同链接和结论上限。入口不是只找一个相似特征；退出不等于必进下一编号；可观察项须对应实际材料；反例提示同表象的竞争解释；证伪已支持会阻断候选。尺度说明哪些低可见位置和时窗不能漏掉。","分类与机制升级分开。各卡的H/G条件针对特定因果、锚点、历史、跨尺度等较强主张，不应机械施加给所有基础观察；但卡本身的必要条件也不能省。U/H/G/C合同链接给出对象与推论责任，不是眼前对象的证据。当前载体、H5留痕和当前表示之外的G3增量尤其不能合成一个“有历史”标签。","本题真实案例只说明某个可核过程或不足以分类的反向材料，均没有为所举集体授予完整S状态。教学构造以明确假设演示判断，不能代替真实对象的入口、反证、九轴、独立复核及非授权记录。标签始终描述性、可撤回，任何实际处置另有规范与授权责任。"],"distinctions":[{"leftTitle":"入口满足","leftText":"必要条件有对应对象材料。","rightTitle":"某项相似","rightText":"仅一个表象像卡片，不足整体分类。"},{"leftTitle":"退出候选路径","leftText":"现原型可能不再主导，另核后续状态。","rightTitle":"自动升级","rightText":"按编号跳到下一张，原文不允许。"},{"leftTitle":"合同链接","leftText":"说明哪类概念或实例承担责任。","rightTitle":"对象证据","rightText":"真实对象在指定窗口的可追查材料。"}],"boundaries":["七卡未宣称穷尽所有集体状态，未匹配残差可以保留。","不把中心材料当整体，不把集体标签当个人人格。","一项证伪支持不能靠多项弱相似投票抵消。"],"questions":["为何已支持证伪不能被更多相似项抵消？","S4退出后必到S5吗？","真实案例只支持某个接口变化，能给整个组织S标签吗？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"8.3","start_line":1666,"end_line":1667,"startLine":1666,"endLine":1667}],"outputId":"section-8-3","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先冻结对象、K、SP、窗口和子系统，核适用域。","逐卡检查完整必要条件与竞争解释，保留支持、反证和缺失。","遇已支持证伪项阻断该候选，不靠弱化名称继续。","把有限原型描述、机制解释与行动建议的材料责任分开。","多个位置分别留证据，未知不改叫混合，编号不作价值和时间阶梯。"],"teachingExamples":[{"title":"布尔构造：必要条件不是加分表","text":"为说明逻辑，设某虚构候选需入口E1、E2和观察O均成立，且证伪F未被支持。若E1=1、E2=0、O=1，不能因“两项好于一项”就判通过；若E1=E2=O=1但F=1，候选仍被阻断。现实还含未知，不可把未查F写成F=0。","assumptions":"纯形式缩略，不对应任何卡的完整字段；1/0是本例已设真值，不表示已做实际验证。","boundary":"说明必要性和阻断，不给出真实分类算法或可靠率。"}],"counterexamples":[{"identity":"constructed_boundary","text":"把七卡当打分表，哪张关键词最多就选哪张。","effect":"忽略必要条件、证伪、尺度及引用职责，词频不能认证构型。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为何已支持证伪不能被更多相似项抵消？","answer":"它按该候选的明确失败条件阻断判断，原型不是任意加分投票。","basis":"本节原文及上述公开推导"},{"question":"S4退出后必到S5吗？","answer":"不必，可停滞、回退、接管、崩解等，后续路径须另查。","basis":"本节原文及上述公开推导"},{"question":"真实案例只支持某个接口变化，能给整个组织S标签吗？","answer":"不能，完整卡及运行合同还需其余条件与证据。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3.png","alt":"S0 凝聚，共同问题与反复生成行动，边界承诺仍在形成；S1 核心依赖，可重复识别的生成核心，关键功能持续依赖；S2 扩展分化，边界持续扩展，新承接与退出位置；S3 连通约束，多约束相互强化，额外末端负荷；S4 实际重构，关键结构真实改变，新旧并存及转换成本；S5 跨窗协调，替代／反馈／恢复可用，纳入真实成本；S6 动态平衡，多位置纠错与真实继任，持续更新而非无波动。七张卡均须独立检查入口、反例与证伪；编号不赋价值或处置权。","caption":"七张卡均须独立检查入口、反例与证伪；编号不赋价值或处置权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。并列卡保留各项条件及停止位置；卡片排列不是必经演化顺序，也不替代正文逐项证据。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"父节是七卡导航，形式逻辑说明最直接；经验案例分别放到适用子节并限定支持范围。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.3.1":{"title":"8.3.1　S0　锚点凝聚原型","lead":"最初有人把一个共同问题说出来，反复召集、翻译、试探，关系和少量资源开始聚拢。S0描述这种形成中的构型，不把它叫作低级组织。","explanation":["原文定位：第1668—1684行；原文锚点 section-8-3-1；短引文：‘候选集体正在形成’。本题源切片逐字附后，讲解与原文分开。","S0的两项入口须一起看：在冻结且对象继续满足的K下，共同问题或意义安排带来可见局部聚集，成员、实际边界或承诺仍在变化；候选生成行动反复出现，承接尚薄。稳定分析判据不要求成员先稳定，反之形成中的不稳定也不能免除同一性追踪。","四个观察面是竞争表述仍协商、资源聚集伴高进出、生成行动者实际承担翻译召集或试错、失败试探与备选历史仍保留。一个热词或一群同时点进页面的人不足以代替这些过程；真实成本也不因金额小就不算，但是否承担须有记录。","反例包括热点、平台推荐造成的短期同步及行政命名的形式团队。应查奖励、曝光或命令撤除后，承诺与边界是否仍持续，或使用其他可比过程材料。这里是提出区分问题，不授权冒险撤除支持或强行测试参与者。与匹配临时聚集相比，共同方向、行动聚集和生成角色均无区别时撤回S0；若稳定角色、承接和重复运转早已存在，S0也不是主导。","退出有两类：同一K继续满足且可追踪时，锚点、实际边界与生成角色跨窗稳定，并出现可追查承诺和初步承接，可另检S1；也可消散、分裂、被吸收或休眠。原K不再满足或不再适用时先核转换或终止。过程结束不自动等于失败，不能从定义推断哪条路径最常见，比例需机会总体与观察。","尺度要分别看到生成者、早期参与者、潜在退出者及外部命名者，不把其中一人的人格聚合成整体。较强主张中，意义安排的资源/行动/协调差异须H1，指定形成通道须G2；H5检留痕，当前载体后续作用按§4.5，额外历史增量才加G3。合同链接U01/U02/U03/U08/U09/U11、H1/H2/H5、G1/G2/G3、C1/C2/C4/C5/C10/C12承担相关接口及推论边界，不替代对象材料。","最终只可说指定对象、尺度、窗口与锚点凝聚原型相容。不推参与者能力、价值或意愿不足，不授权扶持、解散、筛选或排除。支持一个早期集体也应另有价值、成本与权限依据，而不是因编号0就认定必须干预。"],"distinctions":[{"leftTitle":"形成中的集体","leftText":"有局部聚集及反复生成行动，其他面向仍形成。","rightTitle":"低能力群体","rightText":"涉及个体能力评价，S0不提供此推论。"},{"leftTitle":"短期同步","leftText":"同受曝光或奖励而同时出现。","rightTitle":"可持续承诺候选","rightText":"需实际行动和后续材料，不能只凭同时性。"},{"leftTitle":"过程结束","leftText":"形成活动停止或转向。","rightTitle":"失败判决","rightText":"需另有目标、范围与评价依据。"}],"boundaries":["边界在变不等于K可省略，K固定不等于成员冻结。","匹配临时聚集反例与已有成熟运转都会限制S0判断。","不能仅凭幸存项目故事估计所有早期集体成功率。"],"questions":["已知20项目仅4个网页仍在，其他16个可直接记失败吗？","边界尚在形成是否妨碍固定K？","看到稳定承接早已长期运行，还应将它主导记S0吗？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3-1.png","caseLinks":[{"title":"Polymath的公开发起材料","href":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/"}],"caseNotes":[{"title":"Polymath的公开发起材料","text":"Gowers于2009年1月27日公开提出围绕一个数学问题进行协作，邀请尚未成熟的想法并给出暂行讨论规则；2月1日又依据回应修订程序。本节只把这些当可核的召集与规则试探材料。","sourceLabel":"Gowers本人2009年1月27日原博文，结合2月1日续篇","sourceUrl":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","sourceLocator":"正文的问题提议、后续安排及暂行规则；续篇2009-02-01 Questions of procedure开头","boundary":"不据两篇文章判完整S0，不知道全部参与成本、退出者及反例比较；后来的成功不能倒填初始条件。","href":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/"}],"sourceRefs":[{"section":"8.3.1","start_line":1668,"end_line":1684,"startLine":1668,"endLine":1684}],"outputId":"section-8-3-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先核K与可追踪对象，再找聚集及反复生成行动两项入口。","逐项记录协商、资源进出、真实行动及失败备选材料。","对热点同步或行政命名等竞争解释给区分材料，核证伪。","退出时分别检查稳定承接、消散等路径及身份变化，不自动升S1。","机制与历史主张按所选路线升级，有限分类保持非授权。"],"teachingExamples":[{"title":"机会总体构造：只看留下者不能估成功比例","text":"虚构观察库原有20个同口径早期项目，后来只保存4个仍活跃者的网页。仅看这4页会得到“看到的都还在”，不能推出成功率100%。即使确认4个活跃，其余16个失去资料，也只能说已知活跃4、其余状态未知；活跃也未等同原定成功目标。","assumptions":"20为完整机会总体的教学设定，缺页原因未知，未假定16个全部失败。","boundary":"不估计任何现实群体发展概率。"},{"title":"逻辑构造：名字相同的热度不等于同样入口","text":"虚构甲页获得一次平台曝光，只有短暂同步点击；乙围绕同一问题反复召集并有可核试错投入。两者都自称“团队”，但仅凭名字不能给同一分类。甲入口材料不足，乙也仍须补齐尺度、反例及其他条件。","assumptions":"明确虚构，未把反复投入直接当整卡通过。","boundary":"不否认短期聚集可以有价值。"}],"counterexamples":[{"identity":"constructed_boundary","text":"留下来的四个项目都活跃，所以所有S0必会变成稳定组织。","effect":"幸存材料缺机会总体与失访状态，且原型定义允许多种路径。","sourceIds":["theory"]}],"questionAnswers":[{"question":"已知20项目仅4个网页仍在，其他16个可直接记失败吗？","answer":"不能，失去资料不等于项目失败，需保留未知。","basis":"本节原文及上述公开推导"},{"question":"边界尚在形成是否妨碍固定K？","answer":"不必，固定追踪判据与边界状态变化不同；仍须核对象继续满足该判据。","basis":"本节原文及上述公开推导"},{"question":"看到稳定承接早已长期运行，还应将它主导记S0吗？","answer":"不应，原卡将此列为S0不主导的反证条件，应检查其他构型。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3-1.png","alt":"入口共同检查，局部凝聚＋反复生成行动，K继续满足，承接尚薄；四类可观察，协商／进出／召集试错，失败备选记录；竞争表象，平台热点／奖励同步，行政命名的团队；证伪与停止，匹配聚集无区别，或稳定承接早已存在；可能后续，另检S1／消散／分裂，吸收／休眠／对象转换；结论上限，指定窗口相容，不评价人格，不授权处置。上述是条件与路径候选；路径发生比例必须另有机会总体和观察资料。","caption":"上述是条件与路径候选；路径发生比例必须另有机会总体和观察资料。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。并列卡保留各项条件及停止位置；卡片排列不是必经演化顺序，也不替代正文逐项证据。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"发起者当时公开文字记录形成期召集和规则试探，适合局部过程例，明确不作状态认证。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.3.2":{"title":"8.3.2　S1　生成核心奠基原型","lead":"一个人经常站在台前，不必就是所有运转都离不开他。S1要查的是关键功能是否持续依赖生成核心，而不是谁最有名或谁宣布决定。","explanation":["原文定位：第1685—1701行；原文锚点 section-8-3-2；短引文：‘中心性是结构依赖’。本题源切片逐字附后，讲解与原文分开。","S1要求K、锚点和至少一个生成角色可以跨决策重复识别，关键翻译、决策、动员、冲突处理或关系修复持续依赖一个或少数生成角色。一次应急集中不足以满足持续依赖。基本规则、语言、资源通道与早期记忆开始奠基，独立承接者仍少。","四观察面是锚点和边界初步稳定、关键决策依赖核心、规则和记忆载体开始重复、外部进入有限且定向。组织图、公开宣布与实际工作要分别核；若图示和实际通道矛盾，应记conflicted，不为让故事一致而删除一侧。","成熟组织也可能由创始人公开宣布，但实际承接已经广泛分布；行政新设部门可能只是上级的角色单元。应追执行、停止权、反馈和核心暂时低介入时实际运行。若核心低介入，多中心承接仍稳定，则核心依赖被反驳；不是只换说法保留S1。","退出既可因新进入者形成持续承接、责任和边界接口而另检S2，也可因核心分裂、退出、接管、休眠或消散转入其他路径。锚点不稳定但对象仍满足原K并可追踪时可重检S0；原K不满足、不适用或同一性未明时，先做对象转换/终止或unknown，不按编号机械回退。","尺度须分生成角色、早期承接者、上级命名者和外部支持者。锚点和核心的结果效应分别追加H1/G2；早期制度或创伤的当前载体效应按§4.5，留痕检H5，额外历史残差检G3。合同链接U01/U02/U03/U04/U06/U07/U09/U11、H1/H2/H3/H4、G1/G2/G3及C1/C2/C3/C5/C9/C10/C11/C12是推理职责导航，不是用这些编号证明现实依赖。","中心性不证明领导正当，S1不表示幼稚、落后或应被整合。即使关键功能确依赖某人，也不能据此赋予永久领导、扩大权限、强制建制或替换他人的资格；规范、真实选择与授权另核。"],"distinctions":[{"leftTitle":"公开中心","leftText":"经常发言、宣布或代表组织。","rightTitle":"功能核心依赖","rightText":"关键工作缺其介入便受影响，需过程材料。"},{"leftTitle":"应急集中","leftText":"短时特定事件下权力或任务集中。","rightTitle":"持续生成核心依赖","rightText":"跨决策与常态窗口仍依赖。"},{"leftTitle":"结构中心性","leftText":"网络或功能上的依赖位置。","rightTitle":"永久领导资格","rightText":"规范与授权判断，前者不能推出。"}],"boundaries":["低介入观察须核是否仍有隐藏远程支持或外部救援。","核心退出不必等于整个对象立即消失，身份与承接分别判断。","核心重要不使其他承接者的成本或异议失效。"],"questions":["网络B删除发言人后任务仍能完成，反驳了什么？","锚点变了能直接从S1退回S0吗？","核心确有结构依赖，是否可赋永久领导权？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3-2.png","caseLinks":[{"title":"发起者修订规则不能单独证明核心不可替代","href":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/"}],"caseNotes":[{"title":"发起者修订规则不能单独证明核心不可替代","text":"Gowers在2009年2月1日续篇中说明，自己依据评论及进一步考虑重写讨论规则，并调整新讨论线程的组织办法。它记录了发起者实际组织行动，但没有提供其低介入时整个协作是否还能运转的比较。","sourceLabel":"Gowers本人2009年2月1日原博文","sourceUrl":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","sourceLocator":"Questions of procedure正文开头：回应评论、放宽相关议题与按需建立线程的安排","boundary":"只支持发起者行动，不以公开中心性判定完整S1或永久领导资格，也不假造离场实验。","href":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/"}],"sourceRefs":[{"section":"8.3.2","start_line":1685,"end_line":1701,"startLine":1685,"endLine":1701}],"outputId":"section-8-3-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["核重复对象识别、锚点与生成角色，而非只看名字或一次事件。","查关键功能对核心的跨决策依赖及独立承接实际容量。","用低介入下运行等材料区分公开中心与功能依赖，保留外部兜底。","依反证与身份条件决定撤回、重检或未知，不机械进入下一编号。","机制效应与领导正当分开，保持有限描述上限。"],"teachingExamples":[{"title":"网络构造：相同发言人可以对应不同工作网络","text":"虚构两套任务网络都有甲作公开发言人。网络A中乙、丙完成任务前均须取得甲唯一提供的输入，删除甲后两任务均不能完成；网络B中乙、丙各有独立输入和能力，甲只是汇总宣布，删除甲不阻断它们。在所设模型内，只有A有这种核心单点依赖。","assumptions":"输入不可替代、任务规则明确且无隐藏支持；删除节点只作纸面图论操作，不是现实撤职测试。","boundary":"单点依赖模型只说明一项结构责任，不构成完整S1分类或撤换授权。"},{"title":"时间构造：一次停电的集中调度不足以定常态","text":"虚构平时多中心运行的机构在一次两小时停电中临时集中调度。只截这两小时会看到核心，但若分类目标是整季度常态，需要该季度的决策与承接材料，不能用一次应急片段代表持续生成依赖。","assumptions":"时窗为自拟，未预断真实集中调度是否妥当。","boundary":"说明窗口匹配，不否认应急事件本身的事实。"}],"counterexamples":[{"identity":"constructed_boundary","text":"创始人仍每次发布结果，因此组织必然仍是S1。","effect":"发布角色可能不掌握不可替代工作通道，须核实际承接。","sourceIds":["theory"]}],"questionAnswers":[{"question":"网络B删除发言人后任务仍能完成，反驳了什么？","answer":"反驳发言人是所设两项任务不可替代核心的主张，不证明现实全部功能独立。","basis":"本节原文及上述公开推导"},{"question":"锚点变了能直接从S1退回S0吗？","answer":"先核对象是否继续满足原K且可追踪；身份未明时先处理对象转换或未知。","basis":"本节原文及上述公开推导"},{"question":"核心确有结构依赖，是否可赋永久领导权？","answer":"不能，结构描述不提供规范与授权。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3-2.png","alt":"网络A：甲，两任务唯一输入源，纸面模型；网络A：乙任务，需甲输入，无替代通道；网络A：丙任务，需甲输入，无替代通道；网络B：甲，只作公开汇总，不提供必要输入；网络B：乙与丙，各有独立输入与能力，删除甲仍可完成。虚构任务网络：A中甲分别供给乙、丙；B两任务不依赖甲，发言身份不等于功能依赖。","caption":"虚构任务网络：A中甲分别供给乙、丙；B两任务不依赖甲，发言身份不等于功能依赖。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。左侧三节点明确是甲向乙、丙分别供给，不是乙再供给丙；右侧两卡说明另一网络的独立任务。纸面删除不授权现实撤职。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"同一早期过程新增关注公开组织行动与不可替代功能的区别，材料不足处明确保留。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.3.3":{"title":"8.3.3　S2　首次扩展与承接分化原型","lead":"人数增加可能只让同样的事做得更多，也可能改变边界、承接与退出位置。S2关注后一类持续分化，并把新出现的异议和模糊参与留作正常需要理解的位置。","explanation":["原文定位：第1702—1718行；原文锚点 section-8-3-3；短引文：‘分歧本身不是失稳’。本题源切片逐字附后，讲解与原文分开。","S2两项入口是至少一类边界持续扩展且改变关系，以及核心之外出现可区分承接、成本、退出和未决位置。边界可涉及成员、服务对象、地域、平台接口或协作网络，不限于人数。新进入者带来理解、技能、资源和风险差异，需核实际角色而非中心单方面贴标签。","四观察面是进入/退出及接口构成变化，角色责任分化，反馈量、翻译成本、时滞和恢复需求变化，以及认同、异议、退出和安全分别记录。参与不等于认同，未决参与也不是负面主体；仅当可观察机制持续阻断承接、反馈或恢复，才有对应结构问题的材料。","反例包括人数或用户量增长却没有结构变化，以及表达安全改善后旧冲突终于可见。固定统计口径后增长不持续，且不改变边界、角色、责任、接口或负荷，应撤回S2；所谓分化只来自中心单方标签也应撤回。投诉变多不自动等于问题变坏，需要覆盖和表达通道。","退出不是自动升级：重复负荷形成连通约束并持续分割通道时可另检S3；也可能扩展停止、回撤、跳跃、分裂、合并、接管、休眠或崩解。每种路径要有对应过程，不能把有分歧就当已进入连通约束。","尺度应同时覆盖整体、中心、新承接者、退出者及外部化成本。观察扩大不增加对新成员的J权限。扩展或通道的因果效应另需G2/CAUSAL；跨尺度需D3/E5，闭合或转换主张需G4；锚点协调需H1，表达和观测效应需H4；H5留痕、§4.5载体作用与G3残差分开。合同链接U01/U02/U03/U04/U06/U07/U08/U09/U11、H1—H5、G1—G4、C1/C2/C3/C4/C5/C6/C7/C9/C10/C11/C12各给职责，不能替现场材料。","扩展可能改善协调，也可能增加承接成本，但哪一种需证据。S2不授权统一思想、限制退出、清退异议或以“扩维需要”要求个体加负担。认同、拒绝与模糊参与都要按实际材料和权利条件保留。"],"distinctions":[{"leftTitle":"人数增长","leftText":"一个统计总量变大。","rightTitle":"结构扩展分化","rightText":"关系、接口、角色和承接位置持续变化。"},{"leftTitle":"冲突更可见","leftText":"表达渠道和安全改变了报告。","rightTitle":"冲突实际更多","rightText":"还需相同测量口径及来源覆盖。"},{"leftTitle":"不认同或未决","leftText":"具体参与位置与态度状态。","rightTitle":"负向主体","rightText":"不能由异议标签自动生成。"}],"boundaries":["中心给出新角色名称不等于实际承接和停止权出现。","新成员的真实负担与退出能力不能被总用户量遮蔽。","边界扩展、表达差异和结构阻断不是一个事实。"],"questions":["20件问题报告5变10，问题是否必然翻倍？","新岗位名称增多足以证明承接分化吗？","出现不认同的人是否就是S2负向主体？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3-3.png","caseLinks":[{"title":"讨论增加后的整理与新分工线索","href":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/"}],"caseNotes":[{"title":"讨论增加后的整理与新分工线索","text":"在2009年2月1日程序帖的2月2日评论中，Gowers记录评论已较多、分问题开始出现，并提到Jason Dyer已尝试把评论归到不同线程；他询问是否需要分开讨论。这是当时整理需求和参与分工的有限记录。","sourceLabel":"Gowers原程序帖中的署名当时评论","sourceUrl":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","sourceLocator":"Gowers本人2009-02-02 17:41评论，讨论数量、子问题和Jason Dyer整理段","boundary":"这是发起者对整理过程的记录，不等于持续边界扩展、全部退出权或完整S2已核；不把后续成果倒填初期能力。","href":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/"}],"sourceRefs":[{"section":"8.3.3","start_line":1702,"end_line":1718,"startLine":1702,"endLine":1718}],"outputId":"section-8-3-3","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["区分人数增长与关系边界持续扩展，核口径和时间。","查新承接、成本、退出及未决位置是否实际形成。","分别记录认同、异议和表达安全，排除报告增多只是可见度变化等解释。","核证伪与多种退出路径，不因冲突本身宣告结构失稳。","跨尺度、机制与行动各补相应材料，不能从范围扩大扩J。"],"teachingExamples":[{"title":"测量构造：投诉数翻倍而问题总数不变","text":"虚构每月实际问题均为20件，原安全渠道只让其中5件被报告，新渠道让10件被报告。观察投诉5→10，但构造中的实际问题仍20；报告率由1/4变1/2。若没有对覆盖与安全的材料，不能仅凭投诉量判问题加倍。","assumptions":"实际问题数与报告机制在构造中明示；真实场景二者常都未知且可能同时变化。","boundary":"不是断言所有投诉增长都只是测量改善，更不能用此理由否认投诉内容。"},{"title":"关系构造：同样加两人，结构含义不同","text":"虚构网络甲从2人到4人，新增两人仅短时围观且没有新增承接接口；网络乙也从2到4人，但形成独立任务入口、反馈、成本记录及真实退出安排。人数差相同，结构证据不同；乙仍须持续窗口与全卡材料，不能直接因图复杂就判S2。","assumptions":"教学关系设置，不把围观者视为低价值或强迫其承接。","boundary":"人数与接口不同，不意味着某种扩展必然更好。"}],"counterexamples":[{"identity":"constructed_boundary","text":"批评突然变多，必须清理异议才能维持扩展。","effect":"把表达可见性、真实阻断和行动授权混为一谈，缺少机制与规范依据。","sourceIds":["theory"]}],"questionAnswers":[{"question":"20件问题报告5变10，问题是否必然翻倍？","answer":"不必，给定模型只是报告率提高；现实须核两者。","basis":"本节原文及上述公开推导"},{"question":"新岗位名称增多足以证明承接分化吗？","answer":"不足，实际任务、资源、成本、反馈与退出位置须核。","basis":"本节原文及上述公开推导"},{"question":"出现不认同的人是否就是S2负向主体？","answer":"不是，异议与未决参与要分别记录，不能自动污名化。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3-3.png","alt":"入口一，某类边界持续扩展，确实改变关系；入口二，核心外承接与成本，退出及未决位置；四面观察，进入接口／角色责任，翻译时滞／认同安全；教学报告率，问题20，报告5→10，报告率1/4→1/2；反例与证伪，只涨数或中心贴标签，固定口径后无持续变化；结论边界，异议不等于阻断，观察扩大不扩J权限。报告率为教学构造，不否认真实投诉；完整S2仍须其余对象与时间材料。","caption":"报告率为教学构造，不否认真实投诉；完整S2仍须其余对象与时间材料。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。并列卡保留各项条件及停止位置；卡片排列不是必经演化顺序，也不替代正文逐项证据。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"增加的讨论带来整理与新分工问题，适合举局部接口变化线索；没有越界判完整状态。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.3.4":{"title":"8.3.4　S3　连通约束下的发展原型","lead":"一个瓶颈拖慢另一个，后者又反过来加重前者，这才是S3要查的连通约束。问题数量、抱怨声量或某个难相处的人，都不能代替这张通道图。","explanation":["原文定位：第1719—1735行；原文锚点 section-8-3-4；短引文：‘不是“问题很多”’。本题源切片逐字附后，讲解与原文分开。","S3的入口要求至少两类约束相互强化，并跨窗影响通道；同时集体仍运行，但末端承接、反馈、资源或恢复持续承担额外负荷。审批、资源、信任、责任、信息、平台和外部依赖都可能进入网络，关键是它们怎样接续，不是罗列名词。","四观察面是约束网络与瓶颈，输出仍有但损耗返工和隐性劳动增加，修复反复启动却不能写回，以及中心/边缘、指标/承接、名义/实际持续分裂。相似变化可能来自共同输入、口径偏差或短期峰值，不能由相关就画相互强化箭头。弱信号消失也可能是表达通道失效，不等于问题被解决。","反例包括保护性的分层与冗余，以及主动降载重构造成暂时慢产出。要查限制究竟阻断必要反馈，还是隔离错误并提供替代路径。排除共同输入、偏差和短峰后若约束间无连通关系，或末端替代通道、写回和恢复持续有效，S3不应主导。","退出时若关键关系、权限、资源或接口开始实际重构，可另检S4；也可回退、虚稳态、休眠、接管、强制重写、迁移或崩解。提出改革不等于已经重构，表面安静也不自动退出约束状态。","尺度须拆中心、边缘、功能单元、承接末端与外部受影响位置，可parallel；总体平均不遮蔽末端。权力或中介遮蔽主张须H4，指定通道与相互强化须G2；历史形成的当前约束按§4.5，额外残差检G3，跨尺度闭合失败检G4。合同链接U02/U03/U05/U06/U07/U08/U09/U10/U11、H1—H5、G2/G3/G4、C2/C3/C4/C5/C6/C7/C9/C10/C11/C12分别约束这些主张，不让术语代证据。","S3只要求继续区分约束网络与竞争解释，不能把个人命名成壁垒，也不授权清洗、接管、强制改革或把过渡代价转给弱势位置。实际限制若保护错误隔离，应保留其功能，不以“畅通”作为无条件目标。"],"distinctions":[{"leftTitle":"多种问题并存","leftText":"数量多或同时出现。","rightTitle":"连通约束","rightText":"存在相互强化并跨窗影响通道的关系。"},{"leftTitle":"阻断必要反馈","leftText":"限制使问题无法到达或写回。","rightTitle":"保护性隔离","rightText":"限制可能拦截错误且有替代通道，需比较实际功能。"},{"leftTitle":"弱信号消失","leftText":"没再收到问题报告。","rightTitle":"问题消失","rightText":"需要对象状态和安全可见性材料。"}],"boundaries":["相关瓶颈可由共同外因造成，不预设双向因果。","稳定产出不能抹去返工、隐性劳动与恢复成本。","保护性冗余不是因多一道程序就该拆掉。"],"questions":["递推第三轮为何是1.75而不是2.5？","返工有界是否就否定连通约束？","多一道安全隔离程序是否必为S3壁垒？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3-4.png","caseLinks":[{"title":"灾后恢复中的物流与材料条件","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"灾后恢复中的物流与材料条件","text":"GAO2019年报告列出波多黎各和美属维尔京群岛复电困难，包括港口、机场失电影响修复材料运入，以及多地恢复同时增加材料需求。它说明恢复工作可同时受不同资源通道约束。","sourceLabel":"美国政府问责局2019-04-18原报告","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"GAO-19-296，印刷pp.18—19，Logistical challenges及Availability of materials","boundary":"原报告支持这些约束，不单据并存判相互强化、完整S3或个人责任；本讲未重建全部跨窗因果网络。","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"8.3.4","start_line":1719,"end_line":1735,"startLine":1719,"endLine":1735}],"outputId":"section-8-3-4","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先列两类以上约束及跨窗末端额外负荷。","为相互强化画出具体通道、时间和可比较状态，排除共同原因。","检查替代通道、保护性隔离、主动降载及测量偏差。","按证伪撤回或限制主导分类，保留各位置独立事实。","实际重构另检S4，机制和处置都不由S3标签自动取得。"],"teachingExamples":[{"title":"递推构造：相互强化不必无限爆炸","text":"设自拟两类额外返工工时u、v，同步规则u_next=1+v/2、v_next=1+u/2，初值均0。第1、2、3轮分别为(1,1)、(1.5,1.5)、(1.75,1.75)，相互作用持续加重负荷；由对称性，u_n=v_n=2(1−2^(−n))，趋近2而不发散。若移除交叉项，每轮均为1。","assumptions":"系数、外部每轮1小时和同步更新纯属构造；交叉项代表已设通道，不是从数据相关估出来。","boundary":"说明有连通加重也可有界，不据此认定任何现实S3或允许撤掉程序。"},{"title":"共同原因构造：同涨不等于相互强化","text":"另设u_t=z_t、v_t=z_t，z为共同外部需求，没有u到v或v到u的方程。两者会完全同涨同落，但改变u而保持z不变不会改变v。观察相关不能在这两个模型之间自动作选择。","assumptions":"结构方程为教学设定，操作只在纸面模型进行。","boundary":"现实可能既有共因又有相互作用，需具体证据区分。"}],"counterexamples":[{"identity":"constructed_boundary","text":"审批和返工总是一起涨，所以审批与返工必彼此强化。","effect":"共同需求可产生同样相关，需通道和相应因果比较。","sourceIds":["theory"]}],"questionAnswers":[{"question":"递推第三轮为何是1.75而不是2.5？","answer":"同步用上一轮另一变量1.5，故1+1.5/2=1.75。","basis":"本节原文及上述公开推导"},{"question":"返工有界是否就否定连通约束？","answer":"不否定，模型仍有交叉强化与额外负荷；连通不必等于发散。","basis":"本节原文及上述公开推导"},{"question":"多一道安全隔离程序是否必为S3壁垒？","answer":"不是，要查它是否阻断必要反馈，或隔离错误并提供替代路径。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3-4.png","alt":"返工u，u_next=1+v/2，自拟工时；返工v，v_next=1+u/2，自拟工时；同步三轮，(1,1)→(1.5,1.5)，→(1.75,1.75)；另一个模型，u=z，v=z，仅共同外部输入；观察要求，查通道与竞争解释，不以问题数代连通。两向规则是教学设定；共同原因模型也可产生同步变化，真实箭头仍需取证。","caption":"两向规则是教学设定；共同原因模型也可产生同步变化，真实箭头仍需取证。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上排展示自拟相互依赖方程，下排保留共同原因模型；三轮只作计算展示。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"实际恢复资源约束适合说明连通检查的对象；并存事实与完整相互强化判断明确分开。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.3.5":{"title":"8.3.5　S4　结构重构窗口原型","lead":"旧安排正在拆解、新安排尚未完全接住，确实可能出现转换成本。S4让我们描述这段窗口，但“正在重构”不能替无限代价和伤害找理由。","explanation":["原文定位：第1736—1752行；原文锚点 section-8-3-5；短引文：‘不是“改革已经正确”’。本题源切片逐字附后，讲解与原文分开。","S4两入口是至少一个关键字段实际改变而非改名宣传，以及新旧安排并存、过渡成本可追踪、K持续核对。关键字段可在关系、权限、资源通道、角色责任、反馈写回、停止条件或边界接口。变更不自动保持原对象，应检查对象继续满足原K以及判据是否仍适用。","四观察面是权限/资源/角色/责任/停止条件实际写回，双重系统与转换成本，缓冲冗余冷却停止回滚是否可用，多位置后果是否进入真实反馈。只画新流程图或发布新愿景不足；要问谁按哪个版本实际做了什么、何时生效。","反例包括改名换人和重画图的象征改革，也包括拆旧、过载与产出下降其实来自破坏性清洗或资源抽离。若实际关系、权限、资源和执行均未改变，应撤回S4；若无可用新结构且功能持续断裂，不能包装为改善性重构。描述变化与声称改善是不同结论。","退出到S5须跨窗改善通道、反馈、承接与恢复，且无隐藏外包；否则可能停滞、休眠、回退、接管、强制重写、虚稳态或崩解。新系统上线不等于旧成本已结清，短期低产也不证明未来必补偿。","尺度覆盖变更前基线、过渡、冷却、回滚与恢复窗口，并分改革发起、执行、承接及成本承担位置。改善或伤害的因果主张须G2/CAUSAL，对象或干预转换须G4；失败尝试经当前载体影响未来按§4.5，额外历史残差检G3，不能用“隧穿”隐喻跳过。合同链接U03/U05/U06/U07/U09/U10/U11、H1—H5、G2/G3/G4及C2/C3/C4/C5/C6/C7/C9/C10/C11/C12是责任索引。","所谓过渡谷地最多是待检描述，不授权不可逆伤害、取消申诉、清洗、强制迁移或把成本压给低权力者。即使某项成本比较显示未来回收，仍须规范、权益、风险、可替代方案和授权，不能把工时回本当万能正当性。"],"distinctions":[{"leftTitle":"结构实际重构","leftText":"字段与运行安排真实改变。","rightTitle":"改革正确","rightText":"关于效果及规范正当的另一个结论。"},{"leftTitle":"转换成本","leftText":"新旧并行和迁移所耗资源。","rightTitle":"可无限要求的牺牲","rightText":"成本存在不自动正当化其分配。"},{"leftTitle":"未来工时回收","leftText":"在明示模型内总工时可能下降。","rightTitle":"总体净改善","rightText":"还须质量、风险、其他成本与位置后果。"}],"boundaries":["承诺未来好处不证明过去代价有权被施加。","不存在可用新结构时不能用“过渡期”无限推迟核验。","K变化需新版本及身份核对，不能靠同名称强接。"],"questions":["成本模型N=5时是否已经节省工时？","如果新流程后来无法使用，原回本推导还能用吗？","v2图已发但权限未变，能否说权限重构已完成？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3-5.png","caseLinks":[{"title":"续保流程的实际系统调整","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"caseNotes":[{"title":"续保流程的实际系统调整","text":"马里兰2024年报告记载，其更新后的自动续保系统流程自2023年11月开始使用。本节只据此保留一个实际流程改变的历史记录，而不是只靠改进计划的提交。","sourceLabel":"Maryland Department of Health，2024年4月报告","sourceUrl":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","sourceLocator":"印刷p.9，末段updated ex parte systems process及第5项系统变更","boundary":"实际使用不证明完整S4、新旧并行成本已覆盖或改革总体正当；未据此核定所有个体结果或当前法律要求。","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"sourceRefs":[{"section":"8.3.5","start_line":1736,"end_line":1752,"startLine":1736,"endLine":1752}],"outputId":"section-8-3-5","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先确认关键结构字段实际变化，新旧并存和转换成本可核。","持续核K及新旧版本，跟踪执行、停止、回滚与低可见后果。","排除象征改革、资源抽离或破坏性过程，证伪时撤回对应判断。","改善需跨窗及成本完整范围，转到下一原型另核。","因果、对象转换与现实行动分别取得各自条件。"],"teachingExamples":[{"title":"成本构造：短期谷地与回收条件要算清","text":"虚构原流程每窗耗4工时；转换窗同时运行旧流程4工时、新流程3工时，并投入迁移2工时，共9；之后每窗只耗3。转换后再观察N窗，方案累计9+3N，维持旧制则4(N+1)=4+4N，差为5−N。N=5时工时持平，N>5才在这个窄口径中节省；N=6时27对28。","assumptions":"同质量同任务，各窗等长，迁移仅一次，所有工时可加且无隐藏成本，后续新流程确实可用。","boundary":"不把工时回本当权益、伤害或总体正当性；实际条件不符必须重算。"},{"title":"版本构造：新图不等于新运行","text":"虚构流程图v2已公布，系统权限和执行日志仍为v1，所有旧审批节点继续存在。图纸变化可记，但“权限与通道已重构”未得到支持。若另有实际变化，应逐字段记录，不用一句“全部改革完成”代替。","assumptions":"虚构前后记录，未假定宣传动机。","boundary":"不由执行滞后诊断欺骗，也不把真实局部改变抹掉。"}],"counterexamples":[{"identity":"constructed_boundary","text":"产出下降是重构谷地，因此无需再查成本与停止条件。","effect":"下降可能由多种机制产生，且谷地不提供规范豁免或无限期限。","sourceIds":["theory"]}],"questionAnswers":[{"question":"成本模型N=5时是否已经节省工时？","answer":"没有，9+15=24，与4×6=24持平；N>5才节省。","basis":"本节原文及上述公开推导"},{"question":"如果新流程后来无法使用，原回本推导还能用吗？","answer":"不能，关键假设失效，须重新记录成本、功能和路径。","basis":"本节原文及上述公开推导"},{"question":"v2图已发但权限未变，能否说权限重构已完成？","answer":"不能，发布与实际执行须分开。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3-5.png","alt":"前基线，旧流程4工时／窗，同任务同质量假设；转换窗口，旧4＋新3＋迁移2=9，新旧并行；之后N个窗口，新流程每窗3工时，假设持续可用；累计比较，新9+3N，旧4+4N，差5−N；N=5持平，N=6为27对28，只比较所设工时；规范与边界，不为伤害自动正当化，停止／回滚／成本位置。所有工时是教学构造；回本条件不替代真实质量、风险、权益或行动授权。","caption":"所有工时是教学构造；回本条件不替代真实质量、风险、权益或行动授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。并列卡保留各项条件及停止位置；卡片排列不是必经演化顺序，也不替代正文逐项证据。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"报告给出实际开始使用，适合区分计划与执行；完整原型所需转换成本和K材料仍未提供。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.3.6":{"title":"8.3.6　S5　高效协调与弹性扩展原型","lead":"产出很高、投诉很少，可能来自协同，也可能来自维护债、沉默或把成本推给别人。S5要同时看产出、反馈、恢复和真正承担成本的位置。","explanation":["原文定位：第1753—1769行；原文锚点 section-8-3-6；短引文：‘高产出不是充分证据’。本题源切片逐字附后，讲解与原文分开。","S5两入口是关键通道跨窗低损耗、可替代、可写回，以及扩展、存护与消解相互协同且不靠封闭反馈或压制异议。这里的高效是特定环境、任务和窗口内的关系，不是无成本、永久稳定或一劳永逸。","四观察面须同时核：替代承接与通道真实可用；产出、反馈、恢复和维护同时保持；边界开放、保护与退出能执行且成本回流；漏洞审计能实际写回。备用名单不等于有资源权限的真实替代，审计报告发出也不等于漏洞已经修复。","反例包括资源繁荣、选择性指标、投诉渠道失灵、恐惧服从及将维护债推到未来的成功外观。纳入维护、恢复、退出和外部成本后效率优势消失，或中心低介入时局部故障迅速级联，应撤回S5。低投诉不能在不核渠道安全时当作无问题。","退出到S6要进一步看到分布式承接、自我更新、恢复和新生成跨扰动成立；也可因漏洞、异化、虚稳态、回退、功能转移、X0、接管或崩解不再主导。长期存续不是正当证明，高效协调也不保证永远维持。","尺度从管理层总量拆到维护者、低权力承接者、退出者与外部受影响者，覆盖高低负荷、扰动、恢复和维护窗。成因与漏洞效应须G2/H4；H5留痕、§4.5载体持续作用、G3额外残差分开；跨尺度复制须D3/E5映射及独立目标证据，闭合或转换主张另检G4。U01—U11、H1—H5、G1—G4、C1—C12全系列链接并不表示每次描述要把所有机制一口气证完，也不使编号成为对象事实。","S5不是善、成熟或可输出模式的标签。存续增长和筛选不提供扩张、复制、接管或增加成员承担的权限。源地效果成立，目标地仍要资源、通道、尺度、权利和独立材料；不能以“成功经验”绕过。"],"distinctions":[{"leftTitle":"高产出","leftText":"一个结果量较大。","rightTitle":"高效协调","rightText":"同口径资源、反馈、维护、恢复和承担关系均需核。"},{"leftTitle":"备用安排写在表上","leftText":"有人名或设备名。","rightTitle":"替代真实可用","rightText":"具备知识、资源、权限、时间及实际接续。"},{"leftTitle":"源地有限有效","leftText":"在已检环境和窗口成立。","rightTitle":"可以普遍复制","rightText":"需要尺度映射和目标地独立支持。"}],"boundaries":["中心少付出可能是别人或未来多付出，净范围须说明。","投诉少与无问题不同；隐性救火使表面去中心化失真。","完整成本下优势消失即限制或反驳原效率主张，不能再选回窄分母。"],"questions":["甲补成本后效率是多少？","三名候补只有一人同时具权限和时段，能算三个有效替代吗？","原地S5有限分类是否允许直接把模式移到新地区？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3-6.png","caseLinks":[{"title":"恢复率的分母与替代供给","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"恢复率的分母与替代供给","text":"GAO2019年报告对恢复供电的比例使用“能够安全恢复”的客户范围，并记载部分岛屿使用临时发电供给。本节借此提醒，恢复总量必须连同分母、可用条件和继续供给资源一起读。","sourceLabel":"美国政府问责局2019-04-18原报告","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"GAO-19-296，印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明","boundary":"这不证明有关集体满足S5，也不把临时恢复说成无持续投入或长期自主；未由供电指标判断正当与个人责任。","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"8.3.6","start_line":1753,"end_line":1769,"startLine":1753,"endLine":1769}],"outputId":"section-8-3-6","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["同时核跨窗通道、替代、反馈写回及开放退出，不单看产出。","对齐结果和投入口径，纳入维护、恢复及外部化成本。","检查低投诉是否源于安全渠道失效，低介入是否仍靠隐性救火。","出现明确证伪则撤回，后续S6或其他路径各需材料。","外推复制和实际动作另核目标证据及权限。"],"teachingExamples":[{"title":"分母构造：补入维护成本会改变效率排序","text":"虚构方案甲产出120个同质单位，报告直接工时60，表面效率2；乙产出100、全口径工时60，效率5/3。若甲还漏记维护与外包工时40，全口径效率为120/100=1.2，低于乙的约1.667。甲产出仍确为120，但原“效率更高”依赖漏分母。","assumptions":"产出同质同质量、工时同单位且不重复，乙60已包含全部比较范围；实际公平与风险未被量化。","boundary":"不说明所有高产出都是外包，也不以效率数值判正当。"},{"title":"可用性构造：三名候补不等于三条替代通道","text":"虚构名单有甲乙丙三位候补，但只有甲有实际系统权限，乙无权限、丙不在本窗口可用。若所问任务必须权限与时段同时满足，实际可用候补只有甲。名册人数3不能直接当冗余度3。","assumptions":"任务条件和候补状态为构造；不涉及对真实员工权限变更。","boundary":"资格记录不替代实际接续检验。"}],"counterexamples":[{"identity":"constructed_boundary","text":"产出120大于100，因此甲一定更高效且可复制。","effect":"缺投入与质量口径；构造加入维护后排序反转，复制还缺目标条件。","sourceIds":["theory"]}],"questionAnswers":[{"question":"甲补成本后效率是多少？","answer":"120/(60+40)=1.2；乙为100/60≈1.667，原排序反转而甲产出事实仍保留。","basis":"本节原文及上述公开推导"},{"question":"三名候补只有一人同时具权限和时段，能算三个有效替代吗？","answer":"不能，必须核联合可用条件及实际接续。","basis":"本节原文及上述公开推导"},{"question":"原地S5有限分类是否允许直接把模式移到新地区？","answer":"不允许，映射、目标证据及行动授权均另核。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3-6.png","alt":"方案甲：表面口径，产出120／直接工时60，效率2；方案甲：完整口径，再加维护外包40，120／100=1.2；方案乙：完整口径，产出100／工时60，效率约1.667；比较结果，甲产出仍较高，效率排序却反转；可替代须实际可用，知识／权限／时段／资源，名册不等于接续；S5其余条件，跨窗反馈／恢复／退出，不靠沉默或外包债。全部数值是同质任务的教学构造；效率不等于规范正当，更不自动授权复制。","caption":"全部数值是同质任务的教学构造；效率不等于规范正当，更不自动授权复制。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。并列卡保留各项条件及停止位置；卡片排列不是必经演化顺序，也不替代正文逐项证据。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"实际分母与临时供给条件直接展示高结果指标的范围限制，不替任何集体作完整S5判定。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.3.7":{"title":"8.3.7　S6　自适应动态平衡原型","lead":"真正的动态平衡不是从不出错，而是多个位置能看见问题、纠正、恢复并让后来者接得住。S6因此要查扰动与继任，不能只看平稳曲线。","explanation":["原文定位：第1770—1786行；原文锚点 section-8-3-7；短引文：‘不是消灭波动’。本题源切片逐字附后，讲解与原文分开。","S6两入口是中心低介入时多个位置仍能感知、纠错、恢复和写回，以及新承接者、规则和边界可持续更新，不依赖同一批不可替代个体。自治并非无上级支持：局部自稳、横向协同和上级兜底可以并存，应冻结各自实际范围和授权，不能把任何支持都当中心依赖，也不能把中心隐藏救火当自治。","四观察面是扰动后的恢复与二次失稳，多中心协同和兜底，新承接者从训练到真实接管，以及反馈、审计、申诉、规则修订持续闭环。新名单不等于继任，培训结束不等于取得知识、权限和保护；频繁换人也可能只是人员耗材化。","反例包括强控制、弱信号消失、资源保护和中心隐性救火造成低波动。可比扰动下恢复持续变慢、局部故障级联、纠错依赖单点，或继任者得不到知识权限保护，都反驳S6。没有扰动的平稳窗口不足以显示跨扰动恢复；不应为求证而擅自制造现实危险。","退出可因恢复慢、波动放大、写回失效、中心依赖或承接断裂转入回退等路径；也可因使命结束、功能转移、分裂、合并、范式替换或X0改变对象合同。S6不是绝对终态、无冲突社会或历史终点，持续校准才是所问能力。","尺度须跨扰动、恢复、继任及慢变量长窗，拆出边缘伤害并核自治、横向协同、上级兜底与实际J。调节反馈和多中心安排的效果须G2/CAUSAL；学习、制度记忆及代际承接先核载体保留和实际接续，H5检留痕，G3只检额外历史增量；跨尺度外推须D3/E5及独立目标证据，闭合转换主张另检G4。全U01—U11、H1—H5、G1—G4、C1—C12链接说明接口与上限，不替代眼前集体的证据。","观察到恢复能力不意味着对他者取得决策权，也不意味着成员必须持续加负担。具体保护、补给、继任与退出应有自己的规范和授权。纯技术反馈装置能恢复，不足以证明人类集体满足知识、权限、申诉和代际更新条件。"],"distinctions":[{"leftTitle":"低波动","leftText":"短窗观察值变化小。","rightTitle":"动态恢复能力","rightText":"扰动后能恢复、更新及避免持续失稳，须过程材料。"},{"leftTitle":"上级兜底","leftText":"明确边界下的支持与协同。","rightTitle":"中心隐性救火","rightText":"表面自治实由单点持续承担，须查实际。"},{"leftTitle":"培训或换人","leftText":"有培养或人员变动记录。","rightTitle":"真实继任","rightText":"后来者有知识、权限、保护并实际接管修改。"}],"boundaries":["不故意制造现实危险来满足分类需要，应使用合规可比材料。","整体恢复快不能抹去边缘受伤或无法退出的位置。","恢复单一功能不证明完整集体S6，纯技术稳态也不具人类原型资格。","历史载体接续可以有效而无额外G3残差，二者不可互代。"],"questions":["两模型无扰动都为0，为什么不能据此选恢复更好的那个？","A从8开始在阈值1下第几次更新恢复？","有上级兜底是否自动否定S6？","培训已完成但权限和保护缺失，可否把完整继任记supported？"],"diagramPath":"/reading-assets/S-8-3/figures/section-8-3-7.png","caseLinks":[{"title":"设备恢复不是整个人类集体的认证","href":"https://www.nasa.gov/mission/sts-114/"}],"caseNotes":[{"title":"设备恢复不是整个人类集体的认证","text":"NASA的STS-114记录在2005年8月1日舱外活动中更换故障控制力矩陀螺，之后空间站重新有四个工作的陀螺。本节只保留特定功能恢复事实。","sourceLabel":"NASA STS-114官方任务记录","sourceUrl":"https://www.nasa.gov/mission/sts-114/","sourceLocator":"Mission Highlights，EVA No.2条目：failed CMG No.1更换及four functioning CMGs","boundary":"不由一次设备恢复证明分布式集体自治、真实继任或完整S6；技术功能、人的承接与权限要分别取证。","href":"https://www.nasa.gov/mission/sts-114/"}],"sourceRefs":[{"section":"8.3.7","start_line":1770,"end_line":1786,"startLine":1770,"endLine":1786}],"outputId":"section-8-3-7","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先核低中心介入下多个位置的实际纠错及替代更新，不把上级兜底一概排除。","跨可比扰动记录恢复、二次失稳与隐性救火，低波动不单独作证。","追继任从训练到知识、权限、保护和实际接管的完整链。","按明确反证撤回或转查其他路径，保留不同位置的结果。","机制、外推与现实干预分别满足对应证据和授权。"],"teachingExamples":[{"title":"动力构造：相同静止值，不同扰动恢复","text":"自拟系统A满足x_next=x/2，系统B满足x_next=x。在无扰动初值x0=0时，两者一直为0，看起来同样平稳。给定纸面扰动x0=8，A序列8、4、2、1、0.5，B一直8。若本构造恢复标准为|x|≤1，A第3次更新达到，B不达到。","assumptions":"变量无量纲、无持续外部输入、精确递推，阈值1事前给定；不是实际人类实验。","boundary":"只显示静态低波动不能识别恢复规律，不把A直接判S6，也不证明其社会正当。"},{"title":"联合条件构造：继任缺一项不能靠培训次数补齐","text":"虚构候补已学会流程k_skill=1，但执行权限A=0、实际接管T=0，保护P尚未知。完成培训事实可以保留，但不能给出k_skill∧A∧T∧P成立的结论。若后来A与T取得，P仍未知，就继续保留该缺口，不把不同候补的条件拼成一个人全具备。","assumptions":"k_skill只表示已掌握所需知识，与对象同一性判据K无关；A、T、P同为教学符号，现实多态不硬二值化。","boundary":"不是任何真实人事资格评审，也不因保护未知否认已取得的培训能力。"}],"counterexamples":[{"identity":"constructed_boundary","text":"连续三个月指标几乎不变，说明集体必具有自适应恢复。","effect":"无扰动平稳同时兼容恢复与不恢复模型，仍需过程及继任材料。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"新人名单每月都变，所以新生成能力很强。","effect":"频繁换人可能无知识权限保护和实际接管，不能用流动替更新。","sourceIds":["theory"]}],"questionAnswers":[{"question":"两模型无扰动都为0，为什么不能据此选恢复更好的那个？","answer":"两者在该观察条件上不可区分；扰动后的规则不同才显示本模型的恢复差异。","basis":"本节原文及上述公开推导"},{"question":"A从8开始在阈值1下第几次更新恢复？","answer":"第3次，8→4→2→1；这是固定阈值下结果。","basis":"本节原文及上述公开推导"},{"question":"有上级兜底是否自动否定S6？","answer":"不自动，原型允许自治、横向协同和上级兜底并存；须看低介入下实际能力及支持边界。","basis":"本节原文及上述公开推导"},{"question":"培训已完成但权限和保护缺失，可否把完整继任记supported？","answer":"不能，保留已知能力，缺失条件分别记录，不让一项代全链。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-3/figures/section-8-3-7.png","alt":"无扰动窗口，A与B都从x=0开始，两者始终为0；系统A：x_next=x/2，纸面扰动后8→4→2→1，第3次达阈值1；系统B：x_next=x，纸面扰动后一直8，不达恢复阈值；多位置恢复还要核，感知／纠错／写回，中心介入与上级兜底；真实继任还要核，知识／权限／保护，从训练到实际接管；描述上限，不是终态或无冲突，不产生对他者决策权。A、B是教学动力模型，不是人类原型分类；NASA一次技术恢复也不证明完整S6。","caption":"A、B是教学动力模型，不是人类原型分类；NASA一次技术恢复也不证明完整S6。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。并列卡保留各项条件及停止位置；卡片排列不是必经演化顺序，也不替代正文逐项证据。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"可核功能恢复帮助限定S6更强的人类集体要求，防止把技术成功直接升格为状态认证。"},"openQuestions":[],"taskId":"S-8-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1666—1786行；每节精确范围见sourceRefs","claim_support":["8.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.2：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.3：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.4：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.6：术语、合同、论证责任和原文边界；不据此认证经验事实","8.3.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"runtime","title":"现行原文原型最小合同与运行时记录","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2—8.2.1，第1637—1665行","claim_support":["8.3及七子节：K与尺度窗口、逐项入口观察反例证伪、证伪阻断、非授权边界；原型不统一硬需CM-PHASE"],"limits":["卡和记录可复核不等于实际分类可靠性已经检验。"],"access_status":"read"},{"id":"paths","title":"现行原文非线性路径与原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行；§8.7—8.8第1849—1868行","claim_support":["各卡：多种退出路径、非线性与未知保留；分类不等人格与价值，不穷尽全部状态"],"limits":["本文未认证任何真实集体的完整S原型。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体、留痕与额外历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§7.3.5第1552—1557行","claim_support":["七卡证据升级：H5有限留痕、当前载体的未来作用、G3当前表示之外增量分开；H实例唯一预选结果"],"limits":["不是把高级实例前提施加于每一条独立事实记录。"],"access_status":"read"},{"id":"scaleaction","title":"现行原文尺度迁移及规范桥接","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.4第473—494行；§4.14.1第908—924行；§5.2第1039—1059行；§7.4第1596—1603行","claim_support":["七卡：跨尺度不自动升J、机制不授权行动、成本与规范分开；K为同一性判据"],"limits":["所有纸面计算和网络操作不授权真实组织干预。"],"access_status":"read"},{"id":"gowers-start","title":"Timothy Gowers：Is massively collaborative mathematics possible?","url":"https://gowers.wordpress.com/2009/01/27/is-massively-collaborative-mathematics-possible/","source_type":"primary","version_or_date":"2009-01-27","locator":"2009-01-27正文：提出单问题公开协作、后续安排与末尾暂行规则","claim_support":["8.3.1：发起者公开提议、邀请未成熟想法并给暂行讨论规则"],"limits":["正文已读，未将全部评论当对象调查；不由后续成功倒填初期，未判完整S0或计算成功概率。"],"access_status":"partially_read"},{"id":"gowers-procedure","title":"Timothy Gowers：Questions of procedure","url":"https://gowers.wordpress.com/2009/02/01/questions-of-procedure/","source_type":"primary","version_or_date":"正文2009-02-01；所用评论2009-02-02","locator":"2009-02-01正文开头及规则；Gowers署名2009-02-02 17:41评论，讨论增多、子问题与Jason Dyer整理段","claim_support":["8.3.1—8.3.2：依据回应修订规则和线程安排；8.3.3：发起者记录讨论量增加、子问题出现及Dyer尝试分类评论"],"limits":["原作者过程记录，不证明持续核心依赖、全部参与成本、退出安全或完整S1/S2；三个单元共享同源，不计独立复制。"],"access_status":"partially_read"},{"id":"gao-constraints","title":"GAO-19-296：2017 Hurricane Season","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.18—19，Logistical challenges、Availability of materials","claim_support":["8.3.4：港口机场失电影响修复材料运入，多地恢复增加材料需求"],"limits":["约束并存不独立证明相互强化、全部机制或完整S3；报告依据访谈与文件，非本讲新实验。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296恢复口径与临时发电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6—7，恢复客户口径及Vieques/Culebra临时发电说明；p.1亦说明非全部灾前客户","claim_support":["8.3.6：恢复率限能够安全恢复供电的客户；部分岛屿临时发电供给"],"limits":["不是无持续投入、长期自主或完整S5证据；与上一条同一报告，保留来源依赖。"],"access_status":"partially_read"},{"id":"maryland","title":"Maryland Department of Health：FY24 Quarter4续保报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告2024年4月；函件2024-05-14","locator":"印刷p.9，第5项及末段更新流程开始使用说明","claim_support":["8.3.5：更新后的自动续保系统流程从2023年11月开始使用"],"limits":["历史过程资料，未覆盖全部过渡成本、K与完整S4；不作当前法律或个体健康建议。"],"access_status":"partially_read"},{"id":"nasa","title":"NASA：STS-114任务记录","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005年；页面更新2025-05-01","locator":"Mission Highlights，EVA No.2条目","claim_support":["8.3.7：2005年8月1日更换故障CMG No.1，随后有四个工作陀螺的功能恢复记录"],"limits":["技术功能恢复不证明整个人类集体的自治、继任或完整S6。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-3/lecture.md","sourcesPath":"/reading-assets/S-8-3/sources.json","sourceSlicePath":"/reading-assets/S-8-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-3/diagrams.md"},"8.4":{"title":"8.4　非线性路径库","lead":"状态卡说明一个窗口里的构型，路径库说明构型或对象合同怎样变化。十五种路径把分裂、休眠、转移和退场等真实可能留下来，不让所有故事都变成从低到高。","explanation":["原文定位：第1787—1810行；原文锚点 section-8-4；短引文：‘不描述“更好的人怎样升级”’。本题源切片逐字附后，讲解与原文分开。","本节十五个路径ID都是候选描述，不是价值或责任结论。同一窗口可有多个候选路径，但每个都须对象、尺度、时间、事件、通道和材料；缺证保持unknown。先问原对象是否继续满足K，还是须重新登记对象，再问功能、关系、权限、成本或记忆怎样改变。","1. mixed：同一对象、尺度与窗口中，两种以上原型必要特征共同出现。必须有多个原型的正面支持，不能把“不知道选哪一个”改叫混合；若差异能稳定归到独立子系统，应改用parallel。","2. parallel：不同地域、层级、功能或中心/边缘同时呈现不同状态。各子系统分别保留K、证据和退出条件，不能把局部标签求平均成整体阶段。它是同时的分布差异，不自动证明两个主体因果互相影响。","3. jump：相邻观察窗从一个配置到非相邻配置，中间原型没有可辨识持续窗。应先排除采样过稀和资料缺失，登记跳过的功能、代价及未知；两张间隔很远的照片不足以证明真正跳跃，也不能用物理“隧穿”隐喻补机制。","4. regression：相对同一对象自身基线，一个或多个功能退化。要分突发、渐进、临界跳变或级联，并核同口径基线；主动降载重构、X0或功能转移不等于回退，低产出也可能换来更少风险。回退不等于道德堕落。","5. split：原对象分成两个以上具有不同K的候选对象，新对象各自登记。临时分组、模块化或开两个工作线程未必改变对象身份；要查边界、权利责任、资源与连续性，而不是从组织图分叉直接断言分裂。","6. merge：多个对象形成新对象，或被其中一方吸收。联盟、共同活动和共享品牌不必是合并；需核新旧K与实际控制。弱势方的边界、记忆、退出和遗留责任单列，不能因形式合并把它们自动消去。合并也不天然代表进步。","7. dormancy：可见活动降低，但记忆、关系、符号、能力或再激活条件仍保存。要区分保护性撤离、耗竭停滞、资料消失和真实崩解。没有公开活动不直接等于没有承载，更不能把无法安全观察的群体判成已经消亡。","8. takeover：外部主体取得关键资源、权限或接口控制。外部支持和监管若保留真实自主及停止权，不必是接管；需查谁现在能决定和撤回什么。接管是控制关系描述，不单凭路径名认定合法或非法。","9. functional_transfer：核心功能转到另一对象。功能可以连续，而原身份、关系或记忆消失；外包单项任务不一定达到核心功能转移。还须查责任与记忆能否接续，不能用服务没有停证明原集体完整存续或义务已交清。","10. paradigm_replacement：旧对象未被修复，而被具有不同K、接口或规则的新对象绕过。内部升级或品牌改名不必构成这种替换；要核替代对象和运行关系。旧对象被绕过不抹掉遗留义务，技术新颖也不自动提供正当性。","11. trauma_built_development：边界、身份、规则或承接方式在伤害、剥夺、失败或威胁条件下形成。需要实际形成过程，创伤叙事本身不证明未来路径效果；保护当前形成的能力，与复制原始伤害是两个问题，不能因有后来能力就赞成施加伤害。当前载体作用和额外历史增量另按相应路线取证。","12. pseudo_steady：表面指标稳定，但实际承接耗竭、弱信号消失、反馈不写回或债务上升。应建立表面指标与实际承担的双记录，核成本、恢复、停止权和末端反馈。不能把稳定一概叫虚稳，也不能因报表稳定就删掉负担证据。","13. forced_rewrite：高权力主体在缺少可纠错同意、退出和记忆保护时重写对象。它不同于有授权、可撤回、可申诉的协商修订；关键查不可逆身份抹除、真实权力差及保护条件。不能只因变化快或发起者权力大就省略证据；路径判断也不自行授权反制。","14. external_carrier_migration：在修复封闭时，将人员、能力、资源、关系、证据或记忆转到更安全承接系统。要核接收能力、实际到达、资源和保护；只有“离开就好”的口号、没有接收容量或把代价全交个人，都不构成安全迁移。该标签不要求个体自行逃离。","15. collapse：原K不再成立，功能、承接、关系或边界发生非计划性断裂。要与X0、功能转移、保护性休眠和对象重组区分；活动减少或资源释放单独不足。断裂后可能释放资源，但不能由此把伤害说成必要或正当。","十五条可相互关联但不互相代证。例如局部接管与其他子系统并行状态可并存，功能转移后旧对象仍可能保有记忆，也可能消失；每项都按各自对象和范围记录。路径命名把竞争解释放进记录，机制、正当性、责任及行动继续各需自己的合同。"],"distinctions":[{"leftTitle":"mixed与parallel","leftText":"多个必要特征同域共同出现，或可稳定映射不同子系统。","rightTitle":"unknown","rightText":"关键材料不足，不是另一种混合。"},{"leftTitle":"休眠","leftText":"活动少但再激活载体条件仍存。","rightTitle":"崩解","rightText":"原K不成立且非计划性断裂，须对应证据。"},{"leftTitle":"功能转移","leftText":"核心功能由另一对象承担。","rightTitle":"身份与责任全部接续","rightText":"还须分别核K、记忆、遗留义务及实际承接。"},{"leftTitle":"接管","leftText":"外部取得关键控制。","rightTitle":"外部支持","rightText":"可能保留自主和停止权，不能自动等同接管。"},{"leftTitle":"受伤后形成能力","leftText":"一种可研究的历史形成过程。","rightTitle":"应复制伤害","rightText":"规范结论不由后来能力推出。"}],"boundaries":["所有路径都不把个人评价为更好或更坏。","同名、改名、分组或画图均不能替对象身份材料。","资料缺失不能当跳跃、休眠或崩解的肯定证据。","合并、接管、分裂各自不自动等于进步、非法或失败。","能力和记忆可部分迁移，未转移部分及义务不能因主功能连续而消失。"],"questions":["只有两个端点为何不足以确定jump？","产出100不变、三月维护债9，是否应该删掉产出稳定事实？","每天服务10件从甲转乙，最少还要查哪些连续性？","同一对象同窗两种原型特征，但能稳定分到两个独立子系统，应选什么？","集体形成时经历伤害，后来拥有能力，能否据此正当化复制伤害？"],"diagramPath":"/reading-assets/S-8-4/figures/section-8-4.png","caseLinks":[{"title":"Jakarta结束与JMeter独立是不同层面的事件","href":"https://jakarta.apache.org/site/news/news-2011-q4.html"}],"caseNotes":[{"title":"Jakarta结束与JMeter独立是不同层面的事件","text":"Jakarta官方2011年第四季度新闻记录，10月26日JMeter成为独立顶级项目；12月21日因没有剩余子项目，Jakarta项目退入Attic。本节据此区分一个上层项目结束与具体子项目获得独立身份的记录。","sourceLabel":"Apache Jakarta官方当时新闻档案","sourceUrl":"https://jakarta.apache.org/site/news/news-2011-q4.html","sourceLocator":"News & Status - 2011 Oct-Dec：26 October 2011与21 December 2011两个独立条目","boundary":"官方条目支持这些历史事件，不证明所有人员、义务、权限和记忆已完整交接，也不把两个日期当作完整X0、split或functional_transfer认证；不与后来Eclipse的Jakarta EE混同。","href":"https://jakarta.apache.org/site/news/news-2011-q4.html"}],"sourceRefs":[{"section":"8.4","start_line":1787,"end_line":1810,"startLine":1787,"endLine":1810}],"outputId":"section-8-4","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定对象与K、尺度、窗口及功能基线，先区分状态变化和身份转换。","按原顺序逐项检查十五路径的关键事实与相近反例，不仅做名称匹配。","对跳跃核采样，对休眠核保留载体，对分合核对象身份，对迁移核真实接收。","明确权力、责任、成本和低可见位置，不以功能连续代替记忆或义务连续。","允许同窗多候选和unknown，给每个候选独立反证。","路径描述不作价值排名或行动授权，后续机制与规范主张另补材料。"],"teachingExamples":[{"title":"采样构造：同样端点不能确定中间是否跳跃","text":"虚构仅观察t=0与t=3，分别见S1与S4。路径甲在中间依次有S2、S3的可持续窗口；路径乙在中间直接改为S4。稀疏记录对两路径都相容，因而不能凭端点宣布jump。需要足够时间分辨率和中间资料，再判断是否存在可辨识持续窗。","assumptions":"原型端点作为教学已知条件；不把编号当连续数值，也不提供真实分类。","boundary":"未见中间状态与证明中间状态不存在不同。"},{"title":"身份与功能构造：总服务不变仍可能更换对象","text":"虚构旧对象甲按K甲提供每天10件服务，后来新对象乙按不同K乙也提供10件，甲不再提供。总量10→10可支持所设窗口的功能连续，却不能证明甲身份还在、旧承诺全部转移或乙有权限取得全部资料；这些分别核对。","assumptions":"件数同质同质量，两个K不同及实际接续为构造前提；未指定这是完整X0。","boundary":"功能相同不是对象合同等价，也不把数量当遗留义务清零。"},{"title":"双记录构造：稳定产出与累积维护债","text":"虚构每月产出恒100，但所需维护5工时、实际完成2工时，每月未维护差3在本模型可累积，初债0。三月后债3、6、9。产出稳定事实仍真，却不足以说明恢复与承接可持续；若维护债是本任务相关风险，它必须进入判断。","assumptions":"未维护工作在模型内不自动消失、不可互相抵消，单位一致；没有把所有真实维护任务都假定线性累积。","boundary":"模型提示pseudo_steady候选，不单凭三数字授予完整路径状态或判人责任。"}],"counterexamples":[{"identity":"constructed_boundary","text":"t0是S1、t3是S4，所以已经证明跳过S2和S3。","effect":"缺中间材料，路径甲乙在稀疏观察下不可区分。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"旧项目结束，但功能有新承接，所以一切义务和记忆都已经解决。","effect":"功能、身份、责任和记忆分别连续，不能一项代全项。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"离开有害环境总是安全迁移，不必看接收系统。","effect":"无接收能力、资源与保护可能只是代价私有化，不能把建议当已完成迁移。","sourceIds":["theory"]}],"questionAnswers":[{"question":"只有两个端点为何不足以确定jump？","answer":"多个不同中间路径生成相同端点；须排除采样过稀和资料缺失。","basis":"本节原文及上述公开推导"},{"question":"产出100不变、三月维护债9，是否应该删掉产出稳定事实？","answer":"不应，保留产出和维护两套记录，限制由产出推出全面稳态的结论。","basis":"本节原文及上述公开推导"},{"question":"每天服务10件从甲转乙，最少还要查哪些连续性？","answer":"对象K、实际承接、记忆、授权、遗留责任和受影响位置，不能只看总服务量。","basis":"本节原文及上述公开推导"},{"question":"同一对象同窗两种原型特征，但能稳定分到两个独立子系统，应选什么？","answer":"parallel，并分别保留子系统K、证据及退出条件。","basis":"本节原文及上述公开推导"},{"question":"集体形成时经历伤害，后来拥有能力，能否据此正当化复制伤害？","answer":"不能，历史形成与规范选择不同，保护能力不等于赞成伤害。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-4/figures/section-8-4.png","alt":"mixed，同对象尺度窗口，多原型必要特征共同出现；parallel，差异映射不同子系统，各留K与证据；jump，非相邻配置间转移，先排采样稀疏；regression，相对自身基线功能退化，降载不自动是回退；split，多个不同K的新对象，临时分组不够；merge，新对象或一方吸收，联盟不自动合并；dormancy，活动低而再激活条件存，缺资料不等于休眠；takeover，外部取得关键控制，支持不自动是接管；functional_transfer，核心功能另有承接，不保全部身份与义务；paradigm_replacement，不同K等的新对象绕过旧，遗留义务不消失；trauma_built_development，伤害条件下形成安排，不正当化复制伤害；pseudo_steady，表面稳定，承接债上升，看实际成本与弱信号；forced_rewrite，高权力下缺纠错等保护，不同于协商修订；external_carrier_migration，移到更安全承接系统，须核接收能力；collapse，原K失效且非计划断裂，不同于X0与休眠。十五路径逐条按原文顺序呈现；名称不单独证明机制、价值、责任或行动权限。","caption":"十五路径逐条按原文顺序呈现；名称不单独证明机制、价值、责任或行动权限。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。十五卡是一张条件对照图，不是发展阶梯；每卡缩写需结合正文的证据与反例。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"同一历史档案给出不同层次对象的结束与独立，适合说明不能把上层结束等同所有功能崩解。"},"openQuestions":["具体十五路径的判定还需实际K、窗口、过程、保护及反证材料；本题没有给现实项目发出退出、合并或迁移指令。"],"taskId":"S-8-4","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1787—1810行；每节精确范围见sourceRefs","claim_support":["8.4：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"identity","title":"现行原文对象与原型最小合同","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.1第425—448行；§8.2第1637—1665行","claim_support":["8.4：K与对象身份、尺度窗口、缺失、并行/混合需正面材料"],"limits":["路径不因名字吻合就成立。"],"access_status":"read"},{"id":"X0","title":"现行原文X0独立转换及原型边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.5—8.5.2第1811—1838行；§8.7第1849—1860行","claim_support":["8.4：崩解、功能转移、休眠与X0区别；X0非最高阶段之后的必经事件"],"limits":["未据案例宣告完整X0。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体与额外历史","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.5第620—640行","claim_support":["8.4：伤害历史叙事不直接证明未来效应，载体与额外历史增量分别核"],"limits":["不由形成能力正当化伤害。"],"access_status":"read"},{"id":"jakarta","title":"Apache Jakarta：News & Status - 2011 Oct-Dec","url":"https://jakarta.apache.org/site/news/news-2011-q4.html","source_type":"primary","version_or_date":"2011年第四季度原新闻档案","locator":"2011-10-26 JMeter becomes a top level project；2011-12-21 Jakarta Retired","claim_support":["8.4：JMeter成为独立顶级项目；Jakarta因已无子项目而退入Attic的两个历史事件"],"limits":["未核全部人员、遗留责任及权限接续，不授完整路径或X0状态；不是Eclipse Jakarta EE。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-4/lecture.md","sourcesPath":"/reading-assets/S-8-4/sources.json","sourceSlicePath":"/reading-assets/S-8-4/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-4/diagrams.md"},"8.5":{"title":"8.5　X0 有序退场与良性消亡","lead":"一项集体事业不必永远存在，也不必先长成“大组织”才有资格结束。X0把“怎样结束得有交代”单独拿出来检查：使命、功能、人员、记忆和责任各自去哪里，而不是给发展阶梯再加最高一层。","explanation":["原文定位：第1811—1818行；原文锚点 section-8-5；短引文：‘X0 不是第八状态，也不是 S7’。本题源切片逐字附后，讲解与原文分开。","X0的适用对象是人类意向性集体的生命周期路径，不是个人死亡、哀伤阶段或人格等级。它关注继续维持原对象是否仍服务已经登记的锚点，以及核心功能能否完成、终止或得到更安全承接；“不再维持”不能只看一张注销公告。","父节规定路径的身份与无最低状态门槛；8.5.1分别检查候选入口的独立理由及承接清单；8.5.2展开七个完成面与结果状态。进入候选不等于完成，完成记录也不等于产生现实处置权限。","为什么不设S5或S6前提？因为状态配置、退场理由和操作条件回答不同问题。临时倡议可在问题被别处承接时关闭；扩张项目可能因继续扩张伤害更大而收束；受困机构在修复不可行且外部承接充分时也可能退场。反过来，即使原型被登记为S6，也不能代替接收安排、成员保护或遗留责任。这里解释作者允许的条件类型，不声称这些情形一概应当退出。","机器字段把这一点写得明确：origin_policy取any_registered_origin；required_state_ids为空数组；s5_or_s6_prerequisite为false。空数组表示不把任何S编号设为入口资格，不表示免于登记原对象、K、观察窗口和出发情况，更不表示所有退场条件自动通过。","可以把判断分成三个互不代替的栏：所处原型说明当前配置；规范判断说明目标和保护为何可接受；操作材料说明功能、人员和责任如何实际接续。任一栏不能用另一栏分数填满。所谓“良性”也不能由维持组织成本较低或领导愿意退出单方面定义。","原对象按K结束，并不要求所有功能、记忆和责任同时消失。某些功能可结束，某些可迁移，未结案义务须继续有责任主体；咨询或缓冲性质的弱连接可以保留，但不得借旧名义恢复原控制权。这里不是要求人际关系全部切断，而是要求边界和权限可核。","附录A.10的HV10-R4把X0作为独立描述路由：逐项核8.5、保留E4材料，不硬需S0—S6最低原型或CM-PHASE。若另声称退出导致特定结果、或历史留下当前表示之外的增量，才另走相应机制路由；X0名称本身不补因果证据。"],"distinctions":[{"leftTitle":"X0","leftText":"独立生命周期路径，可从任何已登记出发位置检查。","rightTitle":"S7或第八阶段","rightText":"原文明确排除，不能把退场写成发展最高级。"},{"leftTitle":"没有最低S前提","leftText":"不以任何状态编号作为退场资格。","rightTitle":"没有条件","rightText":"对象、锚点、承接、保护和责任条件依然需要。"},{"leftTitle":"阶段能力","leftText":"当前构型中的能力与运行安排。","rightTitle":"规范正当性和操作可行","rightText":"目标、权益与实际交接分别判断。"},{"leftTitle":"原对象结束","leftText":"原K在所记时点不再成立或生命周期收束。","rightTitle":"所有功能与义务消失","rightText":"功能可以转移，义务可持续，必须分别记录。"}],"boundaries":["X0不能套作人的死亡或普遍哀伤阶段，也不构成个人价值评价。","S0并非自动不够资格，S6也不自动足够；不以编号排除任何已登记起点。","分类不授权解散、裁撤、资产转移、公开档案、放弃债务或代表成员同意。","退出理由、承接条件与执行权限存在分别的失败可能，不能互相补齐。"],"questions":["一个S0倡议的使命已由他处承接，能否仅因编号低而拒绝检查X0？","required_state_ids为空，是否代表无需登记原对象与K？","集体不再运作但遗留申诉尚在，应该怎样记录？"],"diagramPath":"/reading-assets/S-8-5/figures/section-8-5.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"8.5","start_line":1811,"end_line":1818,"startLine":1811,"endLine":1818}],"outputId":"section-8-5","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先确认对象是人类意向性集体，并登记原对象完整合同及同一性判据K。","原型编号只记出发位置，不以高低设置资格；核机器三个字段是否表达这一点。","分别登记锚点理由、实际承接与保护，进入8.5.1的候选检查。","将生命周期结束、功能持续、记忆留存和责任持续分栏，不能由一项推出其他项。","按8.5.2保存逐项证据与未知，再给受限路径状态；不由分类产生授权。"],"teachingExamples":[{"title":"教学构造：改变编号不应改变独立入口条件","text":"设两个虚构集体甲、乙，均已登记对象和窗口。甲原型S0，独立入口两组材料都齐；乙原型S6，但接收方能力未知。只据本题入口条件，甲可登记候选，乙的相应入口仍未决。把甲标签改成S3而保留所有入口材料，不应改变该入口判断。这显示判断使用材料而不是阶段排序。","assumptions":"两个原型标签和甲的完整入口材料仅为教学前提；没有提供七面完成证据，也没有现实授权。","boundary":"甲可进入候选不等于完成；乙未决不是证明乙永远不能退场。"},{"title":"形式构造：空集合不是万能许可证","text":"令M为退场资格所要求的最低状态集合，原文固定M=空集；令C为候选入口及其证据条件。取消“起点属于某个高阶集合”的限制，只移除一个限制项，并未令C恒真。机器字段全部正确而C未知的记录，仍不能凭结构合规得到完成。","assumptions":"集合表达只说明资格逻辑，不把现实充分性化约为三个字段。","boundary":"数据结构通过与事实条件成立是两个独立判断。"}],"counterexamples":[{"identity":"constructed_boundary","text":"这个小倡议还在S0，必须先成长到S5才能关闭。","effect":"把原型阶段错误用作退场前提，违背any_registered_origin。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"我们已经是S6，注销后剩余争议可一概不处理。","effect":"高阶标签不消去义务，也不提供免责或解散权限。","sourceIds":["theory"]}],"questionAnswers":[{"question":"一个S0倡议的使命已由他处承接，能否仅因编号低而拒绝检查X0？","answer":"不能，应按独立入口与完成条件逐项检查，而非设最低阶段。","basis":"本节原文及上述公开推导"},{"question":"required_state_ids为空，是否代表无需登记原对象与K？","answer":"不是，空的是最低原型前提，不是对象及证据合同。","basis":"本节原文及上述公开推导"},{"question":"集体不再运作但遗留申诉尚在，应该怎样记录？","answer":"分别记原对象结束时点与申诉的持续责任主体、渠道和未知，不能以注销抹除申诉。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-5/figures/section-8-5.png","alt":"已登记出发位置，可为任一S或未决，不是资格排序；独立候选入口，锚点理由＋承接清单，未知保留；七面完成检查，逐项材料与保护，不由入口代完成；阶段能力，描述当前配置，不代正当性；规范判断，目标与权益条件，不代操作材料；现实操作与权限，J、N、O另有要求，分类不自行授权。图为原文条件关系；任一起点都须独立检查入口和完成面，不是从S0爬到S7。","caption":"图为原文条件关系；任一起点都须独立检查入口和完成面，不是从S0爬到S7。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上排说明路径检查，下排三栏强调不能相互代替。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本单元解释X0的逻辑身份和机器资格边界；真实退场不能证明这些规范定义，具体公共流程与档案案例放在其对应子节。"},"openQuestions":["本题不为任何现实集体认证完整X0；出发原型不能替代其独立材料。"],"taskId":"S-8-5","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1811—1838行；每节精确范围见sourceRefs","claim_support":["8.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.5.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.5.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"identity","title":"现行原文对象、规范与行动边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.1第425—448行；§4.14.1第908—924行；§2.2第239—264行","claim_support":["8.5—8.5.2：K是同一性判据；描述、规范、授权与操作条件分别承担责任"],"limits":["不因分类产生现实处置许可。"],"access_status":"read"},{"id":"route","title":"现行原文HV10-R4及判断、行动上限","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"附录A.10第4185行R4；第4222—4223行；附录D.09相关边界第4665行","claim_support":["8.5：独立X0路由不要求最低S或CM-PHASE；E4与非授权边界；组织退场不套个人死亡或哀伤"],"limits":["解释路由条件，不给案例授予框架资格。"],"access_status":"read"},{"id":"paths","title":"现行原文相近路径","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行","claim_support":["8.5.2：功能转移、接管、强制重写、崩解与X0分别检查"],"limits":["X0未完成不自动推出其他路径成立。"],"access_status":"read"},{"id":"attic-process","title":"Apache Attic现行公布退出流程","url":"https://attic.apache.org/process.html","source_type":"primary","version_or_date":"当前网页，读取2026-10-14；页面无独立修订日期","locator":"Moving a PMC to the Attic：第1节公共讨论/参与/表决；第2节董事会批准后工作","claim_support":["8.5.1：当前公布流程区分讨论、决议与后续移交工作"],"limits":["未核任何具体项目实际履行全部程序；不把当前页面当2011年有效版本。"],"access_status":"read"},{"id":"attic-jakarta","title":"Apache Attic：Jakarta退休档案","url":"https://attic.apache.org/projects/jakarta.html","source_type":"primary","version_or_date":"当前官方档案，记述2011年12月事件；读取2026-10-14","locator":"Apache Jakarta正文退休日期与Read-only Resource表","claim_support":["8.5.2：2011年12月退休及只读资源索引登记"],"limits":["未逐链接核资源完整或安全，未核全部责任；不认证完整X0。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-5/lecture.md","sourcesPath":"/reading-assets/S-8-5/sources.json","sourceSlicePath":"/reading-assets/S-8-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-5/diagrams.md"},"8.5.1":{"title":"8.5.1　X0 候选入口","lead":"想结束一项事业，先回答两件事：为什么原对象确实不必照旧维持，以及那些依赖它的人、功能和承诺能到哪里去。退出愿望可以是真实的，但不能替这两组材料作证。","explanation":["原文定位：第1819—1822行；原文锚点 section-8-5-1；短引文：‘这个判断必须能被独立复核’。本题源切片逐字附后，讲解与原文分开。","第一组是锚点理由：原锚点已完成、失去适用性、由更安全对象承接，或原对象继续维持已主要服务自身存续。四种是候选理由，不是一概相同的事实。“完成”要核原先约定的结果和窗口；“失效”要核适用条件变化；“更安全承接”要核比较对象与保护；“只为自身存续”不能仅靠外部不喜欢该组织来认定。","独立复核意味着结论须有可检查的登记目标、材料与比较，不能由中心把目标改小后宣布原使命已达成。确需修订目标，可以明示新版本及理由，但旧版本下尚未完成或失败的记录仍应保留；新目标达成不自动重写旧目标的历史状态。","第二组是交接清单：人员、功能、资源、关系、记录、债务和不可替代价值逐项列出，并有可核验的接收方或保护安排。不是每一项都必须转到新组织，有的可依法依约终止或通过保护安排保存；但“无人接收”不能凭不写进清单就消失。","接收方名字只是检索入口。要按具体功能核其能力、权限、资源、时间窗口、可达性、维护与保护；同一个主体可能有技能却无权限，或获授权却无容量。它说愿意接收，也不证明实际接收已发生。候选入口与8.5.2的完成证据因此仍有距离。","短期受挫、资金紧张、领导疲倦和逃避责任都可能产生“必须结束”的叙述。这些情况可能值得照护、减负或暂停，也可能与有效退场理由并存；本节不否认其真实负担，只说明它们单独不能证明原锚点已经完成或交接安全。","因此先给候选理由及清单的支持状态，再标相似解释与待补材料。任何关键影响位置或接收能力未知，都不应该从“一份退出说明”跳到“良性完成”；保护性暂停或继续研究可以保留，并非强迫组织永远存续。"],"distinctions":[{"leftTitle":"使命完成","leftText":"原登记目标按原口径得到独立核验。","rightTitle":"改写使命","rightText":"形成新的评价对象，不能消除旧目标的未完成。"},{"leftTitle":"接收方存在","leftText":"有人或机构可联系。","rightTitle":"接收条件齐全","rightText":"具体能力、权限、资源和保护实际匹配。"},{"leftTitle":"退出需要被认真对待","leftText":"负担、疲劳和风险可能真实存在。","rightTitle":"已经证明良性完成","rightText":"还需要独立入口与七面接续材料。"},{"leftTitle":"清单完整","leftText":"相关项目及未知都被登记。","rightTitle":"全部已处理","rightText":"登记存在不等于实际交接和责任履行完成。"}],"boundaries":["不把疲劳或资金紧张单独当退场完成证明，也不据此贬低当事人的负担。","原文要求独立复核，不要求把隐私或弱势材料无差别公开。","承接不必都采取组织转移，可以是完成、终止或保护安排，依具体义务核验。","候选入口不授现实行动权限；当前公开流程也不能追溯证明过去每次退出都履行过同一程序。"],"questions":["一份退出声明列了所有项目，却没有接收方容量资料，能登记什么？","能力覆盖三项、权限覆盖a和b、资源覆盖b和c，三者共同覆盖几项？","把目标从10降为6而完成量仍6，原有4项差额如何处理？"],"diagramPath":"/reading-assets/S-8-5/figures/section-8-5-1.png","caseLinks":[{"title":"Apache Attic现行流程先区分讨论与批准","href":"https://attic.apache.org/process.html"}],"caseNotes":[{"title":"Apache Attic现行流程先区分讨论与批准","text":"Apache Attic当前公开流程先列公共开发者列表讨论、考虑用户及贡献者的参与，再列项目管理委员会表决与董事会决议环节；批准后的移交工作另有清单。它提供了把退出意向、可继续参与的机会和后续处置分开的具体公开流程。","sourceLabel":"Apache Software Foundation官方流程页","sourceUrl":"https://attic.apache.org/process.html","sourceLocator":"Moving a PMC to the Attic：第1节“A PMC decides to move to the Attic”与第2节“If the board approves the resolution”","boundary":"只支持截至2026-10-14可读的公布流程，不证明每个项目都实际履行，也不把现行条款追溯套到2011年Jakarta；不据此完成X0或提供法律意见。","href":"https://attic.apache.org/process.html"}],"sourceRefs":[{"section":"8.5.1","start_line":1819,"end_line":1822,"startLine":1819,"endLine":1822}],"outputId":"section-8-5-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定原登记锚点、版本、对象和观察窗口，再查四类候选理由之一的具体证据。","保留旧失败与未结案项，拒绝用事后缩小目标自证完成。","逐项列出七类交接对象以及接收或保护安排，明确谁受影响。","按功能核接收能力、权限、资源和窗口，区分书面承诺与实际接续。","并列检查短期挫折等竞争解释；给出候选或未知，而非提前写完成。"],"teachingExamples":[{"title":"数学构造：同名接收方的三个覆盖集合","text":"虚构三项任务U={a,b,c}，同一窗口内接收方可胜任集合A={a,b,c}，获授权集合J={a,b}，资源可用集合R={b,c}。即使暂假其他保护条件均成立，三者同时覆盖仅A交J交R={b}。因此不能由“接收方会做全部三项”推得三项可立即转交；a缺资源，c缺权限。","assumptions":"任务身份、质量和时间口径固定；J只是本例已明确登记的权限集合，不以数学运算产生新授权。","boundary":"交集是本构造的必要覆盖检查，未替代完整七面完成条件或现实运行验证。"},{"title":"教学构造：目标缩小不能抹除旧缺口","text":"虚构原承诺在窗口内交付10项，经核实际完成6项。中心把新目标改为6项，可使新口径比值6/6=1，却不能改变原口径6/10=0.6及尚缺4项。若原义务可终止，须另有依据、受影响位置和责任处理，不能靠改分母结案。","assumptions":"10项同口径、等权计数只为演示；没有默认每项同价值或可以相互抵偿。","boundary":"算例不反对正当修订目标，只反对用新版本覆盖旧承诺。"}],"counterexamples":[{"identity":"constructed_boundary","text":"领导疲倦，所以原锚点已经不适用，全部义务结束。","effect":"疲倦可支持减负需求，却不能单独证明锚点与义务状态。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"已找到能做a、b、c的团队，因此三项交接都齐全。","effect":"本构造中a的资源与c的权限仍缺，接收身份不代替实际覆盖。","sourceIds":["theory"]}],"questionAnswers":[{"question":"一份退出声明列了所有项目，却没有接收方容量资料，能登记什么？","answer":"清单与意向可以记录，接收能力保持未知，不能写良性完成。","basis":"本节原文及上述公开推导"},{"question":"能力覆盖三项、权限覆盖a和b、资源覆盖b和c，三者共同覆盖几项？","answer":"只有b一项；分别交集，不能取并集冒充可执行覆盖。","basis":"本节原文及上述公开推导"},{"question":"把目标从10降为6而完成量仍6，原有4项差额如何处理？","answer":"保留原口径缺口，另记新目标与终止或转移依据，不以改分母消除旧责任。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-5/figures/section-8-5-1.png","alt":"锚点理由，完成／失效／更安全承接，须独立复核；候选入口，两组材料分别检查，不等于良性完成；交接清单，人员、功能、资源等，接收方或保护安排；教学任务a，有能力＋权限，缺资源；教学任务b，能力＋权限＋资源，三者共同覆盖；教学任务c，有能力＋资源，缺权限。入口需独立理由与可核交接；下排是明确构造，三个集合的交集只有b，不是现实授权。","caption":"入口需独立理由与可核交接；下排是明确构造，三个集合的交集只有b，不是现实授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上排两组材料同时进入检查，下排逐任务显示覆盖缺口，不用并集替代交集。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"公开退出流程可说明意向、讨论和后续处理并非同一事件；本节新增观察点是候选与执行材料的分开。"},"openQuestions":["现实候选还需锚点版本、受影响位置、完整清单和实际接收条件，公开流程本身不提供这些个案事实。"],"taskId":"S-8-5","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1811—1838行；每节精确范围见sourceRefs","claim_support":["8.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.5.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.5.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"identity","title":"现行原文对象、规范与行动边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.1第425—448行；§4.14.1第908—924行；§2.2第239—264行","claim_support":["8.5—8.5.2：K是同一性判据；描述、规范、授权与操作条件分别承担责任"],"limits":["不因分类产生现实处置许可。"],"access_status":"read"},{"id":"route","title":"现行原文HV10-R4及判断、行动上限","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"附录A.10第4185行R4；第4222—4223行；附录D.09相关边界第4665行","claim_support":["8.5：独立X0路由不要求最低S或CM-PHASE；E4与非授权边界；组织退场不套个人死亡或哀伤"],"limits":["解释路由条件，不给案例授予框架资格。"],"access_status":"read"},{"id":"paths","title":"现行原文相近路径","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行","claim_support":["8.5.2：功能转移、接管、强制重写、崩解与X0分别检查"],"limits":["X0未完成不自动推出其他路径成立。"],"access_status":"read"},{"id":"attic-process","title":"Apache Attic现行公布退出流程","url":"https://attic.apache.org/process.html","source_type":"primary","version_or_date":"当前网页，读取2026-10-14；页面无独立修订日期","locator":"Moving a PMC to the Attic：第1节公共讨论/参与/表决；第2节董事会批准后工作","claim_support":["8.5.1：当前公布流程区分讨论、决议与后续移交工作"],"limits":["未核任何具体项目实际履行全部程序；不把当前页面当2011年有效版本。"],"access_status":"read"},{"id":"attic-jakarta","title":"Apache Attic：Jakarta退休档案","url":"https://attic.apache.org/projects/jakarta.html","source_type":"primary","version_or_date":"当前官方档案，记述2011年12月事件；读取2026-10-14","locator":"Apache Jakarta正文退休日期与Read-only Resource表","claim_support":["8.5.2：2011年12月退休及只读资源索引登记"],"limits":["未逐链接核资源完整或安全，未核全部责任；不认证完整X0。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-5/lecture.md","sourcesPath":"/reading-assets/S-8-5/sources.json","sourceSlicePath":"/reading-assets/S-8-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-5/diagrams.md"},"8.5.2":{"title":"8.5.2　X0 完成条件","lead":"“关掉了”是一件事，“关得有交代”是另一组待核事实。七个完成面要求把人、功能、资源、记忆和责任一起保留在记录里，不能用一张总分表让某些人的损失被别处的好成绩抵消。","explanation":["原文定位：第1823—1838行；原文锚点 section-8-5-2；短引文：‘只要受影响群体、遗留义务、接收能力、申诉或记忆安全仍为未知’。本题源切片逐字附后，讲解与原文分开。","一、锚点与对象。独立验证原锚点完成、终止或失效，登记K的结束时间和所有尚未结案项。K是同一性判据，不是整份对象合同；登记结束时间不等于过去记录失效。改目标、删失败项或中心单方宣告，都会破坏这一面的完成依据。","二、核心功能。每项分别标为完成、终止、转移或未决，并核接收方能力、权限、资源与回滚。不是所有功能都应永续，也不是每项都能由一个承接方包办；但只有公告而没有维护者、使用者连续性或适当终止安排，不能把功能栏写满。","三、人员与关系。保存安全、基本权益、停止权、不被报复及照护、依赖关系的承接。若把组织本来承担的工作和风险交给成员自行解决，即使账面费用归零也未证明此面完成。需要知道谁承担、谁可拒绝、谁能求助，而不只是列核心成员。","四、资源。对象、边界、顺序、时间与去向可追踪，防止高权力位置先截留资源、再把损失交给弱势位置。账面总额平衡不足以证明分配范围与程序正当；记录去向也不自动获得转移资产的权限。","五、记忆与证据。保存成功、失败、修复与岗位记忆，同时明确访问、隐私、纠错和反报复。公开全部资料未必比限制访问更安全；只留胜利史会损害复核，暴露弱势材料也会损害保护。保存什么、谁可访问、如何改错都需要具体安排。","六、债务与责任。合同、劳动、数据、维护、环境、申诉与未来风险要有持续责任主体。原对象结束不意味着每项尚未结案义务都已消灭；把接续责任登记清楚与宣称债务清零不同，负责者的能力、持续渠道和约束还需可核。","七、弱连接。可以保留咨询、经验与缓冲，但边界和期限明确。原成员愿意提供经验不等于旧中心仍可命令资源或代表成员；若确需新权力，应另有新授权，不能把“顾问”名义用作旧结构复活的暗道。","结果至少分候选、进行中、部分完成、完成及unknown。这些是带证据的路径结果，不是可随时间自动升级的数值。已完成的局部事实可以保留，同时把整体完成留作未决；受影响群体、遗留义务、接收能力、申诉或记忆安全有关键未知时，不能写良性完成。","七面不是可随意加权抵消的得分。功能转了但记忆和责任断裂，可能只到functional_transfer；外部单方关闭并改身份，可能是takeover或forced_rewrite；无承接而非计划性断裂，则可能是collapse。每个候选还要各自材料，不能因X0不成立就自动选择另一个路径。","最后，描述判断与实际行动分开。无论记录写候选还是完成，都不自行授权解散、裁撤、资产转移、档案公开、放弃债务或替成员同意。现实行动另核C12、显式规范前提N、J覆盖的具体权限及O程序；这不会取消已经可靠的历史事实。"],"distinctions":[{"leftTitle":"局部完成","leftText":"如某项服务已转接、某份档案已保存。","rightTitle":"整体良性完成","rightText":"还须满足全部相关完成条件，不能留关键未知。"},{"leftTitle":"责任接续","leftText":"仍有义务时可持续找到具备条件的负责者。","rightTitle":"责任消灭","rightText":"需另有依据，不由注销、改名或移交清单推出。"},{"leftTitle":"保存记忆","leftText":"保存必要内容并控制访问、纠错及风险。","rightTitle":"公开所有记忆","rightText":"可能违反隐私和保护，分类不提供公开权限。"},{"leftTitle":"弱连接","leftText":"受限咨询、经验与缓冲。","rightTitle":"原权力继续","rightText":"需要独立新授权，不由旧身份自然延续。"},{"leftTitle":"X0未完成","leftText":"证据缺口或条件失败。","rightTitle":"已证明collapse","rightText":"后者还需原K失效与非计划性断裂等自身条件。"}],"boundaries":["七面缺口不能用其他面的高分抵消；资料不足也不等于证明造成了损害。","有清单不等于完成，有完成公告不等于七面材料齐全。","不把所有遗留义务强行写成零，而要保存持续责任和未结案状态。","公开档案与保存档案不同，保护要求可能需要有限访问。","已知局部完成应保留，不因整体未决被抹去；整体unknown也不等于全部失败。"],"questions":["六面支持、一面记忆安全未知，能否以6/6的已知项平均判完成？","资源总额100全部记账，就能证明无人被不当剥夺吗？","服务交接已完成而旧申诉未结，应否把服务交接也标失败？","顾问小组以保留经验为由继续命令原成员，是否仍只是弱连接？","完成X0判断后，能直接把全部档案公开吗？"],"diagramPath":"/reading-assets/S-8-5/figures/section-8-5-2.png","caseLinks":[{"title":"Jakarta退休档案保留只读资源索引","href":"https://attic.apache.org/projects/jakarta.html"}],"caseNotes":[{"title":"Jakarta退休档案保留只读资源索引","text":"Apache Attic的Jakarta页面记载项目于2011年12月退休，并列网站、邮件档案、源代码、Wiki、董事会报告及下载的只读资源链接。本节新增观察点是项目结束与记忆入口保留可以并存，而非把停止运作等同删除记录。","sourceLabel":"Apache Software Foundation官方Jakarta退休档案","sourceUrl":"https://attic.apache.org/projects/jakarta.html","sourceLocator":"Apache Jakarta正文退休说明及“Read-only Resource”表","boundary":"所读页面证明这些资源被列出；没有逐一验证全部链接、内容完整性、实际访问、安全或遗留责任，也不足以认证完整X0。","href":"https://attic.apache.org/projects/jakarta.html"}],"sourceRefs":[{"section":"8.5.2","start_line":1823,"end_line":1838,"startLine":1823,"endLine":1838}],"outputId":"section-8-5-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["逐面建清单，绑定具体对象、时点、受影响位置、证据与负责者，保留原目标和失败记录。","对功能分别标完成、终止、转移、未决，核接收能力和实际接续。","把人员保护、资源去向、记忆安全、遗留责任和弱连接边界独立核验。","对已完成部分如实记载，对关键未知继续留unknown，不用总分补齐缺项。","以七面材料选择受限结果状态，并分别保留竞争路径，未通过X0不自动证明崩解。","任何现实处置另核规范、授权和程序，描述完成不具有执行许可证效力。"],"teachingExamples":[{"title":"逻辑构造：六项支持不能淹没一项关键未知","text":"把七面各自完整检查的摘要暂记为s=(1,1,1,1,?,1,1)，其中第5面记忆安全未知。若用已知六项平均，得6/6=1；若把未知当0，又会得到6/7，却把缺证伪装成失败。正确做法是保留六面已知支持及第5面未知，整体不得写良性完成。","assumptions":"1只是在本教学模型内假设该面完整条件成立的摘要；问号不是分数，不代表实际测得风险为零。","boundary":"本例只证明平均分不能代替必要条件检查，不凭七个符号发出现实X0认证。"},{"title":"数学构造：账面平衡不能证明去向正当","text":"虚构可分配资源100单位，记录为接收服务方60、遗留责任准备金30、原管理者领取10，和为100。恒等式60+30+10=100只说明记账总量无差额；是否有权领取10、30是否足够覆盖义务、弱势位置是否遗漏，都不能由加总推出。","assumptions":"资源可按同一单位相加，数字只是构造，未设任何真实资产处分或法律结论。","boundary":"守恒等式不等于授权、充分性或保护证明。"},{"title":"教学时间线：局部结束与责任续存","text":"虚构第0日原对象停止新业务，第10日服务交接完成，第30日档案访问规则落实；一项旧申诉仍由已明确的持续主体处理。可以分别记录三个事件和未结案申诉，不能只因第0日停业就写全部完成，也不能因为申诉未结就把第10日服务接续事实删掉。","assumptions":"事件及持续主体为教学前提，其能力、程序与其余七面条件未全部设定。","boundary":"本例不确定整体X0结果；展示多时点和局部事实如何共存。"}],"counterexamples":[{"identity":"constructed_boundary","text":"七面里六面很好，只要平均过线就可写良性完成。","effect":"原文列的关键未知不能加权抵消，且unknown不是失败分数。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"旧组织不在了，原有申诉与维护义务自然消失。","effect":"对象结束不自动消灭持续责任，应保留主体、渠道及未结案项。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"档案页列了只读资源，所以所有隐私、失败史和记忆安全均已保证。","effect":"资源登记只是部分证据，不能代表内容完整、访问实际可用或安全条件全部满足。","sourceIds":["attic-jakarta"]}],"questionAnswers":[{"question":"六面支持、一面记忆安全未知，能否以6/6的已知项平均判完成？","answer":"不能，不能把缺失项从必要检查中删除；保留局部支持与整体未决。","basis":"本节原文及上述公开推导"},{"question":"资源总额100全部记账，就能证明无人被不当剥夺吗？","answer":"不能，加总只核总量，还须去向、权限、程序、遗漏位置与保护材料。","basis":"本节原文及上述公开推导"},{"question":"服务交接已完成而旧申诉未结，应否把服务交接也标失败？","answer":"不应，局部事实保持成立，同时保留申诉责任和整体状态的限制。","basis":"本节原文及上述公开推导"},{"question":"顾问小组以保留经验为由继续命令原成员，是否仍只是弱连接？","answer":"已越过咨询边界；真实控制须另核授权，不能借弱连接复活原权力。","basis":"本节原文及上述公开推导"},{"question":"完成X0判断后，能直接把全部档案公开吗？","answer":"不能，完成分类不提供公开权限，仍核隐私、保护、具体授权与程序。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-5/figures/section-8-5-2.png","alt":"1 锚点与对象，原目标核验、K结束时点，未结案项保留；2 核心功能，完成／终止／转移／未决，接收条件与回滚；3 人员与关系，安全、权益、停止权，照护与依赖承接；4 资源，边界、顺序、时间、去向，防截留与损失外推；5 记忆与证据，成功、失败、岗位记忆，访问、隐私与纠错；6 债务与责任，持续责任主体，申诉与未来风险；7 弱连接，咨询、经验与缓冲，边界期限明确；结果至少五类，候选／进行中／部分完成，完成／unknown；分类不授权，不替成员同意，不自行公开或免债。七面分别检查；关键未知不得以平均分消除，记录完备也不替代实际事实和现实权限。","caption":"七面分别检查；关键未知不得以平均分消除，记录完备也不替代实际事实和现实权限。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。九卡中七张是完成面，另两张是结果状态与非授权边界；没有从卡片数量产生评分。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"一个真实退休档案把结束日期与保留资源并列，适合说明七面中“记忆与证据”的局部材料及其上限。"},"openQuestions":["对Jakarta未核全部受影响群体、义务、申诉、接收能力和记忆安全，因此不把官方退休记录追授为X0良性完成。"],"taskId":"S-8-5","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1811—1838行；每节精确范围见sourceRefs","claim_support":["8.5：术语、合同、论证责任和原文边界；不据此认证经验事实","8.5.1：术语、合同、论证责任和原文边界；不据此认证经验事实","8.5.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"identity","title":"现行原文对象、规范与行动边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§3.1第425—448行；§4.14.1第908—924行；§2.2第239—264行","claim_support":["8.5—8.5.2：K是同一性判据；描述、规范、授权与操作条件分别承担责任"],"limits":["不因分类产生现实处置许可。"],"access_status":"read"},{"id":"route","title":"现行原文HV10-R4及判断、行动上限","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"附录A.10第4185行R4；第4222—4223行；附录D.09相关边界第4665行","claim_support":["8.5：独立X0路由不要求最低S或CM-PHASE；E4与非授权边界；组织退场不套个人死亡或哀伤"],"limits":["解释路由条件，不给案例授予框架资格。"],"access_status":"read"},{"id":"paths","title":"现行原文相近路径","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.4第1787—1810行","claim_support":["8.5.2：功能转移、接管、强制重写、崩解与X0分别检查"],"limits":["X0未完成不自动推出其他路径成立。"],"access_status":"read"},{"id":"attic-process","title":"Apache Attic现行公布退出流程","url":"https://attic.apache.org/process.html","source_type":"primary","version_or_date":"当前网页，读取2026-10-14；页面无独立修订日期","locator":"Moving a PMC to the Attic：第1节公共讨论/参与/表决；第2节董事会批准后工作","claim_support":["8.5.1：当前公布流程区分讨论、决议与后续移交工作"],"limits":["未核任何具体项目实际履行全部程序；不把当前页面当2011年有效版本。"],"access_status":"read"},{"id":"attic-jakarta","title":"Apache Attic：Jakarta退休档案","url":"https://attic.apache.org/projects/jakarta.html","source_type":"primary","version_or_date":"当前官方档案，记述2011年12月事件；读取2026-10-14","locator":"Apache Jakarta正文退休日期与Read-only Resource表","claim_support":["8.5.2：2011年12月退休及只读资源索引登记"],"limits":["未逐链接核资源完整或安全，未核全部责任；不认证完整X0。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-5/lecture.md","sourcesPath":"/reading-assets/S-8-5/sources.json","sourceSlicePath":"/reading-assets/S-8-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-5/diagrams.md"},"8.6":{"title":"8.6　调节、预警与承接如何进入状态判断","lead":"看一个集体是否能稳定运行，不能只看今天的产出：要看遇到问题能否调节、警报是否有用，以及换人后责任和知识能否真的接上。多条信号可以一起分析，但它们的数量不能代替证据质量。","explanation":["原文定位：第1839—1848行；原文锚点 section-8-6；短引文：‘成簇不是预警的通用准入条件’。本题源切片逐字附后，讲解与原文分开。","调节层沿六个环节观察：目标是什么、感知到什么、怎样比较、谁能执行、执行结果怎样返回、各段有多少时滞。目标存在不证明被正确感知，收到信息不证明实际执行，修改表格也不证明相关运行字段已经生效。若目标本身正是权威记录，真实更正与执行记录可以构成相应写回；若目标是下游运行，须再核下游执行。","预警层比较恢复变慢、波动放大、同类扰动后果加重和局部闪烁是否共同出现。“同类”要控制扰动大小、暴露和观察口径，不能把更大外部冲击造成的更重后果直接解释为系统恢复能力下降。局部闪烁也不是任何情绪起伏的技术名称，只有在对应变量和动力条件下才有明确意义。","偿付层追踪谁作承诺、谁承担劳动和风险、收益回到谁，以及哪些成本被延后。这不是只核货币债务。表面稳定若实际依赖账外劳动、沉默或未来债务，可登记pseudo_steady候选，并核具体机制；原有产出稳定事实仍可成立，不能把全部稳定都改叫虚假。","成簇线索不等于独立重复验证。一个过程参数改变可以同时造成恢复慢、自相关变高和方差变大；同一序列算出的多个统计量还共用资料。它们可以构成有用的联合描述或模型输入，但应保留共同来源、相依结构和联合验证，不能把每个名称当一份独立试验。","反过来，不能设“必须两条以上警报”作为通用门槛。一个经专业验证、针对固定业务事件的信号可能足以支持有限预测；没有临界减速或没有第二条信号，既不保证安全，也不取消该有限预测。相应动力、噪声、采样和窗口条件不符时，不能直接移植临界转变指标。","评价预警先固定目标事件、期限、实时可用基线、标签形成与反向信号，再看规则在独立资料中的表现。联合规则需要联合分布或相应验证，不能仅将两条边际准确率相乘；阳性预测值高只说明被警报选中的对象中事件占比高，可能同时漏掉更多事件。实际选择还须明示误报、漏报和行动成本，预测表现本身不生成强制行动权限。","Scheffer等2009年论文的理论说明和讨论限定了临界预警：恢复、自相关、方差在特定动力和噪声下相关；外部突变、噪声变化或有限时间序列可使预警缺失或误判，出现信号也未必能确定转变时刻。本讲不把该论文的生态、气候或生理材料直接移植成组织阶段证据，也不从其模型生成“所有系统都会提前报警”的结论。","预警还必须来得及成为保护：发现、核验、发布、触达、理解、调度和起效各有时延。算法早发现只影响其中一段。警后无事可以依已冻结的实际事件目标评价，但是否因行动避免了伤害是另一因果问题；监测离线不能登记成零事件。具体响应制度变化时，应重核哪些预测结果仍可比较。","承接需候补梯队、影子岗位、岗位记忆、授权路径、交接窗口、合法性转译和保护条件。这里的影子岗位指可准备和学习的实际安排，不意味着未获许可的人可擅自代岗；合法性转译要核新角色的决定在相关制度和受影响位置中如何取得有效资格。有人被命名为接班人，不代表这些条件都已存在。","原生成者退出而接收者进不来，会留下权威或执行空缺；人员频繁更换而关键知识、权限仍锁在旧中心，也不足以叫自适应更新。H2区分载体、承担者、受益者、停止权与责任主体；H3区分反馈受理、相关字段改写和执行；H4核权力怎样影响观测；H5核留痕。按§4.5检验当前载体实际接续，只有另主张当前表示之外的历史增量才需要G3。岗位记忆的当前作用不因G3未证而自动消失。"],"distinctions":[{"leftTitle":"多线索成簇","leftText":"多个变化共同出现，可能共享动力或资料。","rightTitle":"多份独立支持","rightText":"须另核相应独立性；相依线索的联合验证可支持联合预测，但不会将其变成多份独立证据。"},{"leftTitle":"单信号有限预测","leftText":"可以在专业任务上有独立有效性。","rightTitle":"临界转变通用证明","rightText":"还需动力等条件，不因一信号可靠就成立。"},{"leftTitle":"较高PPV","leftText":"报警中的真实事件比例较高。","rightTitle":"较低总损失","rightText":"还取决于漏报、误报与行动成本及其权重。"},{"leftTitle":"有接班人","leftText":"人员名义已确定。","rightTitle":"实际承接","rightText":"知识、权限、资源、窗口和保护已匹配并执行。"},{"leftTitle":"当前岗位记忆作用","leftText":"可经当前载体影响运行。","rightTitle":"额外历史增量","rightText":"在当前表示之外另有预测或机制主张，才按G3检查。"}],"boundaries":["不用“没有两条信号”取消可靠的有限业务预测，不以未报警证明安全。","不把同源统计量当独立样本，也不否认相依线索的可用价值。","临界减速不是所有灾变的必要前兆，波动增大也不唯一指向临界接近。","预测目标和期限不能因响应或结果而事后改写；未发生与成功避免需分开。","实际承接不要求先证明G3，但不能只有名义接班；不以留痕数量认证有效学习。"],"questions":["a固定1/2、噪声方差从1增到3，方差变大能证明临界减速吗？","同源恢复、自相关和方差线索能否一起使用？","为什么B的PPV较高而本例L较大？","12小时提前量，顺序四段共14小时意味着什么？","岗位记忆已实际帮助接班，但G3未通过，能否否定该当前作用？"],"diagramPath":"/reading-assets/S-8-6/figures/section-8-6.png","caseLinks":[{"title":"CAIB区分经验数据库存在与实际使用","href":"https://govinfo.library.unt.edu/caib/news/report/pdf/vol1/chapters/chapter7.pdf"}],"caseNotes":[{"title":"CAIB区分经验数据库存在与实际使用","text":"2003年哥伦比亚事故调查报告印刷第189页说明，NASA的Lessons Learned Information System较易使用，可帮助危害识别和风险评价；熟悉该系统的人员反映设计工程师和任务保障人员只是临时按需使用，限制了其效用。本节据此把岗位经验载体的存在与实际进入工作流程分开。","sourceLabel":"Columbia Accident Investigation Board，Report Volume I，2003年8月","sourceUrl":"https://govinfo.library.unt.edu/caib/news/report/pdf/vol1/chapters/chapter7.pdf","sourceLocator":"第7章印刷第189页，项目“Lessons Learned Information System”及随后Conclusions","boundary":"这是调查报告中的使用状况描述，不证明无人使用、数据库无价值或某个改进必然避免事故；不据此给NASA判S5/S6或将全部事故原因归结于数据库。","href":"https://govinfo.library.unt.edu/caib/news/report/pdf/vol1/chapters/chapter7.pdf"}],"sourceRefs":[{"section":"8.6","start_line":1839,"end_line":1848,"startLine":1839,"endLine":1848}],"outputId":"section-8-6","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["登记对象、K、窗口、任务与目标，按调节六环节查实际运行，而非只取静态输出。","把四类可能预警、反向信号及其共同来源列出；保留有限单信号预测的独立资格。","核动力、噪声、采样和标签条件，在固定目标与实时基线上评价单独及联合规则。","分开PPV、漏报、误报与行动成本；评价预测和识别保护效果各用相应证据。","沿偿付链查承诺、承担、回流和未来负担，沿承接链查知识、权限、资源和进入窗口。","用H2—H5分别管理角色、写回、权力与留痕，当前载体作用与G3额外历史增量分别检验。","警报本身不产生处置授权；现实响应依已有或另行取得的有效授权与程序，继续核规范、保护及适用条件。"],"teachingExamples":[{"title":"数学构造：同一参数同时改变三种线索","text":"设平稳AR(1)模型y_(n+1)=a y_n+ε_n，|a|<1，噪声与过去独立、均值0、方差σ²。平稳方差V满足V=a²V+σ²，故V=σ²/(1−a²)；Cov(y_(n+1),y_n)=aV，所以滞后1相关为a。取σ²=1，a=1/2时V=4/3；a=4/5时V=25/9。无新噪声的单位偏离按a^n衰减，首次降至0.1以下分别在第4和第11步。三条变化来自同一a，不能算三次独立验证。若只把σ²从1改为3、保持a=1/2，则V变4而相关仍为1/2，表明方差增加还有噪声解释。","assumptions":"比较同一采样间隔、同一模型族；方差计算用各参数下平稳分布，恢复计算是无新噪声的条件响应，不混用随机样本轨迹。","boundary":"这是显式数学构造，不是组织数据；有限样本估计误差、非平稳性与实际分岔资格另查。"},{"title":"数学构造：PPV更高而指定损失更大","text":"虚构固定100个已完整标记窗口，其中20个有目标事件、80个无。规则A有TP=18、FP=18、FN=2、TN=62，PPV=18/36=1/2；更严格的联合规则B选中其中10个真事件和2个无事件，故TP=10、FP=2、FN=10、TN=78，PPV=10/12=5/6。设每次误报损失1、每次漏报10、每次报警另有行动成本0.2，总评分L=FP+10FN+0.2(TP+FP)。A的L=45.2，B的L=104.4。B的PPV更高，但在这些明示权重下总损失更高。","assumptions":"标签是已固定响应制度下的目标事件，未缺失；B为A报警子集且组成如上，未假设两信号独立；成本只是教学选择，不是社会公认权重。","boundary":"这是预测规则评分反例，不声称任何实际行动造成或避免了这些事件，也不证明B在其他权重下一定更差。"},{"title":"教学时间构造：提前发现仍可能来不及保护","text":"虚构离危险窗口还有12小时，核验2、触达理解3、筹资调度4、保护起效5小时，且本例规定四段必须依次完成。总耗时2+3+4+5=14小时，比可用时间多2小时；12小时算法提前量本身不足。若现实步骤可重叠，应改为相应关键路径计算，不能继续机械加总。","assumptions":"各段时长为构造常数，明确顺序依赖；未对现实群体作危险预测或干预。","boundary":"时间可行也不替代行动授权与保护适当性。"}],"counterexamples":[{"identity":"constructed_boundary","text":"三条指标来自同一序列，所以既是三份独立证据，又必须全部出现才可预警。","effect":"前半忽视相依，后半把成簇误设通用门槛；联合使用与单信号资格须分别判断。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"联合规则B的PPV从1/2升到5/6，所以它一定更值得采用。","effect":"本构造漏报增加，指定损失45.2升至104.4，不能只看一个比例。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"接班人名单和知识库都存在，说明已完成自适应更新。","effect":"还须实际知识可用、权限可达、交接窗口与执行材料；记录不自动变为运行。","sourceIds":["theory"]}],"questionAnswers":[{"question":"a固定1/2、噪声方差从1增到3，方差变大能证明临界减速吗？","answer":"不能，本模型相关与无噪声恢复率未变，方差增长由噪声幅度解释。","basis":"本节原文及上述公开推导"},{"question":"同源恢复、自相关和方差线索能否一起使用？","answer":"可以，但按联合模型或验证评价，不能凭三名称称三次独立实验。","basis":"本节原文及上述公开推导"},{"question":"为什么B的PPV较高而本例L较大？","answer":"B减少误报也漏掉更多事件；漏报权重10，损失增加超过误报和行动成本减少。","basis":"本节原文及上述公开推导"},{"question":"12小时提前量，顺序四段共14小时意味着什么？","answer":"在本构造下无法及时完成保护，还缺2小时；不是只要早发现就有效。","basis":"本节原文及上述公开推导"},{"question":"岗位记忆已实际帮助接班，但G3未通过，能否否定该当前作用？","answer":"不能，当前载体作用与当前表示之外的历史增量是两种主张，各按相应证据保留。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-6/figures/section-8-6.png","alt":"调节六环节，目标→感知→比较，执行→反馈＋时滞；预警线索，恢复慢、波动、后果、闪烁，成簇不等独立；偿付分布，谁承诺、承担、回流，谁被推迟到未来；共同参数教学构造，a：1/2→4/5，V：4/3→25/9；预测先固定，目标、期限、基线，标签与反向信号；承接需实际条件，知识、权限、资源、窗口，停止与保护；规则A（构造），PPV＝1/2，指定损失45.2；规则B（构造），PPV＝5/6，指定损失104.4；有限结论，不以未报警证明安全，不由预测生成授权。数值全为正文明确假设的数学构造；高PPV不保证低损失，知识留痕不保证实际承接。","caption":"数值全为正文明确假设的数学构造；高PPV不保证低损失，知识留痕不保证实际承接。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。九卡分出运行环节、来源依赖、评价目标、承接条件与非授权边界，不画未测得的现实趋势。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实组织的经验载体与实际使用差距对应本节承接/留痕区分；新预警推导另按数学模型身份展示。"},"openQuestions":["没有执行现实预警、调度或读者测试；任何组织的联合信号价值及实际承接效果均需其自身资料。"],"taskId":"S-8-6","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1839—1848行；每节精确范围见sourceRefs","claim_support":["8.6：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"warnings","title":"现行原文预警评价、时钟与响应边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§12.6第2547—2554行；§12.5相关第2524行；附录D.31第5017—5031行","claim_support":["8.6：预警与反向信号、响应制度、标签与避免损害、末端保护时延"],"limits":["预测与因果保护效果分别判断。"],"access_status":"read"},{"id":"interfaces","title":"现行原文H接口与当前载体/历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.2第586—600行；§4.5第620—640行；§8.4第1787—1810行","claim_support":["8.6：H2/H3分类不代经验实例；当前载体作用与G3增量分路；pseudo_steady是候选路径"],"limits":["不得由H分类或成簇线索补齐因果证据。"],"access_status":"read"},{"id":"scheffer","title":"Scheffer等：Early-warning signals for critical transitions","url":"https://pdodds.w3.uvm.edu/files/papers/others/2009/scheffer2009a.pdf","source_type":"primary","version_or_date":"2009-09-03，doi:10.1038/nature08227","locator":"Nature 461:53—59；本讲用印刷pp.53—55 Theory与Box3，pp.57—58 Outlook；完整主文pp.53—58已读","claim_support":["8.6：特定模型下恢复、自相关与方差关联；外部突变、扰动变化与有限观测带来的漏警误警限制；本文构造参考其AR(1)条件形式后独立推导"],"limits":["论文为原作者综述与理论讨论；未独立核其中每项引文研究，未以生态或生理实例验证组织原型。"],"access_status":"partially_read"},{"id":"caib","title":"CAIB Report Volume I第7章","url":"https://govinfo.library.unt.edu/caib/news/report/pdf/vol1/chapters/chapter7.pdf","source_type":"primary","version_or_date":"2003年8月","locator":"印刷第189页，Lessons Learned Information System段及Conclusions","claim_support":["8.6：数据库可辅助危害识别，相关人员报告临时按需使用限制效用"],"limits":["调查观察，不证明无人使用或某单项改进的事故避免效果；不构成S原型认证。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-6/lecture.md","sourcesPath":"/reading-assets/S-8-6/sources.json","sourceSlicePath":"/reading-assets/S-8-6/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-6/diagrams.md"},"8.7":{"title":"8.7　当前原型边界与排除项","lead":"一套标签最重要的边界，是知道什么时候不贴标签。七种原型可以帮助提出问题，却不能把所有集体排成高低，也不能因为卡片清楚、两个人同意，就宣布分类准确或对实际任务更有用。","explanation":["原文定位：第1849—1860行；原文锚点 section-8-7；短引文：‘七种原型不声称穷尽人类集体的全部状态’。本题源切片逐字附后，讲解与原文分开。","S0—S6是可反驳、允许缺失、并行和撤回的候选原型。每次使用都要逐项检查入口、退出、观察、反例、证伪、尺度、证据、缺失及非授权边界。标题相似或叙事动人不能替这些条件；资料不足时可以记录印象或未知，不必勉强选一个编号。","编号既不是连续量，也不规定从0到6的必经顺序。回退、并行、混合、跳跃、休眠、分裂、合并、接管、功能转移和崩解都有各自条件。先保留对象与尺度差异，再讨论路径；不能把复杂路径压成一条“成熟度”曲线。","X0是独立生命周期路径，任何已登记起点均可按自身条件检查，不要求S5、S6或其他最低编号。阶段能力、规范正当性和操作条件分开；即使一个原型匹配完整，也不提供解散、推进、淘汰或强制转换的权限。","物理隐喻要进入正式机制讨论，至少须有形式映射、量纲、可证伪预测和类比终止条件。要说清源领域的什么变量映到目标领域的什么对象、单位如何对应、什么结果会反驳、在什么情形停止沿用。四项齐备只是开始实质验证的必要准备，不是经验真值证书。","“量子隧穿”不能仅凭听来像“跳跃”就解释人类集体的跳跃转换。未观察中间配置可能来自采样稀疏，也可能来自别的过程；要识别通道，需直接的事件、规则与效应材料。若说先前失败尝试对当前表示之外的后续结果仍有额外历史增量，在本框架中须相应G3-instance；若失败经验已通过当前岗位记忆起作用，则依§4.5的当前载体路线分别检验，不能一概加G3。","生物死亡、社会更新、爱和传承之间没有预设的必然协作。代际承接可以研究角色、记忆、授权与交接接口，不必先说旧者必须死亡才能让新者成长；保护和责任也不能靠自然现象的类比来证明。组织X0不能变成个人死亡或哀伤阶段模型。","七原型不穷尽全部人类集体。若材料充分而持续无法匹配，要保留未解释残差，再用独立材料检验是否新增、合并或拆分；不能用更灵活的叙事让每个案例事后都命中。若只是材料缺失，则首先是判定未决，不应急于发明第八类。更新原型时保留版本与旧预测记录。","四种评价问题分开：原型匹配问本次是否符合卡片条件；观察者一致性问不同判断者是否得到相同结果；跨窗口稳定性问一定范围内是否重复；相对使用增益问它是否优于直接变量完成实际任务。一致判断可以一致地漏掉重要差异，稳定标签可以没有预测信息；动态对象变化也可能使合理分类不稳定。","清楚卡片提供可复核的条件和定位结构，但没有真实比较就不报告分类准确率、预测收益或阅读节省。若评估观察者一致性，应固定对象样本、资料版本、规则和盲法安排，记录分歧与缺失；若评估预测或时间收益，另需预先规定目标、基线、独立评价和适当不确定性，不能把同意率叫准确率。本讲没有实施此类人类评估。","若当前任务只需要成员、通道与负荷，直接联合这些变量即可，原型不是强制入口。删去无增益的标签是保持问题精确的一种选择，并不抹掉原有事实。相反，要主张原型有新增价值，需相同信息、资源和评价口径下的实际对照，不能让原型组额外拿到资料后把优势全归给名称。"],"distinctions":[{"leftTitle":"一致性","leftText":"不同观察者给相同标签。","rightTitle":"有效性","rightText":"标签是否符合目标构念及用途，不能由同意率推出。"},{"leftTitle":"跨窗稳定","leftText":"标签在所定窗口重复。","rightTitle":"信息增益","rightText":"是否改善固定任务，稳定常数也可能没有区分力。"},{"leftTitle":"资料缺失","leftText":"尚不能判断是否符合原型。","rightTitle":"未解释残差","rightText":"充分材料仍不能被现有原型解释，后续检验改分类。"},{"leftTitle":"形式映射与量纲一致","leftText":"类比得到可检查表达。","rightTitle":"现实机制成立","rightText":"还须区分性证据，不因方程形式相似而成立。"},{"leftTitle":"当前载体","leftText":"旧经历已写入现有可观测安排。","rightTitle":"额外历史增量","rightText":"给定当前表示后另有信息或作用，按G3承担责任。"}],"boundaries":["没有实际人类比较，就不能声称本卡片提高准确率、节省阅读时间或改善预测。","不把七类的数量当穷尽性证明，不因资料不足立即新增类型。","物理类比不能授权伤害、淘汰或强制转换；四项形式准备也不是机制的充分条件。","多观察者若共享同一材料，其一致性不是多份独立对象证据。","直接变量是合法分析入口，跳过原型不等于否认已支持的领域事实。"],"questions":["为何两个观察者两窗一致不保证预测更好？","三个对象缺记录，是否应马上创设新原型？","写出量纲一致方程后，现实机制是否已成立？","目标只是统计成员、通道、负荷，必须先给S标签吗？","失败尝试的影响已完全由当前岗位记忆解释，还需把它登记为G3历史增量吗？"],"diagramPath":"/reading-assets/S-8-7/figures/section-8-7.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"8.7","start_line":1849,"end_line":1860,"startLine":1849,"endLine":1860}],"outputId":"section-8-7","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["首先核对象适用、完整卡片条件与缺失身份，允许unknown及不使用原型。","将描述配置、路径、规范评价与现实权限拆开，拒绝发展阶梯和最高阶段退场门槛。","遇到物理比喻，要求明确映射、单位、反证与终止条件，再另查机制证据。","将当前载体作用与当前表示外历史增量分路，不能用失败叙事代G3。","对充分材料下的残差和缺失资料下的未决分别保留，独立检验分类修订。","分别评价匹配、一致、稳定与任务增益；在没有实际比较时不报告经验收益。","若直接变量足以完成任务，跳过原型并保留更简单且可核的表示。"],"teachingExamples":[{"title":"数学构造：一致又稳定的标签仍可没有任务增益","text":"设四种等概率情形，直接变量X依次为0、0、1、1，未来目标Y=X。为教学设定四情形都符合同一原型标签P，并且两个观察者在两个窗口均给这个标签，故本构造内同意率与标签重复率都为1。只知道常数标签P的概率预测只能取一个常数p，Brier期望损失为[p²+(1−p)²]/2=(p−1/2)²+1/4，最小为1/4；知道X并用p=X则损失为0。标签一致与稳定不能保证优于直接变量。","assumptions":"四情形概率、Y关系和原型匹配是显式构造前提，不是实际调查；只比较P标签包含的信息，不能偷偷把原型完整档案中的X也加给P预测器。","boundary":"同意率1不是现实分类准确率，更不是本课程的读者测试；这只反驳一致性足以推出预测增益的逻辑。"},{"title":"教学构造：两种“没归类”需要不同处理","text":"虚构十个已登记对象，七个有充分资料并匹配某原型，另三个暂未归类。若后三个缺关键记录，应标判定未决；若资料充分且逐项检查与所有现有原型均不相容，才可登记现有原型未解释的残差。两种情况下“归类七个”数字相同，后续工作却不同，不能都强塞进mixed。","assumptions":"十个和七个仅为教学数量；未声称现实七类覆盖率70%，也未把不归类当对象本身有缺陷。","boundary":"是否修改原型还需独立材料与版本规则，残差存在不自动要求新增一类。"},{"title":"形式构造：单位正确仍不能证明机制","text":"虚构队列更新q_(n+1)=max(0,q_n+a_n−s_n)，q是任务件数，a和s是本窗口进入与可处理件数。单位一致且含义明示，允许推导条件结果。若只把q称“组织能量”、把max称“隧穿”，没有给新的映射或可反驳后果，就没有增加解释。即使另有不同方程也用件数，仍需实际过程材料判断哪一个适用。","assumptions":"本例是离散教学模型，q、a、s的窗口和同质任务口径固定；不主张真实组织都按此规则运行。","boundary":"单位一致是必要检查，不是模型唯一性或现实因果证据。"}],"counterexamples":[{"identity":"constructed_boundary","text":"两位判断者100%同意，说明分类100%准确且节省时间。","effect":"同意、准确、时间收益分属不同评价，后两者没有材料。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"没有找到中间状态，所以人类集体发生了量子隧穿。","effect":"缺中间记录与证明机制不同，物理名称未提供目标映射或反证。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"三个未归类对象都叫mixed，七原型便覆盖所有对象。","effect":"mixed需正面共同特征；缺失与残差不能靠改名被消去。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为何两个观察者两窗一致不保证预测更好？","answer":"一致和稳定只约束标签关系；常数标签没有区分Y的信息，本构造最小Brier损失1/4而X预测为0。","basis":"本节原文及上述公开推导"},{"question":"三个对象缺记录，是否应马上创设新原型？","answer":"不应，先保留资料不足；充分资料持续无法匹配才构成检验修订的残差入口。","basis":"本节原文及上述公开推导"},{"question":"写出量纲一致方程后，现实机制是否已成立？","answer":"没有，还要核映射、区分性预测、证据及停止适用条件。","basis":"本节原文及上述公开推导"},{"question":"目标只是统计成员、通道、负荷，必须先给S标签吗？","answer":"不必，直接变量即可；原型若无新增用途可以跳过。","basis":"本节原文及上述公开推导"},{"question":"失败尝试的影响已完全由当前岗位记忆解释，还需把它登记为G3历史增量吗？","answer":"不能凭历史发生过就登记额外增量；当前载体作用单独保留，当前表示之外主张另需G3。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-7/figures/section-8-7.png","alt":"原型匹配，入口、观察、反例等，逐项检查；观察者一致，判断是否相同，不等于正确；跨窗口稳定，是否重复匹配，不等于任务增益；任务增益，相对直接变量的比较，无实测不报收益；缺资料／未解释残差，分别保留，不硬塞mixed；物理类比四要求，映射、量纲、可证伪预测，类比终止条件；构造：常数P，同意与重复率均1，最小Brier损失1/4；构造：直接X，Y=X，p=X，Brier损失0；可跳过原型，X0无最低S门槛，标签不授权。两个损失是四种等概率情形的数学构造，不是实际分类或读者试验；一致、稳定、有效分开。","caption":"两个损失是四种等概率情形的数学构造，不是实际分类或读者试验；一致、稳定、有效分开。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。九卡展示四种评价、残差、形式条件及一个反例，不将任何S编号画成价值阶梯。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节主要给出分类与类比的适用边界及评价责任，数学反例足以说明非蕴含；把无完整S判定的历史人物硬贴到此处反而误导。本题不声称已有真实准确率或使用收益。"},"openQuestions":["原型的观察者一致性、跨窗表现及相对直接变量的实际收益仍须专门研究，本讲没有执行真实读者或分类者实验。"],"taskId":"S-8-7","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1849—1860行；每节精确范围见sourceRefs","claim_support":["8.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"contracts","title":"现行原文适用域与状态最小合同","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.1第1629—1636行；§8.2—8.2.1第1637—1665行","claim_support":["8.7：原型适用对象、完整检查、mixed/parallel/unknown及缺失不互代"],"limits":["原文是定义与责任来源，不证明分类实际可靠。"],"access_status":"read"},{"id":"history","title":"现行原文当前载体与额外历史责任","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.5第620—640行","claim_support":["8.7：当前载体作用与G3额外历史增量不能互代"],"limits":["不由失败叙事产生支持。"],"access_status":"read"},{"id":"X0","title":"现行原文独立X0及个人死亡边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.5第1811—1838行；附录D.09第4665行","claim_support":["8.7：X0不是第八阶段，无最低S条件；组织退出不套个人死亡/哀伤"],"limits":["不授权现实退出或替人决定。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-8-7/lecture.md","sourcesPath":"/reading-assets/S-8-7/sources.json","sourceSlicePath":"/reading-assets/S-8-7/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-7/diagrams.md"},"8.8":{"title":"8.8　与行动者状态和多圈层推演的边界","lead":"一个人可以同时属于家、工作团队和兴趣圈，各处有不同角色与条件。集体的状态标签不能当作这个人的性格；一个人的能力也不能替整个集体证明承接和调节已经成熟。","explanation":["原文定位：第1861—1868行；原文锚点 section-8-8；短引文：‘外层制度变化不能自动刷新内层关系’。本题源切片逐字附后，讲解与原文分开。","本节给第八、九、十部分划清接口：第八部分描述有意图集体在指定对象合同下的候选配置；第九部分管理行动者慢、中、快变量；第十部分管理多个圈层及其关系。三类对象可以相互影响，但不能共用一个标签把层次差异删掉。","一个圈层匹配S2，只涉及它在所定K、尺度和窗口下的成员、分工、承接等必要特征，不意味着成员人格处于S2。反方向也不成立：某人有持续表现良好的能力，不说明所在集体具备S5或S6的整体条件。个体能力、可用资源、权限和组织通道分别可能限制结果。","行动者记录按§9.1保留ID、窗口、成员关系、角色、慢中快状态、物质与体验意义条件、未知、证据、隐私和用途。慢中快是相对于当前研究窗口的更新速度，不是三类人格，也不是把一次情绪永久化。跨时间稳定、跨情境稳定和一次行为分别需要不同材料；拒绝披露、无法观察和证据冲突也不能一概填成零。","同一人处在不同圈层时，角色、可见信息、风险、奖惩、资源和退出条件可能不同，行为差异不必先解释成虚伪或本质改变。但情境可能有作用也不是已经证明它是唯一原因；需要具体事件、通道与竞争解释，不能把个人选择完全消解为环境。","第十部分六类关系不是互斥的一层分类。平行看所声明维度上无包含；嵌套看明确维度上的实际包含；重叠看共同部分且彼此不完全包含；桥接看可识别传导接口；竞争看一方占用或规则如何改变另一方可用集合；临时看期限或短窗支持及结束条件。一个临时联盟可以同时重叠、竞争并桥接。共享成员不自动产生代表权，目标不同也不自动构成竞争。","多圈层联合记录应分别维护各圈层的边界、K、尺度、窗口和证据；不同圈层可同时匹配不同原型，不需强制同步成长。原文也允许同一圈层在不同尺度轴上出现混合的局部表现；操作时先保留各剖面和子系统的原始判断，再按§8.2决定正式mixed或parallel。正式mixed仍需同一对象、尺度和窗口下多个必要特征的正面材料；不能把跨口径冲突或不知道选什么直接改叫mixed。","状态变化必须绑定事件、通道、时钟和实际变化字段。外层制度发布可能改变正式规则，却还需查信息触达、内层权限、解释、资源和执行才能判断内层关系是否已改变。若任务就是外层规则文本，发布日期可以是相关完成时点；若任务是实际内层运行，不能用同一时点自动结案。","个体退出先改变相应成员或角色映射，并不自动使圈层K失效。需要核退出的是哪一个圈层、哪些角色、是否有替代及其实际条件；一人退出工作团队也不等于退出所有其他关系。反过来，若该人确为所定K的不可替代条件，退出也可能导致对象转换或解体，不能一律说“少一个人无所谓”。","当多个圈层只有共同环境而无可识别传导通道时，可以并列观察，不虚构相互影响；嵌套或重叠本身也不保证反馈。下行通知、上行报告与有效反馈分别核：后者需要返回并改变后续状态、转移概率或约束。任何跨层作用仍受容量、损失、时滞和保护限制。","如果原型相对直接变量没有增量价值，就以更简单的联合状态完成任务，例如保留成员/角色映射、通道、负荷、事件和时间。这里的“更简单”是按任务删去无用标签，不是删除隐私、未知或关键条件；也不把局部工作表示冒充完整MC*合同。原型使用与否由任务和证据决定，不用编号维护形式完整。"],"distinctions":[{"leftTitle":"集体候选原型","leftText":"指定K、尺度、窗口中的组织配置。","rightTitle":"个人状态与人格","rightText":"不同分析单位，需要个人与情境材料，不能套S编号。"},{"leftTitle":"个人稳定能力","leftText":"某任务与范围内的持续能力。","rightTitle":"集体S5/S6","rightText":"还涉及通道、承接、资源、反馈等完整条件。"},{"leftTitle":"成员重叠","leftText":"有共同成员，但各有自身范围。","rightTitle":"嵌套或有效桥接","rightText":"前者要求包含，后者要求传导接口，均不能由交集自动推出。"},{"leftTitle":"外层规则变化","leftText":"规则文本或管辖条件发生事件。","rightTitle":"内层运行更新","rightText":"还要实际触达、条件与执行证据。"},{"leftTitle":"个体退出","leftText":"某项成员或角色关系结束。","rightTitle":"集体解体","rightText":"需判断原K和承接，不能直接同步。"}],"boundaries":["S标签不评价人格、心理成熟度、道德或人的本质。","慢中快是窗口相关描述；一次行为不能填满个人长期状态。","不同圈层与尺度剖面可有不同结果，不能对S编号做算术平均。","同属某群体不证明认同其目标，共享成员不赋予代表所有人的权限。","外层变化与个体退出的影响可大可小或未知，需具体通道和K，不自动刷新全部状态。","没有相对使用增益时可不用原型，但不能因此删除已经独立支持的对象事实。"],"questions":["甲A={p,q,r}、乙B={r,s,t}的成员表共6项，独立人数是多少？","r退出甲后，何以本构造甲不解体？","同一人甲中输出4、乙中0，能推出能力不同或人格两阶段吗？","t0外层R=1、内层I=0是否矛盾？","不同尺度剖面结果不同，可直接平均S编号或写mixed吗？","原型对任务无新增价值，较合适的表示是什么？"],"diagramPath":"/reading-assets/S-8-8/figures/section-8-8.png","caseLinks":[{"title":"Fleeson用重复个体状态记录研究人格表现","href":"https://simine.com/407/readings/Fleeson_2001.pdf"}],"caseNotes":[{"title":"Fleeson用重复个体状态记录研究人格表现","text":"Fleeson在2001年论文研究1中安排46名大学生连续13天每天5次报告前一小时的行为与感受。这个设计把同一个人的不同时刻作为状态观测对象。本节据此说明个体状态研究的单位与窗口，不能把这种记录直接换成其所属集体的S原型。","sourceLabel":"William Fleeson，Journal of Personality and Social Psychology 80(6)，2001","sourceUrl":"https://simine.com/407/readings/Fleeson_2001.pdf","sourceLocator":"印刷第1014页，Study 1—Method—Participants及Procedure；第1015页Materials说明前一小时报告","boundary":"这里只用原研究的观测设计，不由46名学生推出全部人的状态规律，不据其自述推断集体阶段、心理诊断或某个现实人的人格；不声称本讲实施了该研究。","href":"https://simine.com/407/readings/Fleeson_2001.pdf"}],"sourceRefs":[{"section":"8.8","start_line":1861,"end_line":1868,"startLine":1861,"endLine":1868}],"outputId":"section-8-8","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先标清当前分析单位是行动者、单个意向性集体还是多圈层联合对象。","个体字段按第九部分记录，圈层原型按第八部分独立检查，禁止双向把标签外推。","分别登记成员/角色映射和六类关系的维度、方向、范围、证据与结束条件。","多剖面判断先保留原口径；mixed/parallel按其正式条件检查，未知不强行合并。","事件发生后只更新有通道与材料支持的字段，分别核外层文本、内层执行和关系后果的时钟。","个体退出后重新核相关K与承接，既不自动解体，也不自动保持。","比较任务收益；若直接变量足够，可跳过原型而保留必要合同、隐私与未知。"],"teachingExamples":[{"title":"集合构造：退出一处不等于所有圈层消失","text":"虚构圈层甲成员A={p,q,r}，乙成员B={r,s,t}。两集合交集只有r，并集有5人，而两个成员表条目合计6；若计算独立人数须去重。现r只退出甲，A变为{p,q}，B不变。教学预先规定甲的K要求至少两人、协调与执行岗位持续且必要接口资源不变；p、q分别保有两岗位，故本构造中甲继续满足K，不能从r退出推出甲解体。","assumptions":"K的这些条件在本模型内是完整判据，岗位、接口、资源及时间窗均按前提保持；未把单个人数阈值冒充现实完整合同。","boundary":"若真实K依赖r的不可替代权限，结论会不同；集合重叠也不证明r实际传递了信息。"},{"title":"数学构造：同一能力、不同可用条件","text":"设同一行动者的任务能力k=4件/窗口在两圈层相同，资源容量也均4。定义本教学任务有效输出y=min(k,资源容量)×j，其中j=1表示该任务已有许可，j=0表示未获许可且模型规定不执行。甲中j=1得到4，乙中j=0得到0。差异由本模型许可条件解释，不能反推个人能力4→0，也不能据甲的4件推出整个圈层S5或S6。","assumptions":"明确假设未获许可即不执行、任务同质同质量，且只有所列因素；j不由模型授权，而是外给构造条件。","boundary":"现实行为机制未必是此公式；禁止把输出为零一概归为权限问题。"},{"title":"教学时钟构造：发布与运行可相隔两个窗口","text":"虚构外层规则R在t=0从0改为1。模型设内层在t=2收到并完成解释，既有有效授权与资源允许收到后立即执行，于是内层运行字段I在t=0、1仍0，t=2变1。外层规则已变这个事实与内层尚未执行可以同时为真。若改为收到后仍缺资源，I的后续状态需另设，不能自动沿用原结果。","assumptions":"0/1是规定字段的两个值，不是价值等级；时延2及执行条件明确为构造，不是真实制度记录。","boundary":"这个演示不验证现实跨层机制，也不把所有外层规则都假定两窗口生效。"},{"title":"数学构造：相同均值不说明相同个体过程","text":"两个虚构个体的四次状态记录分别为(1,7,1,7)与(4,4,4,4)，均值都为4；按四个时点等权的总体方差，前者为9，后者为0。只保存均值会丢掉波动差异；这仍是个体状态记录，不是集体S阶段或心理诊断。","assumptions":"数值为假设的等距教学状态量，四时点同口径；未借用真实量表数据，也不声称四次足够估计终身特质。","boundary":"相同均值不证明两人相同，方差不同也不自动说明健康、能力或人格好坏。"}],"counterexamples":[{"identity":"constructed_boundary","text":"圈层已被判S2，因此其中每个人的人格也在S2。","effect":"分析单位混淆，集体原型不描述个人人格。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"制度已经发布，所以每个内层关系立即改变；某人退出，所以全部圈层同时解体。","effect":"两个跳跃都省略事件通道、权限资源、时延与K检查。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A与B共享r，所以A是B的子圈层，r有权代表两边。","effect":"交集不等包含，更不产生代表权限；本构造A、B彼此不包含。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"两个个体均值都4，所以他们的状态过程完全相同。","effect":"序列与方差不同，均值只是一个摘要，不可填满行动者描述。","sourceIds":["theory"]}],"questionAnswers":[{"question":"甲A={p,q,r}、乙B={r,s,t}的成员表共6项，独立人数是多少？","answer":"5人，因为r重复计入两表；成员身份记录与人数分母应分开。","basis":"本节原文及上述公开推导"},{"question":"r退出甲后，何以本构造甲不解体？","answer":"预先规定的完整K仍由p、q及持续岗位/接口/资源满足；真实情形须重新核这些条件。","basis":"本节原文及上述公开推导"},{"question":"同一人甲中输出4、乙中0，能推出能力不同或人格两阶段吗？","answer":"不能，本构造能力固定，许可条件不同；更无个人S阶段含义。","basis":"本节原文及上述公开推导"},{"question":"t0外层R=1、内层I=0是否矛盾？","answer":"不矛盾，两个字段与时钟不同，本构造t2才完成接收并执行。","basis":"本节原文及上述公开推导"},{"question":"不同尺度剖面结果不同，可直接平均S编号或写mixed吗？","answer":"不能，先保留各剖面；正式mixed需同一对象/尺度/窗口下多个必要特征支持，资料不足仍未决。","basis":"本节原文及上述公开推导"},{"question":"原型对任务无新增价值，较合适的表示是什么？","answer":"使用满足任务的直接联合变量，并保留对象、通道、时钟、证据、隐私和未知等必要条件。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-8-8/figures/section-8-8.png","alt":"行动者A*，慢／中／快变量，角色、条件、隐私；单个意向性集体，K＋尺度＋窗口，S原型候选；多圈层联合对象，成员映射＋关系通道，事件、多时钟、证据；教学甲，A={p,q,r}→{p,q}，构造K仍满足；教学乙，B={r,s,t}保持，退出一处≠全部退出；退出前重叠计数，表条目6，独立人数5，共享r不等包含；外层规则（构造），t=0已R=1，不自动刷新内层；内层运行（构造），t=0、1时I=0，t=2接收执行后I=1；任务允许更简单，可用直接联合变量，不以S评价个人。所有集合与时点为显式教学构造；跨层关系需实际通道，个体退出需另核圈层K。","caption":"所有集合与时点为显式教学构造；跨层关系需实际通道，个体退出需另核圈层K。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。九卡分出三种对象和两个不同教学情境，没有画未经识别的现实因果箭头。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实重复测量研究能具体展示个体状态的分析单位；本节新增观察点是它不能越级成为集体原型或多圈层关系证据。"},"openQuestions":["现实跨层变化与退出影响仍需各自K、事件、通道、执行及保护材料；本题没有对真实个人作人格推断。"],"taskId":"S-8-8","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1861—1868行；每节精确范围见sourceRefs","claim_support":["8.8：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"actor","title":"现行原文行动者记录与三时间带","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第九部分导语及§9.1—9.2.3，第1869—1920行","claim_support":["8.8：A*字段、慢中快更新、情境差异与隐私未知"],"limits":["三时间带不是三类人格，个体记录不证明集体原型。"],"access_status":"read"},{"id":"multi","title":"现行原文多圈层联合合同及六类关系","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§10.1—10.4，第2034—2116行，尤其10.2 MC*及10.3六类关系","claim_support":["8.8：各圈层K与成员映射分别保留；六类非互斥关系；无通道不虚构直接影响"],"limits":["圈层范围不限意向性集体，S原型另需其自身适用域。"],"access_status":"read"},{"id":"prototype","title":"现行原文mixed/parallel与原型收益边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§8.2第1637—1665行；§8.7第1849—1860行；§3.1第425—448行","claim_support":["8.8：正式mixed/parallel条件、K身份、允许跳过无增益原型"],"limits":["跨剖面差异不直接合并成正式mixed，也不平均编号。"],"access_status":"read"},{"id":"fleeson","title":"Fleeson：Traits as Density Distributions of States","url":"https://simine.com/407/readings/Fleeson_2001.pdf","source_type":"primary","version_or_date":"2001，doi:10.1037//0022-3514.80.6.1011","locator":"JPSP 80(6):1011—1027；本讲事实定位pp.1014—1015 Study 1 Method及Materials","claim_support":["8.8：研究1为46学生、13天每日5次前一小时行为感受记录的观测安排"],"limits":["安排次数不等每人实际完成次数；不外推现实个人、群体阶段或集体机制。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-8-8/lecture.md","sourcesPath":"/reading-assets/S-8-8/sources.json","sourceSlicePath":"/reading-assets/S-8-8/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-8-8/diagrams.md"}}},"headers":[],"relativePath":"theory/part-08.md","filePath":"theory/part-08.md"}'),n={name:"theory/part-08.md"};function c(u,t,p,_,m,h){const e=i("SectionLesson");return o(),d("div",null,[t[0]||(t[0]=s('<div class="theory-source"><p><a id="part_8"></a></p><h1 id="part-title-8" tabindex="-1"><span class="xk-part">第八部分<span class="xk-part__gap">　</span></span>人类状态原型 <a class="header-anchor" href="#part-title-8" aria-label="Permalink to &quot;第八部分　人类状态原型 {#part-title-8}&quot;">​</a></h1></div>',1)),a(e,{section:"intro-08-part"}),t[1]||(t[1]=s('<div class="theory-source"><h2 id="section-8-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.1</span><span class="xk-num__gap">　</span></span>本部分解释什么 <a class="header-anchor" href="#section-8-1" aria-label="Permalink to &quot;8.1　本部分解释什么 {#section-8-1}&quot;">​</a></h2><p>S0—S6 只适用于人类有意图集体：人们围绕可表达的共同问题、承诺、目标或意义安排形成，并通过角色、资源、规则、关系和反馈持续运作的团队、组织、机构、运动、共同体或治理安排。它们不是普适定律，不能直接套到个体人格、纯物理系统、物种演化或宇宙整体。即使在适用域内，S0—S6 也不是成熟度阶梯，不是历史必经序列，更不是价值排名。</p><p>编号只用于区分原型和方便检索。它允许我们问：“这个对象、这个子系统、这个时间窗，现在主要呈现什么结构构型？”它不允许我们说：“编号更大，所以人更好、制度更正当、文明更先进。”一个大型集体可以中心为 S5、边缘为 S3、技术单元为 S6、代际承接仍为 S1；同一功能也可以同时呈现两种原型。遇到这种情况，应登记 parallel 或 mixed，而不是把复杂性压成一个“整体阶段”。</p><p>状态原型只产生描述性、可撤回的分类。它不产生行动授权。任何现实干预都必须另行给出规范前提，通过 C12，比较包括不行动在内的方案，取得覆盖具体主体、对象、动作、地域和期限的 J 原子授权，并接受 O 程序、申诉与回滚。状态标签不能替这些门作证。</p></div>',1)),a(e,{section:"8.1"}),t[2]||(t[2]=s('<div class="theory-source"><h2 id="section-8-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.2</span><span class="xk-num__gap">　</span></span>状态判断的最小合同 <a class="header-anchor" href="#section-8-2" aria-label="Permalink to &quot;8.2　状态判断的最小合同 {#section-8-2}&quot;">​</a></h2><p>每次判断都先冻结对象 object_id、同一性判据 K、九轴尺度剖面 SP=&lt;A,X,T,O,C,R,I,N,J&gt;、时间窗和子系统范围，然后分别记录入口条件、退出条件、可观察量、反例、证伪结果与缺失。分类模式只有四种：single_dominant、mixed、parallel、unknown。这里冻结的是本次分析用来追踪对象的判据，不要求被观察的成员构成、实际边界、角色、承诺或自我认同已经稳定。若需要改变K的定义，应另建有版本的记录，保留原判据、材料和判断，并重新核对对象同一性；核对未完成前，不将不同K下的记录直接接成同一对象的跨窗路径。</p><div class="xk-table"><table><thead><tr><th>字段</th><th>必须回答的问题</th><th>停止位置</th></tr></thead><tbody><tr><td>对象与 K</td><td>我们追踪的是同一个人类集体，还是名称相同、对象已变？</td><td>K未冻结、无法据其追踪对象或同一性尚未核清时，先做对象与同一性判断，不分配原型；成员或实际边界变化不自动等于K改变</td></tr><tr><td>尺度与时间</td><td>哪些单位、空间、窗口、层级、影响位置和网络被看见？</td><td>观察范围扩大不扩大 J 授权</td></tr><tr><td>入口与退出</td><td>什么材料使某原型成为候选，什么材料使它不再主导？</td><td>“像”一个原型不等于已经进入或必然退出</td></tr><tr><td>可观察量</td><td>哪些行为、记录、通道、成本、恢复与写回能被复核？</td><td>单一口号、总量或官方自述不足</td></tr><tr><td>反例与证伪</td><td>还有什么会产生相同表象？什么结果会撤回判断？</td><td>不主动找反证的标签只能算印象</td></tr><tr><td>证据覆盖</td><td>哪些外部材料支持入口、观察与反证判断？证据能否解析并覆盖当前对象？</td><td>内部定义、编号和框架叙述均不能替代对象证据</td></tr><tr><td>缺失</td><td>是未收集、不可观察、不适用、冲突还是未知？</td><td>不得把缺失补成“正常”“没有”或零值</td></tr><tr><td>规范与行动</td><td>该分类是否给出价值、义务或处置权？</td><td>全部状态均为 descriptive_only、action_authorization=none</td></tr></tbody></table></div><p>五种缺失状态必须分开。not_collected 表示可取得但尚未收集；not_observable 表示当前权限、安全或测量条件下不可观察，不能要求弱势主体为填表而暴露；not_applicable 必须经过适用性检查；conflicted 表示合格来源互相冲突；unknown 表示已经尝试仍不能区分。关键入口、反证或尺度字段缺失本身，只支持 unknown 或暂停相关分类；mixed 和 parallel 须分别有多个原型及其对应位置的正向证据，不得把无知改名为混合。已经成立的局部材料仍按原范围保留。</p></div>',1)),a(e,{section:"8.2"}),t[3]||(t[3]=s('<div class="theory-source"><h3 id="section-8-2-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.2.1</span><span class="xk-num__gap">　</span></span>运行时分类记录 <a class="header-anchor" href="#section-8-2-1" aria-label="Permalink to &quot;8.2.1　运行时分类记录 {#section-8-2-1}&quot;">​</a></h3><p>原型卡只有进入封闭的运行时记录，才构成可复核分类。记录必须同时冻结 record_id、对象与同一性标准、九轴尺度、时间窗、子系统范围、分类模式、候选状态、路径候选、五类条件结果、缺失数据、对象证据、不确定性、独立复核、申诉、回滚以及非授权边界。每一项入口、退出、观察、反例和证伪结果都使用同一结构：item_id + state_id + status + evidence_refs + reason；结果必须逐项覆盖候选原型，不能用一段总评代替。</p><p>single_dominant 恰有一个候选；mixed 与 parallel 至少各有两个候选并显式登记对应路径；unknown 不指定已获支持的原型，必须说明哪些关键材料仍不足以区分；已经成立的局部事实和组件观察保留在对象证据中，不能因总体原型未知而删除。运行记录若不容许在 unknown 的候选条件栏存放支持项，应将这些材料保留在对象证据及理由中，不伪造完整原型。任一候选至少要有入口和观察项的对象证据；一旦某个证伪项为 supported，该候选即被阻断，不能靠降低措辞强度继续保留。每次验证都必须另行提供外部 evidence_ids 注册表，记录内每一层 evidence_refs 既要解析到本记录的对象证据，也要递归解析到该外部注册表；省略注册表、顶层自报或幽灵引用均不能通过。内部编号、定义和自报判断不能替代对象证据。</p><p>复核者记录为 reviewer_id + independent + reviewed_at + material_version + outcome，申诉和回滚各自绑定结构化程序 ID 与状态。reviewer_id 经 NFKC、首尾空白与大小写规范化后不得等于对象 ID，也不得使用对象 ID 派生别名；换一个字符串不能把对象自身变成独立复核者。它们不能写成“已复核”“可申诉”之类自我声明字符串。无论复核结果如何，记录恒为 normative_status=descriptive_only、action_authorization=none：撤回或改写状态标签时，应保留原证据、异议与版本链。</p><p>U、H、G、C 编号在本部分有四种不同作用：U 提供对象、状态、通道、负荷和相位接口；H 提供人类世界中的意义、承接、制度写回、权力和历史载体适配；G 指明何时必须用独立合格实例把模式升级为经验机制；C 限制推论的停止位置。它们是合同链接，不是眼前对象的证据。</p><p>S0—S6 的配置描述不以 CM-PHASE 的多区间模式为前提。一个对象在已观察窗口中始终满足单一原型的必要条件，也可以取得相应的有限分类；它没有因此证明曾发生相位转移。进一步主张多区间、阈值或相位转移机制时，再按 CM-PHASE 及相应 G 实例检查。反过来，两区间形式模式成立，也不直接证明符合某个人类集体原型。</p></div>',1)),a(e,{section:"8.2.1"}),t[4]||(t[4]=s('<div class="theory-source"><h2 id="section-8-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3</span><span class="xk-num__gap">　</span></span>S0—S6 状态原型 <a class="header-anchor" href="#section-8-3" aria-label="Permalink to &quot;8.3　S0—S6 状态原型 {#section-8-3}&quot;">​</a></h2></div>',1)),a(e,{section:"8.3"}),t[5]||(t[5]=s('<div class="theory-source"><h3 id="section-8-3-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3.1</span><span class="xk-num__gap">　</span></span>S0　锚点凝聚原型 <a class="header-anchor" href="#section-8-3-1" aria-label="Permalink to &quot;8.3.1　S0　锚点凝聚原型 {#section-8-3-1}&quot;">​</a></h3><p>S0 描述的是“候选集体正在形成”，不是“低级组织”。共同问题、候选目标或意义表达开始聚拢注意、关系、时间和少量资源，但成员构成、实际边界、角色、承诺方式与共同身份的表达仍在形成或变化。分析仍须使用本次冻结且可据以追踪对象的K；形成中的状态变化不替代同一性判断。至少一个候选生成行动者反复进行翻译、召集、试探或承担真实成本，独立承接层尚未形成。候选集体可以在这里消散、休眠、并入其他安排或转向新的目标；各路径的发生比例须有相应机会总体和观察资料，不能由原型定义推定。过程结束本身不构成失败判决。</p><div class="xk-table"><table><thead><tr><th>检查面</th><th>S0 诊断卡</th></tr></thead><tbody><tr><td>入口</td><td>S0-E1：在本次冻结且可据以追踪对象的K下，共同问题或意义安排造成可见局部聚集，但成员、实际边界或承诺方式尚未稳定。S0-E2：候选生成行动反复出现，承接尚薄。</td></tr><tr><td>退出</td><td>S0-X1：在同一K仍适用且对象同一性可追踪的窗口内，锚点、实际边界和生成角色跨窗稳定，并出现可追踪承诺与初步承接，可检 S1。S0-X2：聚集消散、分裂、被吸收或进入休眠，不必经过 S1；原K不再适用时，另做对象转换或终止判断。</td></tr><tr><td>可观察</td><td>S0-O1 竞争表述仍在协商；S0-O2 资源聚集伴随高进出；S0-O3 生成行动者承担翻译、召集或试错；S0-O4 失败试探与备选历史仍被保留。</td></tr><tr><td>反例</td><td>热点或平台推荐能制造短期同步；行政命名能制造形式团队。要观察奖励、曝光或命令撤除后，承诺和对象边界是否仍持续。</td></tr><tr><td>证伪</td><td>与匹配临时聚集相比，共同方向、行动聚集与生成角色都无区别，则撤回 S0。若稳定角色、承接与重复运行早已存在，S0 也不是主导状态。</td></tr><tr><td>尺度</td><td>必须区分生成者、早期参与者、潜在退出者与外部命名者；不能把个体人格聚合成集体状态。</td></tr><tr><td>证据升级</td><td>意义安排造成资源、行动或协调差异须 H1-instance；指定通道造成形成须 G2-instance；历史留痕按 H5，当前载体的未来作用按§4.5；当前表示之外的历史增量才追加 G3。</td></tr><tr><td>合同链接</td><td>U01/U02/U03/U08/U09/U11；H1/H2/H5；G1/G2/G3；C1/C2/C4/C5/C10/C12。</td></tr></tbody></table></div><p>S0 允许的结论只是在特定对象、尺度和窗口内与锚点凝聚原型相容。它不能证明参与者缺乏能力、价值或意愿，也不能授权扶持、解散、筛选或排除。</p></div>',1)),a(e,{section:"8.3.1"}),t[6]||(t[6]=s('<div class="theory-source"><h3 id="section-8-3-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3.2</span><span class="xk-num__gap">　</span></span>S1　生成核心奠基原型 <a class="header-anchor" href="#section-8-3-2" aria-label="Permalink to &quot;8.3.2　S1　生成核心奠基原型 {#section-8-3-2}&quot;">​</a></h3><p>S1 中，候选锚点、对象边界和至少一个生成角色已经能跨决策重复识别，基本规则、语言、资源通道和最早记忆载体开始奠基。主要翻译、决策、资源动员、冲突处理或关系修复仍集中在一个或少数生成角色，独立承接者很少。中心性是结构依赖，不是领导正当性的证明。</p><div class="xk-table"><table><thead><tr><th>检查面</th><th>S1 诊断卡</th></tr></thead><tbody><tr><td>入口</td><td>S1-E1：K、锚点和生成角色可重复识别。S1-E2：关键功能持续依赖生成核心，而非一次紧急集中。</td></tr><tr><td>退出</td><td>S1-X1：新进入者形成持续承接、责任与边界接口，可检 S2。S1-X2：生成核心分裂、退出、被接管、休眠或对象消散，转入相应路径。</td></tr><tr><td>可观察</td><td>S1-O1 锚点和边界初步稳定；S1-O2 关键决策依赖生成核心；S1-O3 规则和记忆载体开始重复；S1-O4 外部进入有限且定向。</td></tr><tr><td>反例</td><td>成熟组织可能仍由创始人公开宣布决定，但实际承接层已庞大；行政新设部门也可能只是上级对象的角色单元。要追踪实际执行、停止权、反馈和核心暂时离场后的运行。</td></tr><tr><td>证伪</td><td>生成核心低介入时，多中心承接仍稳定运行，则核心依赖被反驳。若锚点不稳定，但同一K仍适用且对象可追踪，可重新检验S0；若原K不再适用或对象同一性不明，应先检查对象转换或终止，或保持unknown，再对可识别对象分类。</td></tr><tr><td>尺度</td><td>冻结生成角色、早期承接者、上级命名者与外部支持者；组织图与实际通道冲突时记 conflicted。</td></tr><tr><td>证据升级</td><td>锚点或生成核心的结果效应分别需要 H1/G2；早期制度或创伤的载体效应依§4.5，留痕检 H5，历史条件残差另检 G3。</td></tr><tr><td>合同链接</td><td>U01/U02/U03/U04/U06/U07/U09/U11；H1/H2/H3/H4；G1/G2/G3；C1/C2/C3/C5/C9/C10/C11/C12。</td></tr></tbody></table></div><p>S1 不能被读成“幼稚”“落后”或“应被整合”。它不能赋予生成者永久领导、扩大权力、强制建制或替换他人的资格。</p></div>',1)),a(e,{section:"8.3.2"}),t[7]||(t[7]=s('<div class="theory-source"><h3 id="section-8-3-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3.3</span><span class="xk-num__gap">　</span></span>S2　首次扩展与承接分化原型 <a class="header-anchor" href="#section-8-3-3" aria-label="Permalink to &quot;8.3.3　S2　首次扩展与承接分化原型 {#section-8-3-3}&quot;">​</a></h3><p>S2 描述边界、成员、服务对象、地域、平台接口或协作网络的持续扩展。新进入者带来不同理解、技能、资源和风险，生成核心之外开始形成承接、退出、保留异议与未决参与位置。扩张既可能提高协调能力，也会增加翻译、反馈、恢复和权力问题。分歧本身不是失稳；只有可观察机制持续阻断承接、反馈或恢复，才能谈结构问题。</p><div class="xk-table"><table><thead><tr><th>检查面</th><th>S2 诊断卡</th></tr></thead><tbody><tr><td>入口</td><td>S2-E1：至少一类边界持续扩展并改变关系。S2-E2：生成核心之外出现可区分承接、成本、退出与未决位置。</td></tr><tr><td>退出</td><td>S2-X1：重复负荷和压力形成连通约束、持续分割通道，可检 S3。S2-X2：扩展停止、回撤、跳跃、分裂、合并、接管、休眠或崩解。</td></tr><tr><td>可观察</td><td>S2-O1 进入/退出和接口构成变化；S2-O2 角色与责任分化；S2-O3 反馈量、翻译成本、时滞和恢复需求变化；S2-O4 认同、异议、退出与安全被分别记录。</td></tr><tr><td>反例</td><td>人数或用户数增长不一定改变结构；冲突公开也可能是表达安全改善，使旧问题终于可见。</td></tr><tr><td>证伪</td><td>冻结统计口径后，增长不持续且不改变边界、角色、责任、接口或负荷，则撤回 S2。若所谓分化只来自中心单方标签，也应撤回。</td></tr><tr><td>尺度</td><td>整体、中心、新承接者、退出者和外部化成本必须同时进入；观察范围扩大不增加对新成员的 J 权限。</td></tr><tr><td>证据升级</td><td>扩展或通道造成结果差异须 G2/CAUSAL；跨尺度另经 D3/E5，闭合或转换主张另检 G4；锚点协调须 H1；表达、公开与权力的观测效应须 H4；历史留痕须 H5，载体传递按§4.5，历史条件残差另检 G3。</td></tr><tr><td>合同链接</td><td>U01/U02/U03/U04/U06/U07/U08/U09/U11；H1/H2/H3/H4/H5；G1/G2/G3/G4；C1/C2/C3/C4/C5/C6/C7/C9/C10/C11/C12。</td></tr></tbody></table></div><p>S2 不允许把不认同、退出或模糊参与者本身命名为负向主体，也不允许用“扩维需要”授权统一思想、限制退出或清退异议。</p></div>',1)),a(e,{section:"8.3.3"}),t[8]||(t[8]=s('<div class="theory-source"><h3 id="section-8-3-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3.4</span><span class="xk-num__gap">　</span></span>S3　连通约束下的发展原型 <a class="header-anchor" href="#section-8-3-4" aria-label="Permalink to &quot;8.3.4　S3　连通约束下的发展原型 {#section-8-3-4}&quot;">​</a></h3><p>S3 中，集体仍在运行或发展，但多个重复约束已经彼此连通：审批、资源、信任、责任、信息、平台或外部依赖形成互相放大的瓶颈，持续分割反馈、承接、恢复或成本回流。这里的关键不是“问题很多”，而是问题能否形成可复核的连通结构；也不是把某个人命名为壁垒。</p><div class="xk-table"><table><thead><tr><th>检查面</th><th>S3 诊断卡</th></tr></thead><tbody><tr><td>入口</td><td>S3-E1：至少两类约束相互强化并跨窗影响通道。S3-E2：运行仍继续，但末端承接、反馈、资源或恢复承担持续额外负荷。</td></tr><tr><td>退出</td><td>S3-X1：关键关系、权限、资源或接口开始实际重构，可检 S4。S3-X2：转入回退、虚稳态、休眠、接管、强制重写、迁移或崩解。</td></tr><tr><td>可观察</td><td>S3-O1 约束网络与瓶颈；S3-O2 输出仍有而损耗、返工、隐性劳动增加；S3-O3 修复反复启动却不写回；S3-O4 中心/边缘、指标/承接、名义/实际持续分裂。</td></tr><tr><td>反例</td><td>高风险环境的保护性分层和冗余可能提高可靠性；主动降载重构也可能暂时放慢产出。必须检查限制是否阻断必要反馈，或提供错误隔离与替代路径。</td></tr><tr><td>证伪</td><td>去除共同输入、测量偏差和短期峰值后，约束之间无连通关系，或承接末端的替代通道、写回和恢复持续有效，则 S3 不是主导。</td></tr><tr><td>尺度</td><td>必须拆分中心、边缘、功能单元、承接末端和外部受影响位置，允许 parallel。弱信号消失不能当问题消失。</td></tr><tr><td>证据升级</td><td>权力/中介遮蔽须 H4；指定通道与相互强化须 G2；历史形成的当前约束按§4.5，额外历史残差检 G3；跨尺度闭合失败须 G4。</td></tr><tr><td>合同链接</td><td>U02/U03/U05/U06/U07/U08/U09/U10/U11；H1/H2/H3/H4/H5；G2/G3/G4；C2/C3/C4/C5/C6/C7/C9/C10/C11/C12。</td></tr></tbody></table></div><p>S3 分类不能授权“打壁垒”、清洗、接管、强制改革或把过渡成本交给弱势位置。它只说明应继续区分约束网络与竞争解释。</p></div>',1)),a(e,{section:"8.3.4"}),t[9]||(t[9]=s('<div class="theory-source"><h3 id="section-8-3-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3.5</span><span class="xk-num__gap">　</span></span>S4　结构重构窗口原型 <a class="header-anchor" href="#section-8-3-5" aria-label="Permalink to &quot;8.3.5　S4　结构重构窗口原型 {#section-8-3-5}&quot;">​</a></h3><p>S4 不是“改革已经正确”，而是关键结构确实处于重构窗口：旧关系、权限、资源通道、反馈写回或边界接口正在被拆解、替换或绕开，新旧安排并存，转换成本、重复劳动、知识迁移、短期产出下降和恢复需求上升。结果仍然开放，可能改善，也可能停滞、异化、强制重写或崩解。</p><div class="xk-table"><table><thead><tr><th>检查面</th><th>S4 诊断卡</th></tr></thead><tbody><tr><td>入口</td><td>S4-E1：至少一个关键字段实际改变，不只是改名或宣传。S4-E2：旧新安排并存，过渡成本可追踪，K 持续核对。</td></tr><tr><td>退出</td><td>S4-X1：跨窗改善通道、反馈、承接与恢复且无隐藏外包，可检 S5。S4-X2：新结构不可用，转入休眠、回退、接管、强制重写、虚稳态或崩解。</td></tr><tr><td>可观察</td><td>S4-O1 权限/资源/角色/责任/停止条件真实写回；S4-O2 双重系统和转换成本；S4-O3 缓冲、冗余、冷却、停止与回滚；S4-O4 多位置结果进入真实反馈。</td></tr><tr><td>反例</td><td>大规模改名、换人或重画流程图可能是象征改革；拆旧、过载和产出下降也可能是破坏性清洗或资源抽离。</td></tr><tr><td>证伪</td><td>实际关系、权限、资源和执行没有改变，则撤回 S4。不存在可用新结构且功能持续断裂时，也不能把过程包装为改善性重构。</td></tr><tr><td>尺度</td><td>变更前基线、过渡、冷却、回滚和恢复窗均要覆盖；改革发起者、执行者、承接者与成本承担者分开。</td></tr><tr><td>证据升级</td><td>重构导致改善/伤害须 G2/CAUSAL；对象或干预转换须 G4；失败尝试是否经当前载体影响未来按§4.5，额外历史残差另检 G3，不能用“隧穿”类比代替。</td></tr><tr><td>合同链接</td><td>U03/U05/U06/U07/U09/U10/U11；H1/H2/H3/H4/H5；G2/G3/G4；C2/C3/C4/C5/C6/C7/C9/C10/C11/C12。</td></tr></tbody></table></div><p>“过渡谷地”最多是待检的描述，不能为无限代价、不可逆伤害、取消申诉或牺牲低权力位置提供正当性。S4 不产生拆除、清洗或强制迁移的行动授权。</p></div>',1)),a(e,{section:"8.3.5"}),t[10]||(t[10]=s('<div class="theory-source"><h3 id="section-8-3-6" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3.6</span><span class="xk-num__gap">　</span></span>S5　高效协调与弹性扩展原型 <a class="header-anchor" href="#section-8-3-6" aria-label="Permalink to &quot;8.3.6　S5　高效协调与弹性扩展原型 {#section-8-3-6}&quot;">​</a></h3><p>S5 描述在当前环境和时间窗内，资源、信息、反馈、责任、承接和恢复通道能够较低损耗地协同，局部扰动通常不能形成持续连通壁垒，边界扩展与收缩较有弹性。它仍可能被资源红利、成本外包、沉默、指标漂白或制度漏洞伪造。因此，高产出不是充分证据，长期存续也不是正当性的证明。</p><div class="xk-table"><table><thead><tr><th>检查面</th><th>S5 诊断卡</th></tr></thead><tbody><tr><td>入口</td><td>S5-E1：关键通道跨窗低损耗、可替代、可写回。S5-E2：扩展、存护与消解协同，且不靠封闭反馈或压制异议。</td></tr><tr><td>退出</td><td>S5-X1：分布式承接、自我更新、恢复和新生成跨扰动成立，可检 S6。S5-X2：漏洞、异化、虚稳态、回退、功能转移、X0、接管或崩解使其不再主导。</td></tr><tr><td>可观察</td><td>S5-O1 替代承接与通道真实可用；S5-O2 产出、反馈、恢复和维护同时保持；S5-O3 边界开放、保护与退出可执行，成本回流；S5-O4 漏洞审计能写回。</td></tr><tr><td>反例</td><td>资源繁荣、选择性指标、投诉渠道失效、恐惧服从或把维护债推到未来，都能制造“成功”外观。</td></tr><tr><td>证伪</td><td>纳入维护、恢复、退出和外部成本后效率优势消失，或中心低介入时局部故障迅速级联，则撤回 S5。</td></tr><tr><td>尺度</td><td>管理层总量必须拆到维护者、低权力承接者、退出者和外部影响位置；覆盖高低负荷、扰动、恢复与维护窗。</td></tr><tr><td>证据升级</td><td>高效协调成因与漏洞效应须 G2/H4；历史留痕、载体持续作用与额外残差分别按 H5、§4.5 与 G3；跨尺度复制须 D3/E5 映射与独立目标证据；闭合或转换主张另检 G4。</td></tr><tr><td>合同链接</td><td>U01—U11；H1/H2/H3/H4/H5；G1/G2/G3/G4；C1—C12。</td></tr></tbody></table></div><p>S5 不是“善”“成熟”或“可以输出模式”的标签。存续、增长和筛选不等于正当，也不能授权扩张、复制、接管或要求成员增加承担。</p></div>',1)),a(e,{section:"8.3.6"}),t[11]||(t[11]=s('<div class="theory-source"><h3 id="section-8-3-7" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.3.7</span><span class="xk-num__gap">　</span></span>S6　自适应动态平衡原型 <a class="header-anchor" href="#section-8-3-7" aria-label="Permalink to &quot;8.3.7　S6　自适应动态平衡原型 {#section-8-3-7}&quot;">​</a></h3><p>S6 描述集体拥有分布式承接、有效反馈、恢复、更新和新生成能力。常规波动不会长期锁定方向，自治单元能局部自稳、横向协同并获得上级兜底，候补梯队、岗位记忆、授权和交接使后来者能真正进入并修改旧安排。它通过持续校准维持功能，不是消灭波动。</p><div class="xk-table"><table><thead><tr><th>检查面</th><th>S6 诊断卡</th></tr></thead><tbody><tr><td>入口</td><td>S6-E1：中心低介入时，多个位置仍能感知、纠错、恢复和写回。S6-E2：新承接者、规则与边界可持续更新，不依赖同一批不可替代个体。</td></tr><tr><td>退出</td><td>S6-X1：恢复变慢、波动放大、写回失效、中心依赖或承接断裂，转入回退等路径。S6-X2：使命结束、功能转移、分裂、合并、范式替换或 X0 改变对象合同。</td></tr><tr><td>可观察</td><td>S6-O1 扰动后的恢复与二次失稳；S6-O2 多中心协同与兜底；S6-O3 新承接者从训练到真实接管；S6-O4 反馈、审计、申诉与规则修订持续闭环。</td></tr><tr><td>反例</td><td>强控制、弱信号消失、资源保护或中心隐性救火都能制造低波动；频繁换人和改组也可能只是人员耗材化。</td></tr><tr><td>证伪</td><td>可比扰动下恢复持续变慢、局部故障级联、纠错依赖单点，或继任者得不到知识、权限和保护，则撤回 S6。</td></tr><tr><td>尺度</td><td>需要跨扰动、恢复、继任和慢变量长窗；整体平均不能掩盖边缘伤害。冻结自治、横向协同、上级兜底与实际授权。</td></tr><tr><td>证据升级</td><td>调节、反馈和多中心安排的效果须 G2/CAUSAL；学习、制度记忆和代际承接先核载体保留及实际接续；留痕检 H5，额外历史增量检 G3；跨尺度外推须 D3/E5 与独立目标证据；闭合或转换主张另检 G4。</td></tr><tr><td>合同链接</td><td>U01—U11；H1/H2/H3/H4/H5；G1/G2/G3/G4；C1—C12。</td></tr></tbody></table></div><p>S6 不是绝对终态、无冲突社会或历史终点。它可以回退、分裂、被接管、转移功能、进入 X0 或崩解；它也不能替任何对象取得对他者的决策权。</p></div>',1)),a(e,{section:"8.3.7"}),t[12]||(t[12]=s('<div class="theory-source"><h2 id="section-8-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.4</span><span class="xk-num__gap">　</span></span>非线性路径库 <a class="header-anchor" href="#section-8-4" aria-label="Permalink to &quot;8.4　非线性路径库 {#section-8-4}&quot;">​</a></h2><p>状态原型只有与路径库一起使用才不会退回阶段论。路径描述“状态配置或对象合同怎样变化”，不描述“更好的人怎样升级”。同一窗口可以有多个路径候选；证据不足时保持 unknown。</p><div class="xk-table"><table><thead><tr><th>路径 ID</th><th>含义</th><th>关键区分</th></tr></thead><tbody><tr><td>mixed</td><td>同一对象、尺度和窗口中，两种以上原型的必要特征共同出现。</td><td>若差异能稳定映射到独立子系统，应登记 parallel。</td></tr><tr><td>parallel</td><td>不同地域、层级、功能或中心/边缘同时处于不同状态。</td><td>不能压成“整体阶段”；各子系统分别留 K、证据和退出条件。</td></tr><tr><td>jump</td><td>相邻观察窗从一个配置转到非相邻配置，中间原型无可辨识持续窗。</td><td>先排除采样过稀和资料缺失；登记跳过的功能、代价和未知。</td></tr><tr><td>regression</td><td>相对同一对象自身基线，一个或多个功能退化。</td><td>分突发、渐进、临界跳变和级联；主动降载、X0 或功能转移不是回退。</td></tr><tr><td>split</td><td>原对象分成两个以上具有不同 K 的候选对象。</td><td>临时项目分组和模块化未必改变对象；每个新对象重新登记。</td></tr><tr><td>merge</td><td>多个对象形成一个新对象或被一方吸收。</td><td>联盟不必是合并；弱势方边界、记忆、退出与遗留责任必须单列。</td></tr><tr><td>dormancy</td><td>可见活动降低，但记忆、关系、符号、能力或再激活条件仍保存。</td><td>区分保护性撤离、耗竭停滞、资料消失与真实崩解。</td></tr><tr><td>takeover</td><td>外部主体取得关键资源、权限或接口控制。</td><td>外部支持或监管若保留真实自主与停止权，不必是接管。</td></tr><tr><td>functional_transfer</td><td>核心功能转到另一对象，功能可连续而原身份、关系或记忆消失。</td><td>外包单项任务不等于转移；功能连续不证明责任和记忆连续。</td></tr><tr><td>paradigm_replacement</td><td>旧对象未被修复，而被不同 K、接口或规则的新对象绕过。</td><td>同一对象内部升级或品牌改名不必是范式替换；遗留义务仍在。</td></tr><tr><td>trauma_built_development</td><td>边界、身份、规则或承接方式在伤害、剥夺、失败或威胁下形成。</td><td>创伤叙事不自动证明未来效应；保护与复制原始伤害须分别检验。</td></tr><tr><td>pseudo_steady</td><td>表面指标稳定，实际承接耗竭、弱信号消失、反馈不写回或债务上升。</td><td>建立表面/实际双账本，回到成本、恢复、停止权和末端反馈。</td></tr><tr><td>forced_rewrite</td><td>高权力主体在缺少可纠错同意、退出和记忆保护时重写对象。</td><td>与有授权、可撤回、可申诉的协商修订分开；检查不可逆身份抹除。</td></tr><tr><td>external_carrier_migration</td><td>修复封闭时，把人员、能力、资源、关系、证据或记忆移到更安全承接系统。</td><td>无接收能力、浪漫化离开或把伤害私有化，不构成安全迁移。</td></tr><tr><td>collapse</td><td>原 K 不再成立，功能、承接、关系或边界非计划性断裂。</td><td>与 X0、功能转移、保护性休眠和对象重组分开；资源释放不使伤害正当。</td></tr></tbody></table></div><p>路径名也不产生价值或责任。例如，regression 不是道德堕落，split 不必然失败，merge 不必然进步，takeover 不是自动非法，external_carrier_migration 也不是要求个体自行逃离。路径只是让竞争解释进入记录；机制、正当性与行动仍需各自合同。</p></div>',1)),a(e,{section:"8.4"}),t[13]||(t[13]=s('<div class="theory-source"><h2 id="section-8-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.5</span><span class="xk-num__gap">　</span></span>X0 有序退场与良性消亡 <a class="header-anchor" href="#section-8-5" aria-label="Permalink to &quot;8.5　X0 有序退场与良性消亡 {#section-8-5}&quot;">​</a></h2><p>X0 不是第八状态，也不是 S7；它不计作第八阶段。它是一条独立的人类集体生命周期路径：当继续维持原对象不再服务已登记锚点，核心功能可完成、终止或被更安全承接，并且人员、关系、资源、记忆、债务与申诉能被明确处理时，记录对象如何收束使命、转移功能、释放资源、保存记忆、结清责任并保留受限弱连接。</p><p>X0 不要求 S5 或 S6。S0 的临时倡议可以在发现问题已由他处承接时有序关闭；S2 的扩展项目可以在继续扩张只会制造伤害时收束；S3 的受困机构也可能在修复不可行而外部承接充分时进入退场。反过来，S6 也不能凭“高阶”标签宣布自己有资格解散。阶段能力、规范正当性和操作条件是三件事，任何状态编号都不能成为主动退场的资格前提。</p><p>机器合同用 origin_policy 把这条边界封闭为 any_registered_origin：不设最低状态前提，required_state_ids 为空，s5_or_s6_prerequisite 恒为 false。X0 的入口与完成条件不得引用 S0—S6 作为资格；编号只能说明出发位置，不能变成退场门槛。</p></div>',1)),a(e,{section:"8.5"}),t[14]||(t[14]=s('<div class="theory-source"><h3 id="section-8-5-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.5.1</span><span class="xk-num__gap">　</span></span>X0 候选入口 <a class="header-anchor" href="#section-8-5-1" aria-label="Permalink to &quot;8.5.1　X0 候选入口 {#section-8-5-1}&quot;">​</a></h3><p>第一，锚点已完成、失去适用性、被更安全对象承接，或继续维持已主要服务于组织自身存续。这个判断必须能被独立复核，不能靠中心改写目标后自证完成。第二，人员、功能、资源、关系、记录、债务与不可替代价值已经形成清单，并存在可核验的接收方或保护安排。短期挫折、资金紧张、领导疲倦或责任逃避都可能制造相似表象，因此只满足叙述不能进入“良性完成”。</p></div>',1)),a(e,{section:"8.5.1"}),t[15]||(t[15]=s('<div class="theory-source"><h3 id="section-8-5-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.5.2</span><span class="xk-num__gap">　</span></span>X0 完成条件 <a class="header-anchor" href="#section-8-5-2" aria-label="Permalink to &quot;8.5.2　X0 完成条件 {#section-8-5-2}&quot;">​</a></h3><div class="xk-table"><table><thead><tr><th>完成面</th><th>必须保存的内容</th><th>失败信号</th></tr></thead><tbody><tr><td>锚点与对象</td><td>完成、终止或失效的独立验证；K 的结束时间与尚未结案项</td><td>改写目标、删除失败项、中心单方宣布完成</td></tr><tr><td>核心功能</td><td>每项标为完成、终止、转移或未决；接收方能力、权限、资源与回滚</td><td>只有宣告，没有维护者或使用者连续性</td></tr><tr><td>人员与关系</td><td>安全、基本权益、停止权、不被报复、照护与依赖关系承接</td><td>把组织义务私有化为成员自行承担</td></tr><tr><td>资源</td><td>对象、边界、顺序、时间和去向可追踪，防止高权力截留</td><td>先内部瓜分，再把损失留给低权力位置</td></tr><tr><td>记忆与证据</td><td>成功、失败、修复、岗位记忆均保存；访问、隐私、纠错和反报复明确</td><td>只保留胜利史，删除或暴露弱势材料</td></tr><tr><td>债务与责任</td><td>合同、劳动、数据、维护、环境、申诉和未来风险有持续责任主体</td><td>对象一注销，责任、复核和维护同步消失</td></tr><tr><td>弱连接</td><td>只提供咨询、经验与缓冲，边界和期限明确</td><td>未经新授权复活原权力结构</td></tr></tbody></table></div><p>X0 的结果至少应区分“候选”“进行中”“部分完成”“完成”和 unknown。只要受影响群体、遗留义务、接收能力、申诉或记忆安全仍为未知，就不能写“良性完成”。功能转移却没有记忆与责任连续，可能只是 functional_transfer；外部权力单方关闭并改写身份，可能是 takeover 或 forced_rewrite；无承接断裂则是 collapse，不能用“有序退场”美化。</p><p>X0 分类不产生解散、裁撤、资产转移、公开档案、放弃债务或代表成员同意的授权。它只能告诉我们：如果要判断退场是否有序，必须把哪些对象、义务、证据、保护和未知放到同一张账上。</p></div>',1)),a(e,{section:"8.5.2"}),t[16]||(t[16]=s('<div class="theory-source"><h2 id="section-8-6" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.6</span><span class="xk-num__gap">　</span></span>调节、预警与承接如何进入状态判断 <a class="header-anchor" href="#section-8-6" aria-label="Permalink to &quot;8.6　调节、预警与承接如何进入状态判断 {#section-8-6}&quot;">​</a></h2><p>状态不是靠静态截图判定。调节层要求观察目标、感知、比较、执行、反馈与时滞；预警层要求比较恢复变慢、波动放大、同类扰动后果加重和局部闪烁是否成簇；偿付层要求追踪谁承诺、谁承担、谁回流、谁被推迟到未来。S5 或 S6 的表面稳定若建立在账外劳动、沉默和未来债务上，应转为 pseudo_steady 候选。</p><p>同一序列或共同变化通道产生的多条线索，不因成簇就成为多份独立证据。相依线索仍可联合使用，其预警价值须在相符的动力、噪声、采样与观察窗口下，按固定目标、期限、实时基线和反向信号评价（Scheffer等，2009；参见D.31、§12.6）。</p><p>成簇不是预警的通用准入条件。单个业务信号也可能足以支持有限判断；缺少临界减速或第二条信号，既不证明安全，也不取消已有专业预测。联合规则需要联合分布或相应验证，其阳性预测值上升还不保证给定误报、漏报与行动成本下的总损失下降。</p><p>承接也不能只看“有没有接班人”。需要看候补梯队、影子岗位、岗位记忆、授权路径、交接窗口、合法性转译和保护条件是否实际存在。生成者退出干净而承接者无法进场，会形成权威真空；频繁换人而关键知识、权限仍锁在原中心，也不是自适应更新。这里使用 H2 区分承接载体、成本承担者、受益者、停止权与责任主体，使用 H3 判断反馈是否真的改写字段并执行，使用 H4 检查权力与观测通道，使用 H5 核留痕，按§4.5检验载体实际接续；如另主张当前表示之外的历史增量，再检 G3。</p></div>',1)),a(e,{section:"8.6"}),t[17]||(t[17]=s('<div class="theory-source"><h2 id="section-8-7" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.7</span><span class="xk-num__gap">　</span></span>当前原型边界与排除项 <a class="header-anchor" href="#section-8-7" aria-label="Permalink to &quot;8.7　当前原型边界与排除项 {#section-8-7}&quot;">​</a></h2><p>S0—S6 是一组可反驳、可缺失、可并行、可撤回的人类集体状态原型。每个候选都必须逐项检查入口、退出、观察、反例、证伪、尺度、证据、缺失和非授权边界；缺少这些条件时，只能保留为印象或未知。编号不表示从 0 到 6 的普遍演化路线，状态之间允许回退、并行、混合、跳跃、休眠、分裂、合并、接管、功能转移与崩解。</p><p>X0 是独立生命周期路径，不以 S5、S6 或任何最低状态为前提。阶段能力、规范正当性和退场操作条件必须分别判断；任何原型匹配都不能自行产生解散、推进、淘汰或强制转换授权。</p><p>缺少形式映射、量纲、可证伪预测和类比终止条件的物理隐喻不进入正式机制库。例如，“量子隧穿”不能解释人类集体为何跳跃转换；在本框架中将失败尝试登记为当前注册状态之外的历史条件增量，仍须由相应G3-instance支持（参见§4.5）。生物死亡与社会更新、爱与传承之间也不预设必然协作；代际承接只按角色、记忆、授权与交接接口记录。</p><p>七种原型不声称穷尽人类集体的全部状态。案例若持续落在原型之外，应先保留未解释残差，再依据独立材料检验是否需要新增、合并或拆分原型，而不是把案例硬塞进编号。</p><p>原型匹配、观察者间一致性、跨窗口稳定性及相对直接变量的使用增益是不同问题。清楚的卡片可以提高可复核性，却不证明分类已经可靠或比专业描述更有效。未取得实际比较时，不报告准确率、预测收益或阅读节省；若任务只需直接描述成员、通道和负荷，可以跳过原型。</p></div>',1)),a(e,{section:"8.7"}),t[18]||(t[18]=s('<div class="theory-source"><h2 id="section-8-8" tabindex="-1"><span class="xk-num"><span class="xk-num__n">8.8</span><span class="xk-num__gap">　</span></span>与行动者状态和多圈层推演的边界 <a class="header-anchor" href="#section-8-8" aria-label="Permalink to &quot;8.8　与行动者状态和多圈层推演的边界 {#section-8-8}&quot;">​</a></h2><p>S0-S6 描述的是有意图集体在指定对象合同下的候选状态，不描述个人人格、心理成熟度或道德等级。行动者的慢、中、快变量由第九部分管理；多个集体的平行、嵌套、重叠、桥接、竞争与临时关系由第十部分管理。一个人所属圈层被分类为 S2，不意味着该人的人格处于 S2；一个人表现出稳定能力，也不意味着其圈层处于 S5 或 S6。</p><p>多圈层推演可以让不同圈层同时处于不同原型，也可以让同一圈层在不同尺度轴上呈现混合状态。状态变化必须绑定事件、通道和时间窗；外层制度变化不能自动刷新内层关系，个体退出也不自动造成集体解体。若原型分类相对于直接变量没有增量价值，应跳过原型，使用更简单的联合状态。</p></div>',1)),a(e,{section:"8.8"}),t[19]||(t[19]=l("div",{class:"theory-source"},null,-1))])}const g=r(n,[["render",c]]);export{b as __pageData,g as default};
